      "search_planner"        => false,
      # 0.7.3. How many plies the search planner looks ahead. 1 is the 0.7.2 grid --
      # this turn, then score the board. 2 answers each of those boards with the
      # safest reply grid from it, which is what makes a kill the foe can only
      # postpone by switching still count. Read only when search_planner is on.
      "search_depth"          => 2,
      # 0.7.5. THE OPPONENT MODEL, in one number, applied to the root rows only. 0 is
      # the original's pick_safest: an action is worth the worst the foe can reply
      # with. 1 values it at the EXPECTED reply instead -- the weights of the reply
      # the adapter predicts (foe_oracle, foe_stock_model), or uniform over the foe's
      # options when nothing is predicted. Between the two is a blend. Measured with
      # the stock model: 0.5 is 46/60 and 1.0 is 44 against 40 at 0; uniform weights
      # lose (29 / 28). Read only when search_planner is on; 0 reproduces 0.7.4.
      "search_foe_mix"        => 0.5,
      # 0.7.8. STEER BY HOW HARD THE FOE'S MOVES HIT. Both planners weight the foe's
      # columns; with this off, the mass that is not a predicted switch is shared
      # evenly over every move the foe owns. That even split is measurably wrong: on
      # the 0.7.7 5000-iteration arm the cell's max-damage incoming move was the move
      # the foe actually registered on 51.7% of 925 decisions, while the tree's own
      # most-visited foe column was right on 43.1% -- so the free prior beats the
      # model each planner built for itself. On the maximin this redistributes
      # column_weights within the stay group; on the tree it adds a PUCT term to the
      # foe axis of UCB1. It never moves mass between staying and switching, and it
      # needs no opponent-model producer. Read only when search_planner is on.
      "search_foe_prior"      => false,
      # 0.7.5. Predict the foe's reply with the engine's OWN AI: the withdraw
      # triggers of pbEnemyShouldWithdrawEx? read without their dice (as a chance),
      # its switch target, and the top of pbGetMoveScore. Exports through the same
      # fields the oracle does (predicted_foe and friends), so every consumer of a
      # prediction reads it alike and its number is judged against the oracle's
      # ceiling. Not cheating -- it reads no registered choice -- but it is a model
      # of stock v16, and a human does not switch on stock's triggers. Off.
      "foe_stock_model"       => false,
      # 0.7.6. WHICH SEARCH. False is 0.7.5's maximin grid over the joint own x foe
      # payoff (pick_safest, the legacy poke-engine path) and reproduces it decision
      # for decision. True routes the same board through a decoupled simultaneous-move
      # MCTS instead (search.rb, THE TREE), which is what poke-engine and Foul Play
      # run today: the foe's line is shaped by its own payoff over many iterations
      # rather than by the one predicted-reply number search_foe_mix blends in --
      # and neither search_foe_mix nor the predicted reply is read on that path.
      # Read only when search_planner is on.
      "search_mcts"           => false,
      # 0.7.6. The MCTS budget, as an ITERATION COUNT and not a time: a paired run and
      # its shadow twin must make the same decisions on the same board, and a clock
      # would make that depend on the machine. The gauntlet is a study harness, not a
      # move clock, so this may be raised until it stops paying. Read only when
      # search_mcts is on.
      "search_iterations"     => 1000,
      # 0.7.6. Mixed into the per-decision seed of the MCTS chance sampler. The seed is
      # otherwise the position itself, so a decision replays from its snapshot; this is
      # how the same position can be asked twice for a different tree. Read only when
      # search_mcts is on.
      "search_seed"           => 0
    }

    def self.config(overrides)
      out = {}
      DEFAULT_CONFIG.each { |k, v| out[k] = v }
      (overrides || {}).each { |k, v| out[k.to_s] = v }
      out
    end

    def self.validate(snapshot)
      raise ArgumentError, "snapshot must be a Hash" if !snapshot.is_a?(Hash)
      actors = snapshot["actors"]
      targets = snapshot["targets"]
      raise ArgumentError, "snapshot actors must be a non-empty Array" if !actors.is_a?(Array) || actors.empty?
      raise ArgumentError, "snapshot targets must be an Array" if !targets.is_a?(Array)
      actors.each do |actor|
        raise ArgumentError, "actor must be a Hash" if !actor.is_a?(Hash)
        raise ArgumentError, "actor index missing" if actor["index"].nil?
        actions = actor["actions"]
        raise ArgumentError, "actor actions must be an Array" if !actions.is_a?(Array)
        actions.each do |action|
          validate_action(action)
        end
      end
      true
    end

    def self.validate_action(action)
      raise ArgumentError, "action must be a Hash" if !action.is_a?(Hash)
      kind = action["type"]
      raise ArgumentError, "unknown action type #{kind.inspect}" if kind != "move" && kind != "switch"
      raise ArgumentError, "action slot missing" if action["slot"].nil?
      if kind == "move"
        raise ArgumentError, "move id missing" if action["move_id"].nil?
      end
      true
    end

    def self.number(value, fallback)
      return fallback if value.nil?
      value.to_f
    rescue
      fallback
    end

    def self.truthy(value)
      value == true || value == 1 || value == "1" || value == "true"
    end

    def self.copy_hash(source)
      out = {}
      (source || {}).each { |k, v| out[k] = v }
      out
    end
  end
end
# ===== END portable_ai/model.rb =====

# ===== BEGIN portable_ai/effects.rb =====
# Canonical move knowledge keyed by internal move ID, never by Essentials function code.
# Adapters convert PBMoves::FOO / GameData IDs to the uppercase String "FOO".

module PortableAI
  module Effects
    TABLE = {}

    # Tags accumulate: a move may be listed by more than one call (Explosion is both
    # a spread move and a self-KO), so the table is order-independent.
    def self.add(ids, tags)
      ids.each do |id|
        known = TABLE[id] || []
        merged = known.clone
        tags.each { |tag| merged << tag if !merged.include?(tag) }
        TABLE[id] = merged
      end
    end

    # "heal" alone is the flat half-HP recovery the core assumes. The two refinements
    # exist because the 0.4.0 heal gate asks whether healing outruns the incoming hit,
    # which needs the amount: Rest refills completely, and the weather heals pay only
    # a quarter in sand or hail.
    add(%w[RECOVER ROOST SOFTBOILED MILKDRINK SLACKOFF
           HEALORDER SHOREUP], ["heal"])
    add(%w[MOONLIGHT SYNTHESIS MORNINGSUN], ["heal", "heal_weather"])
    add(%w[REST], ["heal", "heal_full", "self_sleep"])
    add(%w[WISH], ["delayed_heal"])
    add(%w[PAINSPLIT], ["variable_heal"])

    # Defensive setup was missing entirely: the list was offensive boosts only, so
    # Iron Defense and Amnesia were scored as plain unknown status moves. Curse is
    # here for the non-Ghost form; the adapter's own type check keeps the Ghost form
    # (which costs half the user's HP) out.
    add(%w[SWORDSDANCE NASTYPLOT DRAGONDANCE QUIVERDANCE CALMMIND
           BULKUP COIL SHELLSMASH GEOMANCY TAILGLOW
           AGILITY ROCKPOLISH AUTOTOMIZE WORKUP GROWTH
           IRONDEFENSE AMNESIA COSMICPOWER ACIDARMOR BARRIER STOCKPILE
           HONECLAWS CURSE DEFENDORDER], ["setup"])
    add(%w[BELLYDRUM], ["setup", "hp_cost_half"])

    # 0.6.5. WHAT each setup move actually raises, so a boost can be priced by what
    # it changes rather than by a flat bonus (Core.setup_matrix_value). Every id
    # carrying the "setup" tag above has a row here and a test asserts it, because a
    # missing row silently falls back to the flat 55 and nothing would say so.
    #
    # Stat keys are the core's own short names, not engine constants: "atk", "def",
    # "spa", "spd", "speed". Drops are negative -- Shell Smash pays two defences for
    # its three boosts and Curse pays speed, and a rule that only read the boosts
    # would call both of them free.
    SETUP_STAGES = {
      "SWORDSDANCE"  => { "atk" => 2 },
      "NASTYPLOT"    => { "spa" => 2 },
      "TAILGLOW"     => { "spa" => 3 },
      "DRAGONDANCE"  => { "atk" => 1, "speed" => 1 },
      "QUIVERDANCE"  => { "spa" => 1, "spd" => 1, "speed" => 1 },
      "CALMMIND"     => { "spa" => 1, "spd" => 1 },
      "BULKUP"       => { "atk" => 1, "def" => 1 },
      "COIL"         => { "atk" => 1, "def" => 1 },
      "HONECLAWS"    => { "atk" => 1 },
      "WORKUP"       => { "atk" => 1, "spa" => 1 },
      "GROWTH"       => { "atk" => 1, "spa" => 1 },
      "CURSE"        => { "atk" => 1, "def" => 1, "speed" => -1 },
      "SHELLSMASH"   => { "atk" => 2, "spa" => 2, "speed" => 2,
                          "def" => -1, "spd" => -1 },
      "GEOMANCY"     => { "spa" => 2, "spd" => 2, "speed" => 2 },
      "BELLYDRUM"    => { "atk" => 6 },
      "AGILITY"      => { "speed" => 2 },
      "ROCKPOLISH"   => { "speed" => 2 },
      "AUTOTOMIZE"   => { "speed" => 2 },
      "IRONDEFENSE"  => { "def" => 2 },
      "ACIDARMOR"    => { "def" => 2 },
      "BARRIER"      => { "def" => 2 },
      "AMNESIA"      => { "spd" => 2 },
      "COSMICPOWER"  => { "def" => 1, "spd" => 1 },
      "STOCKPILE"    => { "def" => 1, "spd" => 1 },
      "DEFENDORDER"  => { "def" => 1, "spd" => 1 }
    }

    # The engine's own stage table as ratios (085_PokeBattle_AI.rb:2932 holds the same
    # numbers as numerator/denominator pairs). Index is the absolute stage; a drop is
    # the reciprocal, which is what the engine's pair table spells out row by row.
    STAGE_MULT = [1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 4.0]

    add(%w[SOLARBEAM SOLARBLADE], ["charge_solar"])
    add(%w[PROTECT DETECT KINGSSHIELD SPIKYSHIELD BANEFULBUNKER
           OBSTRUCT SILKTRAP BURNINGBULWARK], ["protect"])
    add(%w[SUBSTITUTE], ["substitute"])

    # Status kinds let adapters derive immunity facts (burn vs Fire-types, poison vs
    # Steel, powder vs Grass, paralysis vs Electric). "typed_status" marks moves whose
    # own type immunity blocks them (Thunder Wave vs Ground) — Glare deliberately lacks
    # it because modern engines let it hit Ghost-types.
    add(%w[THUNDERWAVE], ["status", "paralyze", "typed_status"])
    add(%w[GLARE], ["status", "paralyze"])
    add(%w[STUNSPORE], ["status", "paralyze", "powder"])
    add(%w[WILLOWISP], ["status", "burn"])
    add(%w[TOXIC], ["status", "poison"])
    add(%w[POISONPOWDER], ["status", "poison", "powder"])
    add(%w[SPORE SLEEPPOWDER], ["status", "sleep", "powder"])
    add(%w[HYPNOSIS DARKVOID], ["status", "sleep"])
    # Yawn puts the target to sleep NEXT turn by writing PBEffects::Yawn, so it fails
    # against an already-drowsy target while pbCanSleep? still says yes. It carries its
    # own tag purely so the adapter's status_blocked? can find it without a move-name
    # lookup -- the same shape as "drain" on LEECHSEED below.
    add(%w[YAWN], ["status", "sleep", "drowsy"])
    add(%w[CONFUSERAY SWAGGER FLATTER], ["status", "confuse"])
    add(%w[LEECHSEED], ["status", "drain"])
    add(%w[TAUNT ENCORE TORMENT DISABLE HEALBLOCK PSYCHICNOISE], ["disrupt"])
    add(%w[HAZE CLEARSMOG], ["reset_stages"])

    add(%w[STEALTHROCK SPIKES TOXICSPIKES STICKYWEB], ["hazard"])
    add(%w[RAPIDSPIN DEFOG MORTALSPIN TIDYUP], ["hazard_remove"])
    add(%w[REFLECT LIGHTSCREEN AURORAVEIL SAFEGUARD MIST], ["screen"])

    add(%w[UTURN VOLTSWITCH FLIPTURN PARTINGSHOT TELEPORT], ["pivot"])
    add(%w[ROAR WHIRLWIND DRAGONTAIL CIRCLETHROW], ["force_switch"])
    add(%w[BATONPASS], ["baton_pass"])
    add(%w[TRICK SWITCHEROO KNOCKOFF CORROSIVEGAS], ["item_control"])
    # Knock Off alone actually REMOVES the item; Trick and Switcheroo swap it, which
    # is a different trade the core does not price. Reborn's knockcode (:8072) is a
    # short whitelist and nothing else, so the tag exists to reach that one rule.
    add(%w[KNOCKOFF], ["item_removal"])

    add(%w[FOLLOWME RAGEPOWDER SPOTLIGHT], ["redirect"])
    # 0.5.0 tables. "speed_control" is anything that changes who moves first;
    # "field_speed" narrows that to the two whole-turn investments, which are the only
    # ones with a "already active, do not repeat" case. "first_turn_only" and
    # "delayed_damage" each need one engine fact (turncount, effect_active) that the
    # adapter now exports. "partner_heal" is a move that does nothing at all in
    # singles.
    add(%w[TRICKROOM TAILWIND STICKYWEB ICYWIND ELECTROWEB ROCKTOMB
           BULLDOZE ICESPINNER], ["speed_control"])
    add(%w[TRICKROOM TAILWIND], ["speed_control", "field_speed"])
    add(%w[FAKEOUT FIRSTIMPRESSION], ["first_turn_only"])
    add(%w[FUTURESIGHT DOOMDESIRE], ["delayed_damage"])
    add(%w[HEALPULSE POLLENPUFF LIFEDEW FLORALHEALING], ["partner_heal"])
    add(%w[HELPINGHAND COACHING DECORATE], ["partner_support"])
    add(%w[WIDEGUARD QUICKGUARD MATBLOCK CRAFTYSHIELD], ["team_protect"])

    add(%w[EARTHQUAKE SURF DISCHARGE SLUDGEWAVE BOOMBURST EXPLOSION
           SELFDESTRUCT LAVAPLUME PETALBLIZZARD BULLDOZE], ["spread", "friendly_fire"])
    add(%w[ROCKSLIDE HEATWAVE DAZZLINGGLEAM MUDDYWATER BLIZZARD
           ICYWIND RAZORLEAF AIRSLASH SNARL TWISTER], ["spread"])
    add(%w[FAKEOUT EXTREMESPEED AQUAJET BULLETPUNCH MACHPUNCH
           ICESHARD SHADOWSNEAK SUCKERPUNCH VACUUMWAVE], ["priority"])

    # Moves that pay for their damage. "self_drop" wrecks the user's own offence for
    # the rest of the turn cycle; "self_ko" ends the user outright. Reborn charges
    # both (selfstatdrop :6118, deathcode :7779) and Portable over-used every move on
    # these two lists relative to it.
    add(%w[DRACOMETEOR OVERHEAT LEAFSTORM PSYCHOBOOST FLEURCANNON
           SUPERPOWER CLOSECOMBAT VCREATE HAMMERARM DRAGONASCENT], ["self_drop"])
    add(%w[EXPLOSION SELFDESTRUCT FINALGAMBIT MEMENTO HEALINGWISH
           LUNARDANCE], ["self_ko"])

    # 0.7.2. WHAT each self_drop move actually costs, the same shape as SETUP_STAGES,
    # so a search projection can charge Superpower's Attack and Draco Meteor's Special
    # Attack rather than pricing the two kills identically. Every id carrying
    # "self_drop" above has a row here and a test asserts it.
    SELF_DROP_STAGES = {
      "DRACOMETEOR"  => { "spa" => -2 },
      "OVERHEAT"     => { "spa" => -2 },
      "LEAFSTORM"    => { "spa" => -2 },
      "PSYCHOBOOST"  => { "spa" => -2 },
      "FLEURCANNON"  => { "spa" => -2 },
      "SUPERPOWER"   => { "atk" => -1, "def" => -1 },
      "CLOSECOMBAT"  => { "def" => -1, "spd" => -1 },
      "VCREATE"      => { "def" => -1, "spd" => -1, "speed" => -1 },
      "HAMMERARM"    => { "speed" => -1 },
      "DRAGONASCENT" => { "def" => -1, "spd" => -1 }
    }

    # Adapters that cannot compute Essentials function codes fall back to bare kind
    # tags ("secondary:burn"), so the core can still find the kind without a chance.
    # The Reborn adapter exports effect_kind/effect_chance from the code map instead
    # and never needs these; they exist so the same core runs on a thinner adapter.
    # A stage as a damage ratio. Negative stages are the reciprocal, which is what
    # the engine's own pair table spells out row by row; clamped at +-6 as the engine
    # clamps the stage itself.
    def self.stage_multiplier(stage)
      value = stage.to_i
      value = 6 if value > 6
      value = -6 if value < -6
      return STAGE_MULT[value] if value >= 0
      1.0 / STAGE_MULT[-value]
    end

    # nil for a move with no row, which the setup consumer reads as "price it the old
    # way" rather than as "it raises nothing".
    def self.setup_stages(move_id)
      SETUP_STAGES[move_id.to_s.upcase]
    end

    def self.self_drop_stages(move_id)
      SELF_DROP_STAGES[move_id.to_s.upcase]
    end

    # How much a heal move restores, in percent of max HP. Rest refills; the weather
    # heals pay two thirds in sun and a quarter in sand or hail; everything else half.
    # Move knowledge, so it lives here where both planners can read it (0.7.2; it was
    # Core.heal_amount, which still delegates).
    def self.heal_amount(snapshot, tags)
      return 100.0 if tags.include?("heal_full")
      if tags.include?("heal_weather")
        weather = (snapshot || {})["weather"]
        return 66.0 if weather == "sun"
        return 25.0 if weather == "sand" || weather == "hail"
      end
      50.0
    end

    # The memory record a chosen action leaves behind: what was clicked and which
    # repeat counter it advances. The adapter's apply_memory zeroes every counter but
    # the one incremented, which is what makes "did I Protect last turn" answerable.
    # Shared by both planners (0.7.2; Core.memory_updates delegates).
    def self.memory_updates(actions)
      out = {}
      actions.each do |action|
        actor_index = action["actor_index"]
        update = { "last_type" => action["type"] }
        if action["type"] == "switch"
          update["increment"] = "switch"
        else
          tags = describe(action["move_id"], action["tags"])
          update["last_move"] = action["move_id"]
          if tags.include?("setup")
            update["increment"] = "setup"
          elsif tags.include?("protect") || tags.include?("team_protect")
            update["increment"] = "protect"
          elsif tags.include?("substitute")
            update["increment"] = "substitute"
          end
        end
        out[actor_index.to_s] = update
      end
      out
    end

    def self.kind_of(tags, prefix)
      head = prefix.to_s + ":"
      (tags || []).each do |tag|
        value = tag.to_s
        return value[head.length, value.length] if value.index(head) == 0
      end
      nil
    end

    def self.describe(move_id, supplied_tags)
      tags = []
      (TABLE[move_id.to_s.upcase] || []).each { |tag| tags << tag }
      (supplied_tags || []).each do |tag|
        value = tag.to_s
        tags << value if !tags.include?(value)
      end
      tags
    end

    def self.tagged?(move_id, supplied_tags, tag)
      describe(move_id, supplied_tags).include?(tag)
    end
  end
end
# ===== END portable_ai/effects.rb =====

# ===== BEGIN portable_ai/matrix.rb =====
# Engine-independent readers over the party x party damage matrix.
# Requires model.rb and effects.rb to have been loaded first; requires nothing from
# core.rb, which is the point -- both the rule planner (core.rb) and the search
# planner (search.rb) read the board through these and neither owns them.
#
# Everything here is a pure function of the snapshot. No config, no rng, no scoring.

module PortableAI
  # Beyond this many hits the exchange is not a race any more, it is a stall war, and
  # the counts stop carrying information. Cap rather than let a chip move produce a
  # 40-turn "plan" that compares equal to another one.
  RACE_MAX_HITS = 8

  # nil when nothing gets through, otherwise the capped number of hits.
  def self.hits_needed(hp, per_hit)
    return nil if per_hit.nil? || per_hit <= 0
    count = (hp / per_hit.to_f).ceil
    count = RACE_MAX_HITS if count > RACE_MAX_HITS
    count = 1 if count < 1
    count
  end

  # ---------------------------------------------------------------------------
  # 0.6.5. THE PARTY x PARTY DAMAGE MATRIX -- a pure derived layer over one new
  # snapshot field.
  #
  # Every rule above this line scores against the ACTIVE foe. That is the whole
  # board a move sees, but it is not the whole board a switch decides: sending the
  # only body that beats their Azumarill into a Scizor that removes it is a game
  # thrown away three turns before anything looks wrong, and a boost is worth what
  # it flips across the rest of the party, not a flat 55.
  #
  # The adapter builds `snapshot["matrix"]` -- one damage estimate per party pair,
  # both directions, cached and re-rolled only when a signature changes. This
  # section reads it and nothing else, so every consumer goes inert the instant the
  # field is absent: an adapter that exports no matrix (Reborn) is unchanged, which
  # is what makes its gauntlet the control for this version.
  #
  # SLOTS, NOT SEATS. A benched body has no seat, and a seat is not a party index.
  # The side tables carry both, and matrix_slot is the only way across.
  #
  # NOT in the cells, on purpose: HP (this layer derives the hit counts from the
  # side tables' current hp_pct, so a verdict decays as a body is chipped),
  # Intimidate, the Choice lock, entry hazards, and PRIORITY -- a cell is a damage
  # number, and damage_race is the thing that orders the final hit, so a body that
  # wins on Bullet Punch reads here as losing. The 0.6.4 switch estimators
  # still carry those and still feed candidate_race; the matrix is the wide, thin
  # view, not a replacement for the narrow, thick one. Defender-side screens ARE in
  # the numbers, because the engine's own damage estimate reads them.

  # Both sides needing six or more hits is not a race, it is a stall: at that depth
  # the exchange is decided by crits, status and residual, none of which these cells
  # carry. Deliberately below RACE_MAX_HITS (8), which is a CAP -- "both at the cap"
  # would need <= 12.5% a hit on both sides and would almost never be reachable --
  # and above WALL_BREAK_MAX_HITS (4), which asks the opposite question. The verdict
  # is recomputed from current HP every snapshot, so an S decays into W or L as soon
  # as one side is chipped enough to matter.
  MATRIX_STALL_HITS = 6

  def self.matrix(snapshot)
    m = (snapshot || {})["matrix"]
    m.is_a?(Hash) ? m : nil
  end

  # Seat (a battler index: actor["index"], target["index"], never an action's slot)
  # to party slot. nil for a seat no live party entry occupies.
  def self.matrix_slot(side_table, seat)
    return nil if side_table.nil? || seat.nil?
    side_table.each do |entry|
      next if entry.nil?
      return entry["slot"] if !entry["index"].nil? && entry["index"] == seat
    end
    nil
  end

  def self.matrix_entry(side_table, slot)
    return nil if side_table.nil? || slot.nil?
    side_table.each do |entry|
      next if entry.nil?
      return entry if entry["slot"] == slot
    end
    nil
  end

  def self.matrix_cell(snapshot, own_slot, foe_slot)
    m = matrix(snapshot)
    return nil if m.nil? || own_slot.nil? || foe_slot.nil?
    cells = m["cells"]
    return nil if !cells.is_a?(Hash)
    cell = cells["#{own_slot}:#{foe_slot}"]
    cell.is_a?(Hash) ? cell : nil
  end

  # Hits each way at the HP both bodies are actually standing on. nil on either side
  # means nothing that body has gets through, which is a distinct answer from "it
  # needs many hits" and the verdict below reads it as such.
  def self.matrix_hits(cell, own_hp, foe_hp)
    return nil if cell.nil?
    { "mine" => hits_needed(foe_hp, Model.number(cell["out"], 0.0)),
      "theirs" => hits_needed(own_hp, Model.number(cell["in"], 0.0)) }
  end

  # "W" this body wins the pair, "L" it loses, "S" neither finishes, nil unknown.
  #
  # No free-hit convention here. The turn a switch costs belongs to candidate_race
  # (:1210), which already charges it; a matrix verdict is the standing question
  # "who beats whom", asked of two bodies at their current HP.
  def self.matrix_verdict(snapshot, own_slot, foe_slot)
    cell = matrix_cell(snapshot, own_slot, foe_slot)
    return nil if cell.nil?
    m = matrix(snapshot)
    own = matrix_entry(m["own"], own_slot)
    foe = matrix_entry(m["foe"], foe_slot)
    return nil if own.nil? || foe.nil?
    cell_verdict(cell, Model.number(own["hp_pct"], 100.0),
                 Model.number(foe["hp_pct"], 100.0))
  end

  # The same judgement on a cell the caller is holding -- a transformed one, which by
  # construction is in no matrix (Core.setup_matrix_value).
  # A pair the engine could not price reads here exactly like a pair nothing lands in:
  # `out` nil and `out` 0.0 both give no hits and both lose. The distinction is kept in
  # the cell for the readout (`?` against `0%`) rather than acted on, because the
  # alternative -- a verdict of nil -- would silently drop the pair out of
  # matrix_answers and turn "we could not measure it" into "nothing answers it".
  def self.cell_verdict(cell, own_hp, foe_hp)
    return nil if cell.nil?
    return nil if own_hp <= 0 || foe_hp <= 0
    hits = matrix_hits(cell, own_hp, foe_hp)
    mine = hits["mine"]
    theirs = hits["theirs"]
    stalled_mine = mine.nil? || mine >= MATRIX_STALL_HITS
    stalled_theirs = theirs.nil? || theirs >= MATRIX_STALL_HITS
    return "S" if stalled_mine && stalled_theirs
    return "L" if mine.nil?
    return "W" if theirs.nil?
    return "W" if mine < theirs
    return "L" if mine > theirs
    faster = cell["faster"]
    return nil if faster != true && faster != false
    faster ? "W" : "L"
  end

  def self.matrix_live_slots(side_table)
    out = []
    (side_table || []).each do |entry|
      next if entry.nil?
      next if entry["alive"] == false
      next if Model.number(entry["hp_pct"], 0.0) <= 0
      out << entry["slot"]
    end
    out
  end

  # Every live body on our side that beats this foe.
  def self.matrix_answers(snapshot, foe_slot)
    m = matrix(snapshot)
    return [] if m.nil?
    matrix_live_slots(m["own"]).select do |own_slot|
      matrix_verdict(snapshot, own_slot, foe_slot) == "W"
    end
  end

  # The live foes this body is the ONLY answer to. Empty when the matrix is absent,
  # so a consumer written against it is inert by construction.
  def self.sole_answers(snapshot, own_slot)
    m = matrix(snapshot)
    return [] if m.nil? || own_slot.nil?
    matrix_live_slots(m["foe"]).select do |foe_slot|
      answers = matrix_answers(snapshot, foe_slot)
      answers.length == 1 && answers[0] == own_slot
    end
  end

  # A cell as it would read after the actor's own stat stages. Physical output scales
  # with Attack, special with Special Attack, and the mirror on the way in; speed
  # stages can flip who moves first, which is the whole point of a Dragon Dance.
  # Ratios, not the engine's numerator/denominator pairs -- STAGE_MULT.
  #
  # Applied from stage 0. Its only caller is the first-setup arm (repeats == 0, which
  # setup_stage keys off positive_stage_total < 2), so the body is carrying at most
  # one stage already and the error is bounded by one.
  def self.matrix_transform_cell(cell, stages, own_speed, foe_speed, trick_room)
    return nil if cell.nil?
    out = Model.copy_hash(cell)
    stages = stages || {}
    offence = (cell["out_cat"] == "special") ? stages["spa"] : stages["atk"]
    defence = (cell["in_cat"] == "special") ? stages["spd"] : stages["def"]
    if !cell["out"].nil? && !offence.nil? && offence != 0
      out["out"] = Model.number(cell["out"], 0.0) * Effects.stage_multiplier(offence)
    end
    if !cell["in"].nil? && !defence.nil? && defence != 0
      out["in"] = Model.number(cell["in"], 0.0) / Effects.stage_multiplier(defence)
    end
    speed_stage = stages["speed"]
    if !speed_stage.nil? && speed_stage != 0 && !own_speed.nil? && !foe_speed.nil?
      mine = own_speed.to_f * Effects.stage_multiplier(speed_stage)
      # The adapters' own convention (faster_than_foes?): strictly greater is faster,
      # a tie is not, and Trick Room inverts it.
      out["faster"] = trick_room ? mine < foe_speed.to_f : mine > foe_speed.to_f
    end
    out
  end
end
# ===== END portable_ai/matrix.rb =====

# ===== BEGIN portable_ai/core.rb =====
# Engine-independent battle decision module.
# Requires model.rb, effects.rb and matrix.rb to have been loaded first.

module PortableAI
  HARD_REJECT = -1000000

  def self.plan(snapshot, config, rng)
    Model.validate(snapshot)
    cfg = Model.config(config)
    random = rng || Kernel
    scored_by_actor = []

    snapshot["actors"].each do |actor|
      scored = []
      actor["actions"].each do |action|
        candidate = score_action(snapshot, actor, action, cfg, random)
        scored << candidate
      end
      raise ArgumentError, "actor #{actor['index']} has no usable actions" if scored.empty?
      scored.sort! { |a, b| compare_candidates(a, b) }
      scored_by_actor << scored
    end

    selected, joint = choose_joint(snapshot, scored_by_actor, cfg)
    updates = memory_updates(selected)
    {
      "actions" => selected,
      "memory_updates" => updates,
      "diagnostics" => {
        "version" => VERSION,
        "format" => snapshot["format"] || (snapshot["actors"].length > 1 ? "double" : "single"),
        "joint_adjustment" => joint,
        "candidate_counts" => scored_by_actor.map { |items| items.length },
        "rankings" => scored_by_actor
      }
    }
  end

  def self.score_action(snapshot, actor, action, config, rng)
    out = Model.copy_hash(action)
    out["actor_index"] = actor["index"] if out["actor_index"].nil?
    reasons = []
    score = Model.number(action["base_score"], 0.0)
    reasons << ["engine_base", score]

    if action["type"] == "switch"
      score = score_switch(snapshot, actor, action, config, score, reasons)
    else
      score = score_move(snapshot, actor, action, config, score, reasons)
      if doubles_outcomes_enabled?(snapshot, config) &&
         Model.truthy(action["damaging"]) && !Model.truthy(action["friendly_target"]) &&
         (!Model.truthy(action["spread"]) || action["damage_by_target"])
        # joint_adjustment replaces only this move's independent damage/KO value.
        # All type, priority, recoil and effect knowledge above remains intact.
        out["outcome_scored"] = true
        reasons << ["doubles_outcome_candidate", 0]
      end
    end

    adjustment = Model.number(action["score_adjustment"], 0.0)
    if adjustment != 0
      score += adjustment
      reasons << ["adapter_adjustment", adjustment]
    end

    noise = Model.number(config["noise"], 0.0)
    if !config["deterministic"] && noise > 0
      roll = rng.rand((noise * 2).to_i + 1) - noise
      score += roll
      reasons << ["difficulty_noise", roll]
    end

    out["score"] = score
    out["reasons"] = reasons
    out
  end

  def self.score_move(snapshot, actor, action, config, score, reasons)
    move_id = action["move_id"].to_s.upcase
    tags = Effects.describe(move_id, action["tags"])
    out_score = score
    target = target_for(snapshot, action["target"])
    actor_hp = Model.number(actor["hp_pct"], 100.0)
    target_hp = target ? Model.number(target["hp_pct"], 100.0) : 100.0
    # A spread move carries no registration target -- the adapter sets
    # action["target"] = nil because there is no single battler to register against
    # (Portable_AI_Adapter.rb:551) -- so target_for returns nil and this defaulted to a
    # phantom 100% target. Earthquake and Lava Plume therefore NEVER reached `lethal`,
    # at any target HP, and ko_never_lands could not fire for them either. The adapter
    # exports the scoring target's own HP on every action (:638); read that instead.
    if !target && config["spread_target_hp"] && !action["target_hp_pct"].nil?
      target_hp = Model.number(action["target_hp_pct"], 100.0)
    end
    damage = Model.number(action["expected_damage_pct"], 0.0)
    effectiveness = Model.number(action["effectiveness"], 1.0)

    partial_spread = doubles_outcomes_enabled?(snapshot, config) && Model.truthy(action["spread"]) &&
      action["damage_by_target"] && action["damage_by_target"].any? do |_index, hit|
        Model.number(hit["damage_pct"], 0) > 0
      end
    if (Model.truthy(action["immune"]) ||
        (Model.truthy(action["damaging"]) && effectiveness <= 0)) && !partial_spread
      reasons << ["immune", HARD_REJECT]
      return HARD_REJECT
    end

    # A move the engine refused last turn against this same target will be refused
    # again: the board has not moved. Reborn keeps the flag itself for Stomping
    # Tantrum (PBEffects::Tantrum, PokeBattle_Battler.rb:5085) and the adapter reads it
    # back on the action. Bisharp clicked a dead Sucker Punch three turns running with
    # a guaranteed Knock Off KO one point behind (bulky_vs_offense 196613 t22-24), so
    # this is deliberately larger than that gap and smaller than a kill call.
    if config["move_memory"] && Model.truthy(action["failed_last_turn"])
      out_score -= 200
      reasons << ["failed_last_turn", -200]
    end

    lethal = false
    faster = faster_flag(actor)

    if Model.truthy(action["damaging"])
      lethal = damage >= target_hp && target_hp > 0
      # A spread action's damage is summed across foes, so comparing that total with
      # one foe's HP invents a KO. The pair evaluator awards each real KO instead.
      lethal = false if doubles_outcomes_enabled?(snapshot, config) && Model.truthy(action["spread"]) &&
                        action["damage_by_target"]

      # NOTE on Sturdy and Focus Sash. 0.5.0 first cancelled the kill call here --
      # lethal = false, damage := target_hp - 1 -- on the argument that a hit leaving
      # the target on 1 HP is not a knockout. It was WITHDRAWN before release, for
      # three reasons that are worth keeping written down:
      #
      #  * Reborn does not do it. Its notOHKO? (:17401) exists to pay a MULTI-HIT move
      #    x1.3 for beating the guard (:7389); it never removes a single-hit move's own
      #    kill score. The multi-hit row in side_effect_rules is that same fact, and it
      #    is what the corpus cards (sturdy_blocks_the_kill_call, focus_sash_same_as_
      #    sturdy, sash_ignored_when_not_full_hp) actually decide on -- none of them
      #    ever touched this block.
      #  * The cost was out of proportion to the information. Cancelling lethal takes
      #    about 420 points off the strongest move, which is far more than "you will
      #    need a second hit" is worth: hitting hard is still right, because breaking
      #    the guard is what makes the next hit lethal.
      #  * It measured badly and it is the only ability row that could. Of the six
      #    ability rows, Unaware, Contrary, Justified and Regenerator are all INERT on
      #    set_a..e (the gauntlet builds every mon with setAbility(0) and no roster mon
      #    carries them in slot 0), so ability_rules on those rosters was essentially
      #    this row plus the status-deterrent table -- and turning ability_rules off
      #    was worth +3 wins over 120 battles.
      #
      # The knowledge is still worth having for the priority gate and the heal gate,
      # which read `lethal`; reinstating it needs a form that does not also delete the
      # move's value, and a roster on which the rest of the table is not inert.
      priority = Model.number(action["priority"], 0)

      # A knockout only counts if it lands. When the actor is slower and the foe's
      # best move already kills it, a non-priority "KO" resolves after the actor is
      # gone, so it is worth its damage and nothing more (Reborn :2855-2923).
      if lethal && config["priority_gate"] && faster == false && priority <= 0 &&
         certain_lethal_threat?(actor, config)
        lethal = false
        reasons << ["ko_never_lands", 0]
      end

      if lethal
        value = 500.0
        out_score += value
        reasons << ["lethal", 500]
      elsif damage > 0
        value = [damage, 100.0].min * 0.8
        out_score += value
        reasons << ["expected_damage", value]
      else
        value = 0.0
      end

      # Reborn scales every move score by (accuracy + 100) / 200 (:3349), which is
      # what makes an accurate KO beat an inaccurate one -- Portable had no accuracy
      # term at all and over-clicked Fire Blast, Stone Edge and Focus Blast. Only the
      # damage terms are scaled; the type and tag rules keep their full weight.
      if value > 0
        factor = accuracy_factor(action, config)
        if factor != 1.0
          adjust = value * factor - value
          out_score += adjust
          reasons << ["accuracy", adjust]
        end
      end

      # Priority is worth most exactly where it is the only way the KO happens.
      if config["priority_gate"] && lethal && priority > 0 && !faster.nil?
        bonus = faster ? 60 : 150
        bonus += 200 if !faster && threatened_lethal?(actor)
        # A second foe acts whichever order this one resolves in, so moving first buys
        # much less: Reborn drops priority from x2 to x1.3 in doubles (:2856), and the
        # probe measured Aqua Jet at 242 in singles against 157 in the same doubles
        # position. Flat 60 rather than a scaled 150.
        if config["format_rules"] && doubles?(snapshot) && bonus > 60
          bonus = 60
          reasons << ["priority_flat_in_doubles", 0]
        end
        out_score += bonus
        reasons << ["priority_finisher", bonus]
      end

      # Once the move kills, the type chart has already said everything it has to say:
      # both kills remove the same battler, so the only thing left to choose on is
      # which one lands. Fire Blast at 85% was beating Dragon Claw at 100% for the same
      # KO on a 70-point super-effective bonus against a 45-point resist penalty
      # (bulky_vs_offense 196613 t4: 649 against 555). flat_kill also drops the
      # secondaries that only pay out on a survivor -- see side_effect_rules.
      #
      # NOT applied to a SPREAD action, which is a summary of several targets rather
      # than one kill: its damage is the sum over the foes and its effectiveness is a
      # standing measure of how much of the field the move resolves, which is exactly
      # what choose_joint weighs it against. Dropping the term there cost Garchomp a
      # double kill it had been finding since 0.4.0 -- d_spread_kills_both_preferred,
      # caught by the corpus on the first 0.6.2 probe (Earthquake 740 -> 600, and the
      # split-fire pair's coordination bonus then won by 66 points).
      flat_kill = lethal && config["lethal_flat"] && !Model.truthy(action["spread"])
      if flat_kill
        reasons << ["lethal_flat", 0]
      elsif doubles_outcomes_enabled?(snapshot, config) && Model.truthy(action["spread"]) &&
            action["damage_by_target"]
        reasons << ["spread_type_in_damage", 0]
      elsif effectiveness > 1
        bonus = 35 * effectiveness
        out_score += bonus
        reasons << ["super_effective", bonus]
      elsif effectiveness > 0 && effectiveness < 1
        out_score -= 45
        reasons << ["resisted", -45]
      end

      if config["side_effects"]
        out_score = side_effect_rules(snapshot, actor, action, tags, target,
                                      damage, lethal, faster, out_score, reasons,
                                      flat_kill)
      end
      if config["ability_rules"]
        out_score = damaging_ability_rules(action, target, lethal, out_score, reasons)
      end
    end

    if tags.include?("heal") || tags.include?("variable_heal")
      if actor_hp >= 85
        out_score -= 500
        reasons << ["heal_near_full", -500]
      elsif actor_hp <= 35
        bonus = 220 + (35 - actor_hp) * 3
        out_score += bonus
        reasons << ["heal_low_hp", bonus]
      elsif actor_hp <= 60
        out_score += 90
        reasons << ["heal_mid_hp", 90]
      end
      if config["heal_gate"]
        out_score = heal_gate(snapshot, actor, action, tags, out_score, reasons, config)
      elsif threatened_lethal?(actor)
        out_score -= 80
        reasons << ["heal_under_lethal_threat", -80]
      end
    elsif tags.include?("delayed_heal")
      # Wish fails outright with a Wish already pending (PokeBattle_MoveEffects.rb:6084
      # returns -1 and displays "But it failed!"). Same channel the screens use: the
      # adapter reports PBEffects::Wish through effect_active.
      if config["wish_pending"] && Model.truthy(action["effect_active"])
        out_score -= 300
        reasons << ["delayed_heal_pending", -300]
      elsif actor_hp >= 90
        out_score -= 300
        reasons << ["delayed_heal_near_full", -300]
      elsif actor_hp <= 55
        out_score += 100
        reasons << ["delayed_heal_useful", 100]
      end
    end

    if tags.include?("status")
      if target && occupied_status?(target["status"])
        out_score -= 450
        reasons << ["target_already_statused", -450]
      elsif target && Model.truthy(target["status_immune"])
        out_score -= 450
        reasons << ["target_status_immune", -450]
      else
        out_score += 25
        reasons << ["fresh_status", 25]
        if config["ability_rules"] && !Model.truthy(action["damaging"])
          out_score = status_deterrent_rule(action, tags, target, out_score, reasons)
        end
      end
    end

    if config["side_effects"]
      out_score = turn_shape_rules(snapshot, actor, action, tags, faster,
                                   out_score, reasons)
    end
    if config["format_rules"]
      out_score = format_rules(snapshot, actor, action, tags, out_score, reasons)
      return HARD_REJECT - 1 if out_score <= HARD_REJECT
    end

    if tags.include?("setup")
      repeats = config["memory"] ? memory_count(snapshot, actor["index"], "setup") : 0
      # The memory counter alone answers "did I set up on the PREVIOUS action", because
      # apply_memory zeroes every counter but the one it just incremented
      # (Portable_AI_Adapter.rb:1487). One attack in between and a +2 sweeper was
      # "first setting up" all over again -- Heracross took a second Swords Dance at
      # 31% HP that way (bulky_vs_offense 196613 t20). The stages the actor is standing
      # in are the durable record of the same fact, and one setup move is worth about
      # two stages (Swords Dance +2, Dragon Dance +1/+1, Calm Mind +1/+1).
      if config["setup_stage"]
        carried = Model.number(actor["positive_stage_total"], 0).to_i / 2
        repeats = carried if carried > repeats
      end
      if config["ability_rules"] && actor_ability(actor) == "CONTRARY"
        # Contrary turns every boost into a drop. Reborn does not have this row at all;
        # it is here because a Contrary user clicking Swords Dance is strictly harming
        # itself, which no amount of engine damage data reveals.
        out_score -= 300
        reasons << ["contrary_setup", -300]
      elsif config["ability_rules"] && target_fact(action, target, "ability") == "UNAWARE"
        # Boosting in front of Unaware achieves nothing: it reads through the stages.
        # Reborn halves the setup score (:4966); -150 is that halving in score units.
        out_score -= 150
        reasons << ["setup_vs_unaware", -150]
      elsif actor_hp <= 30 || threatened_lethal?(actor)
        out_score -= 240
        reasons << ["unsafe_setup", -240]
      elsif setup_into_2hko?(snapshot, actor, target, config)
        # Being 2HKOed while SLOWER means the boost never gets used: the foe's second
        # hit lands before the boosted attack does. Reborn charges x0.4 for exactly
        # this (:6007) on top of the x0.8/x0.3 a status move already pays; against a
        # ~450-point setup score that is about -180.
        #
        # The `faster == false` clause is NOT an inference from the source, it is a
        # measurement: on one board with +2 Speed and nothing else changed, stock
        # Reborn's Swords Dance went from 9 to 46 (PORTABLE-AI-REBORN.md, "0.6.0 Phase
        # A"). What refuses the setup there is the speed order, not the race, and a
        # faster mon setting up into a 2HKO is behaviour the reference endorses.
        #
        # Departure from the reference, recorded because a future agent comparing
        # against Reborn will otherwise read it as a bug: Reborn's gate also requires
        # `stats[PBStats::ATTACK]==1`, and `stats` holds STAGES, so its own rule
        # silently skips every +2 move (Swords Dance, Nasty Plot) and only ever
        # reaches +1 moves. That is a quirk of how the gate was written, not a claim
        # about play, so this rule applies to any setup tag.
        out_score -= 180
        reasons << ["setup_into_2hko", -180]
      elsif repeats == 0 && config["setup_matrix"] &&
            !(worth = setup_matrix_value(snapshot, actor, action, config)).nil?
        # 0.6.5. The first boost is priced by what it flips across their whole party
        # rather than paid a flat 55 (Core.setup_matrix_value). Key off, or no matrix
        # to read, and the flat bonus below is what happens.
        out_score += worth["value"]
        reasons << [worth["reason"], worth["value"]]
      elsif repeats == 0
        out_score += 55
        reasons << ["first_setup", 55]
      else
        penalty = 100 * repeats
        out_score -= penalty
        reasons << ["repeated_setup", -penalty]
      end
    end

    if tags.include?("hp_cost_half") && actor_hp <= 50
      out_score -= 600
      reasons << ["hp_cost_unaffordable", -600]
    end

    if config["self_cost"] && tags.include?("self_drop")
      if config["ability_rules"] && actor_ability(actor) == "CONTRARY"
        # The same ability read the other way round: Draco Meteor's -2 becomes +2, so
        # the move Portable is charged 40 for is the one a Contrary user wants most.
        out_score += 40
        reasons << ["contrary_boost", 40]
      else
        penalty = lethal ? 15 : 40
        out_score -= penalty
        reasons << ["self_stat_drop", -penalty]
      end
    end

    if config["self_cost"] && tags.include?("self_ko")
      # Fainting on purpose is a trade. It is not one with nothing left to send out --
      # the battle ends there -- and it is not one while healthy: Reborn's deathcode
      # (:7779) scales the score by 1 - hp% and lands at 0.14 at full HP, where
      # Portable exploded 15 times out of 21.
      reserves = Model.number(action["own_reserves"], 0)
      trade = reserves > 0 && (actor_hp < 30 || threatened_lethal?(actor))
      if !trade
        out_score -= 400
        reasons << ["self_ko_cost", -400]
      end
    end

    if tags.include?("charge_solar") && snapshot["weather"] != "sun"
      out_score -= 120
      reasons << ["charge_turn_without_sun", -120]
    end

    if tags.include?("force_switch")
      layers = Model.number(action["foe_hazard_layers"], 0)
      boosts = Model.number(action["target_positive_stages"], 0)
      bonus = layers * 15 + boosts * 25
      if bonus > 0
        out_score += bonus
        reasons << ["phaze_value", bonus]
      end
    end

    if tags.include?("protect") || tags.include?("team_protect")
      repeats = config["memory"] ? memory_count(snapshot, actor["index"], "protect") : 0
      if repeats > 0
        penalty = 140 * repeats
        out_score -= penalty
        reasons << ["repeated_protect", -penalty]
      end
    end

    if tags.include?("substitute")
      if actor_hp <= 25
        out_score -= 500
        reasons << ["cannot_afford_substitute", -500]
      elsif config["memory"] && memory_count(snapshot, actor["index"], "substitute") > 0
        out_score -= 250
        reasons << ["substitute_already_used", -250]
      end
    end

    if tags.include?("hazard")
      layers = Model.number(action["existing_layers"], 0).to_i
      maximum = Model.number(action["max_layers"], 1).to_i
      if layers >= maximum
        out_score -= 500
        reasons << ["hazard_at_cap", -500]
      elsif action.key?("hazard_targets") && Model.number(action["hazard_targets"], 0) <= 0
        out_score -= 600
        reasons << ["hazard_hits_nobody", -600]
      elsif Model.number(action["foe_reserves"], 0) <= 0
        out_score -= 180
        reasons << ["hazard_no_reserves", -180]
      end
    end

    if tags.include?("hazard_remove") && Model.number(action["own_hazard_layers"], 0) <= 0
      out_score -= 300
      reasons << ["no_hazards_to_remove", -300]
    end

    if tags.include?("screen") && Model.truthy(action["effect_active"])
      out_score -= 400
      reasons << ["screen_already_active", -400]
    end

    if tags.include?("baton_pass") && Model.number(action["own_reserves"], 0) <= 0
      out_score -= 600
      reasons << ["baton_pass_no_bench", -600]
    end

    # A non-damaging move aimed at the partner is hostile unless it is an actual
    # support move: statusing or disrupting your own side is never worth a turn.
    if Model.truthy(action["friendly_target"]) && !Model.truthy(action["damaging"]) &&
       !tags.include?("partner_support") && !tags.include?("redirect") &&
       !tags.include?("heal")
      reasons << ["hostile_move_at_partner", HARD_REJECT]
      return HARD_REJECT
    end

    friendly = Model.number(action["friendly_fire_pct"], 0.0)
    if friendly > 0
      if Model.truthy(action["friendly_target"])
        reasons << ["targeted_friendly_fire", HARD_REJECT]
        return HARD_REJECT
      end
      partner_hp = Model.number(action["partner_hp_pct"], 100.0)
      penalty = friendly * 3
      penalty += 700 if friendly >= partner_hp
      out_score -= penalty
      reasons << ["friendly_fire", -penalty]
    end

    if move_id == "THUNDER"
      if snapshot["weather"] == "rain"
        out_score += 100
        reasons << ["thunder_in_rain", 100]
      else
        out_score -= 100
        reasons << ["thunder_without_rain", -100]
      end
    end

    # 0.6.7 (dead_before_moving). A move the actor does not live to click is worth a
    # quarter of itself. ko_never_lands above strips the +500 kill call from such a
    # move and nothing else: engine_base, expected_damage and super_effective stayed,
    # so a slower Sceptile at 100% facing a declared Acrobatics of 198% clicked its
    # own Acrobatics at 410 over a switch at 234 whose only death-aware term was
    # escape_lethal_threat +130 (gen5ru_a team3_vs_team4 104729 t10). Of the 162
    # oracle turns where the actor was slower and certain to die, 131 attacked.
    #
    # Every non-priority move is scaled the same, so the ORDER among them is what it
    # was -- the rule never changes which move is clicked, only whether a switch
    # that has its own reason to exist wins over it -- and a priority move keeps
    # its whole score, because it lands: a Quick Attack that chips before death now
    # beats a Focus Blast that never happens. Same triple as ko_never_lands: slower
    # (nil is not slower), no priority, certain_lethal_threat? (the declared hit on
    # its minimum roll under the oracle, the strict figure otherwise). A trapped
    # actor keeps its move; the gate stays closed on the switches, the moves are
    # ranked as before. Under priority_gate, like ko_never_lands: with the gate off
    # nothing in the core reads the speed order, and that ablation stays whole.
    if config["dead_before_moving"] && config["priority_gate"] && faster == false &&
       Model.number(action["priority"], 0) <= 0 && certain_lethal_threat?(actor, config)
      adjust = out_score * (DEAD_BEFORE_MOVING_SCALE - 1.0)
      out_score += adjust
      reasons << ["dead_before_moving", adjust]
    end

    out_score
  end

  # Reasons that, on their own, justify leaving. Modelled on Reborn's
  # shouldSwitchintense? (PokeBattle_AI_2.rb:13713), which builds its switch score
  # purely from affirmative escape reasons — residual damage, its own debuffs, Yawn,
  # Perish Song — and never reads the opponent's stat stages. Deliberately excluded:
  # "matchup" and "engine_base" (type chart and HP, which are near-constant and were
  # the thing switching used to win on), and "preserve_low_hp_actor", which fires
  # exactly where Intense switches least — it never once switched below 30% HP across
  # 180 measured battles.
  # "escape_lethal_threat" opens the gate only above HEALTHY_PIVOT_HP_PCT.
  # threatened_lethal? is incoming_damage_pct >= hp_pct, which conflates two different
  # situations: a healthy battler facing a genuine hard counter (Garchomp into Lapras —
  # a real matchup problem, and a legitimate pivot the scenario corpus requires), and a
  # battler at 20% HP that everything threatens (not a matchup problem, just accumulated
  # damage). Counting both licensed exactly the switches this gate exists to stop: the
  # first gated run left switches-below-30%-HP unchanged at 2.09/battle. Intense treats
  # a weak battler as a reason to *stay* — shouldSwitchintense? subtracts 100 below 30%
  # HP for non-sweepers — and spends it attacking. Below the threshold the bonus still
  # applies once some other reason has opened the gate; it just cannot open it alone.
  HEALTHY_PIVOT_HP_PCT = 50

  # A boosted foe must not be able to open the gate by itself. A foe at +2 roughly
  # doubles its output, so it turns threatened_lethal? on without the matchup having
  # changed at all — and HEALTHY_PIVOT_HP_PCT then licenses the switch precisely when
  # the battler is healthy, which is the worst moment to leave: the switch-in eats a
  # free boosted hit and the boost is still there afterwards. Measured over 180 fair
  # baseline battles, Reborn-Normal switched 0 times out of 173 while the foe was at
  # >= +2, whereas 49 of Portable 0.3.0's 451 switches happened there — 10.9% of its
  # switching in 5.8% of its turns.
  #
  # Only the lethal-threat reason is suppressed. Every other escape reason (no
  # effective move, crushed stats, Yawn, residual chip) is a fact about this battler
  # that a foe's boosts did not manufacture, so a boosted foe does not veto those.
  BOOST_SUPPRESSES_LETHAL_ESCAPE = 2

  # Type-matchup units as the adapters hand them over: a single neutral verdict is 4 on
  # Reborn's chart and is scaled x8, so neutral lands on 32, resisted 16, immune 0,
  # super-effective 64 and doubly so 128. How hard the defensive term pulls against the
  # offensive one is the "switch_risk_weight" config key, defaulted in
  # Model::DEFAULT_CONFIG.
  NEUTRAL_TYPE_MATCHUP = 32

  SWITCH_ESCAPE_REASONS = %w[
    no_effective_move clear_crushed_stats clear_bad_stats weak_current_attacks
    escape_yawn escape_residual_chip escape_lethal_threat_while_healthy
    losing_damage_race losing_race_bench_wins
  ]

  # Highest positive stage total among the opposing active battlers.
  def self.foe_boost_total(snapshot)
    best = 0
    (snapshot["targets"] || []).each do |target|
      total = Model.number((target || {})["positive_stages"], 0)
      best = total if total > best
    end
    best
  end

  def self.score_switch(snapshot, actor, action, config, score, reasons)
    if !config["switching"] && !Model.truthy(action["forced"])
      reasons << ["switching_disabled", HARD_REJECT]
      return HARD_REJECT
    end

    out_score = score + Model.number(action["matchup_score"], 0)
    reasons << ["matchup", Model.number(action["matchup_score"], 0)]

    # "matchup" is offence only. Weigh what the incoming Pokemon will eat the same way,
    # symmetrically around neutral, so resisting the foe is worth as much as threatening
    # it and walking a Pokemon into a super-effective STAB costs what it should. Only
    # applies once a switch is happening; it never argues for or against leaving, just
    # for who goes in. Absent (older adapters, forced switches) it contributes nothing.
    weight = Model.number(config["switch_risk_weight"],
                          Model::DEFAULT_CONFIG["switch_risk_weight"])
    # When the adapter can estimate what the candidate ACTUALLY eats on the way in --
    # a real damage roll against a fake battler, with the candidate's own Intimidate
    # already applied to the foes -- that replaces the type proxy rather than joining
    # it. The proxy pays (32 - risk) * weight, so +32w for an immunity and -96w for a
    # 4x hit; 25% incoming is mapped to neutral and 100% to the 4x end, which puts the
    # real number on exactly the scale the rest of the switch score was tuned against.
    real_incoming = config["entry_rules"] && action.key?("incoming_damage_pct")
    if action.key?("incoming_risk") && weight != 0 && !real_incoming
      risk = Model.number(action["incoming_risk"], NEUTRAL_TYPE_MATCHUP)
      adjust = (NEUTRAL_TYPE_MATCHUP - risk) * weight
      out_score += adjust
      reasons << ["incoming_risk", adjust]
    elsif real_incoming && weight != 0
      incoming = entry_hit_pct(action)
      adjust = (25.0 - incoming) * 1.28 * weight
      out_score += adjust
      reasons << ["entry_incoming_damage", adjust]
    end

    # WHO COMES IN, rather than whether to leave -- so this is the one race consumer
    # that also applies to a forced switch, which is the post-KO replacement Radical
    # Red designed its table for (ANALYSIS.md :655-684). A candidate whose two damage
    # estimates the adapter could not build contributes nothing.
    #
    # Both halves are Reborn-measured, not guessed. Phase A put two identical
    # Mamoswine on the bench differing only in an Assault Vest -- one incoming number,
    # nothing else -- and stock scored them 257 against -175.8; two identical Ampharos
    # differing only in 252 Speed EVs scored 193 against 115.8, so outspeeding alone
    # is worth about +77 in Reborn's units (:11755-11764 scales a switch-in's damage
    # output x1.5 when it outruns the foe and x0.75 when it does not). Radical Red
    # pays a flat +14 for the same fact; scaled x5 into Portable's units -- where a
    # neutral matchup is 32 and one super-effective step is another 32 -- that is +70,
    # which is within rounding of what Reborn actually pays.
    if config["damage_race"] && action.key?("outgoing_damage_pct") &&
       action.key?("incoming_damage_pct")
      bonus = switchin_race_bonus(action)
      if bonus != 0
        out_score += bonus
        reasons << ["switchin_race", bonus]
      end
    end
    # 0.6.4. The other half of the same question: not only how long the candidate
    # LASTS but who lands the last hit once it is in -- candidate_race, the full
    # exchange after the entry damage (hazards plus the free hit) is paid, graded by
    # the margin in hits. Every switch candidate carries it, the post-KO replacement
    # included, which is what the readout kept asking for: Scizor sent into a Heatran
    # that kills it first with Slowbro on the bench (team3_vs_team2 155921 t29). The
    # defensive bands above are Reborn's measured switch-in and stay as they are; this
    # is the term neither Reborn nor the bands have.
    if config["switchin_race_grade"] && config["damage_race"]
      grade = candidate_race_grade(snapshot, action)
      if grade != 0
        out_score += grade
        reasons << ["kill_order", grade]
      end
    end
    # 0.6.5. What this body is worth to the REST of the battle, from the party x party
    # matrix: the only answer to a foe still on their bench is not a body to spend in
    # front of a foe it loses to. A score term, not a reason to leave, so a forced
    # replacement is ranked by it too (only the gate below is bypassed when forced).
    sole = sole_answer_value(snapshot, actor, action, config)
    if !sole.nil?
      out_score += sole[0]
      reasons << [sole[1], sole[0]]
    end
    escapes = []

    if Model.truthy(action["forced"])
      out_score += 1000
      reasons << ["forced_switch", 1000]
    end
    # 0.6.3. "I cannot hurt it" is a reason to leave only for a body that can. Against
    # a wall every attacker's moves are weak, so these two reasons opened the gate for
    # whoever stood there, the bench Pokemon that came in was as weak as the one that
    # left, and it went straight back: 168 of the 193 switch-backs against an
    # unchanged foe in the first 0.6.3 Realidea run were Zapdos and Suicune trading
    # places in front of a Chansey on weak_current_attacks. The candidate's own
    # estimate is on the action; absent (older adapters), the reasons keep their
    # 0.6.2 shape and the candidate is not held to a number nobody computed.
    hitter = candidate_can_hit?(snapshot, actor, action, config)
    # 0.6.6 (no_hit_needs_threat). "I cannot hurt it" is a reason to leave only if IT
    # can hurt ME. The airborne fix made Steelix's Earthquake into a Levitate Uxie
    # the nothing it always was, and both reasons below then sent Steelix off the
    # field at turn 0 with Toxic, Stealth Rock and Roar in hand, against a foe that
    # needs six hits to remove it -- four battles lost on one roster, every one of
    # them a Steelix that stock kept in and let lay rocks (gen5ru_a team3_vs_team4
    # 196613 t0). A wall that cannot be hurt in a hurry and still has a move worth
    # clicking has no reason to leave; a wall with nothing but blanked attacks does.
    walled = config["no_hit_needs_threat"] && walled_but_safe?(actor)
    if Model.truthy(actor["no_effective_move"])
      if hitter == false
        reasons << ["bench_cannot_hit_either", 0]
      elsif walled
        reasons << ["walled_but_safe", 0]
      else
        out_score += 260
        reasons << ["no_effective_move", 260]
        escapes << "no_effective_move"
      end
    end
    negative_stages = Model.number(actor["negative_stage_total"], 0)
    if negative_stages <= -6
      bonus = [(-negative_stages) * 35, 350].min
      out_score += bonus
      reasons << ["clear_crushed_stats", bonus]
      escapes << "clear_crushed_stats"
    elsif negative_stages <= -3
      out_score += 90
      reasons << ["clear_bad_stats", 90]
      escapes << "clear_bad_stats"
    end
    if Model.number(actor["best_damage_pct"], 100) < 10
      if hitter == false
        reasons << ["bench_as_weak", 0]
      elsif walled
        reasons << ["walled_but_safe", 0] if !reasons.any? { |r| r[0] == "walled_but_safe" }
      else
        out_score += 120
        reasons << ["weak_current_attacks", 120]
        escapes << "weak_current_attacks"
      end
    end
    if Model.truthy(actor["yawned"])
      out_score += 300
      reasons << ["escape_yawn", 300]
      escapes << "escape_yawn"
    end
    residual = Model.number(actor["residual_damage_pct"], 0)
    if residual >= 20
      bonus = [residual * 8, 400].min
      out_score += bonus
      reasons << ["escape_residual_chip", bonus]
      escapes << "escape_residual_chip"
    end
    if Model.truthy(actor["trapped"])
      reasons << ["trapped", HARD_REJECT]
      return HARD_REJECT
    end
    if threatened_lethal?(actor)
      out_score += 130
      reasons << ["escape_lethal_threat", 130]
      boosted_foe = foe_boost_total(snapshot) >= BOOST_SUPPRESSES_LETHAL_ESCAPE
      reasons << ["boosted_foe_holds_ground", 0] if boosted_foe
      if !boosted_foe && Model.number(actor["hp_pct"], 100) >= HEALTHY_PIVOT_HP_PCT
        escapes << "escape_lethal_threat_while_healthy"
      end
    end

    # Losing the race by a whole turn, at full health, is the generalisation of
    # escape_lethal_threat_while_healthy from "it kills me in one" to "it kills me in
    # two". OFF BY DEFAULT, and that is a finding rather than caution: the Phase A
    # card race_leave_when_losing_2hko_vs_3hko put a healthy Donphan in front of an
    # Espeon that 2HKOs it with a Psychic-IMMUNE bench available, and stock Reborn's
    # shouldSwitch? came back -50 and never even scored the bench. So the reference
    # does not do this; it is Radical-Red-cited only, the switch programme was closed
    # on evidence (PORTABLE-AI-DIAGNOSIS.md §4), and it must not reopen by default.
    # The boost suppression is the same one escape_lethal_threat carries: a +2 foe
    # manufactures a losing race exactly the way it manufactures a lethal threat.
    if config["damage_race_switch"]
      race = worst_race(snapshot, actor, config)
      if !race.nil? && race["winning"] == false &&
         !race["theirs"].nil? && race["theirs"] <= 2 &&
         Model.number(actor["hp_pct"], 100) >= HEALTHY_PIVOT_HP_PCT &&
         foe_boost_total(snapshot) < BOOST_SUPPRESSES_LETHAL_ESCAPE
        out_score += 110
        reasons << ["losing_damage_race", 110]
        escapes << "losing_damage_race"
      end
    end

    # 0.6.3. Leave a race this battler loses, for a bench candidate that WINS it.
    #
    # The 0.6.0 flag above opens the gate for every candidate once the actor's race is
    # lost, and that is the form the Donphan card sank: stock Reborn never asked whether
    # whoever came in would do any better, and neither did the flag. This one asks per
    # candidate, on the candidate's own two estimates, and pays for the switch turn
    # honestly -- the candidate eats one free hit coming in, then has to land the last
    # hit of the exchange that follows (candidate_race). Read off the Realidea shadow
    # run: 884 turns losing the race at >= 50% HP, 550 of them with a bench switch
    # vetoed by nothing but no_escape_reason -- Quagsire into a Calm Mind Clefable with
    # Magnezone on the bench among them (team1_vs_team2 104729 t0-5).
    #
    # Two things it deliberately does NOT carry over from the flag above. No boost
    # suppression: the foe's stages are already inside the candidate's incoming
    # estimate, so "it wins its race against a +2 foe" is a real claim here, not a
    # manufactured one. No HP floor: a chipped battler that is losing anyway has less
    # to preserve by staying, not more -- it is Zapdos at 13% Roosting into a 57% Lava
    # Plume five turns running with Chansey on the bench (team3_vs_team1 155921
    # t23-28). What it does require is that no recovery move the actor carries would
    # turn the race around: a race counted in hits is not lost by a battler that
    # out-heals the hit (heal_cannot_outpace?).
    if config["race_switch_to_winner"]
      race, foe = worst_race_with_target(snapshot, actor, config)
      if race_lost_by_a_hit?(race) && heal_cannot_outpace?(snapshot, actor)
        bench = candidate_race(action, foe)
        if !bench.nil? && bench["winning"]
          # 0.6.4: the size of the push is the kill_order grade above, so the reason
          # is worth its gate and nothing more; 0.6.3's flat 110 is what the grade
          # key off restores.
          bonus = config["switchin_race_grade"] ? 0 : 110
          out_score += bonus
          reasons << ["losing_race_bench_wins", bonus]
          escapes << "losing_race_bench_wins"
        end
      end
    end
    if config["entry_rules"] && action.key?("entry_damage_pct")
      # The hazard charge is already inside engine_base; recorded as its own reason so
      # a trace can say how much of a switch's cost was the entry rather than the
      # candidate. Zero delta on purpose -- charging it twice was the alternative.
      reasons << ["entry_hazards", 0]
    end
    # Safe entry originally asked only whether the candidate cleared the hazards with
    # 20% to spare. What actually matters is whether it is still alive at the end of
    # the turn it comes in on, which needs the incoming hit as well.
    safe = Model.truthy(action["safe_entry"])
    if config["entry_rules"] && action.key?("entry_damage_pct") &&
       action.key?("incoming_damage_pct")
      safe = Model.number(action["candidate_hp_pct"], 100.0) -
             Model.number(action["entry_damage_pct"], 0.0) -
             entry_hit_pct(action) > 0
    end
    if Model.number(actor["hp_pct"], 100) <= 20 && safe
      out_score += 80
      reasons << ["preserve_low_hp_actor", 80]
    end
    # The same subtraction, read the other way: a candidate that is dead before it acts
    # is not a switch, it is a sacrifice, and score_switch computed this quantity for
    # `safe` without ever rejecting on it. Mandibuzz sent a 58-HP Flygon into Stealth
    # Rock plus a Rapid Spin; it died without moving and Mandibuzz walked back through
    # the rocks (bulky_vs_balance 196613 t51).
    #
    # Charged on the MINIMUM damage roll, so only a candidate that dies on every roll
    # pays, and charged rather than HARD_REJECTed so a forced replacement still ranks
    # the least bad body instead of falling through to slot order.
    #
    # 500, not the ~300 the backlog entry proposed, and the corpus is why: on
    # a_dying_switch_in_is_not_worth_sending the candidate scores 385.9 against a
    # 59.8 move, so 300 left the corpse ahead by 26 points and the card failed on the
    # build that was supposed to fix it. 500 is not a fitted number either -- it is
    # what this scorer already pays for a knockout, and handing the opponent a free one
    # is the same event seen from the other side.
    if config["entry_death"] && config["entry_rules"] &&
       action.key?("entry_damage_pct") && action.key?("incoming_damage_pct")
      left = Model.number(action["candidate_hp_pct"], 100.0) -
             Model.number(action["entry_damage_pct"], 0.0) -
             entry_hit_pct(action) * MIN_DAMAGE_ROLL
      if left <= 0
        out_score -= 500
        reasons << ["dies_on_entry", -500]
      end
    end
    if config["ability_rules"] && actor_ability(actor) == "REGENERATOR" &&
       Model.number(actor["hp_pct"], 100) < 66
      # Reborn INTENDS this (healscore += 40/50 at :13415 and :13792) but the guard is
      # `hp/totalhp < (2/3)`, and (2/3) is Ruby integer division = 0, so it has never
      # once fired. Implemented here as the intent, and deliberately NOT added to
      # SWITCH_ESCAPE_REASONS: regenerating is a discount on leaving, never a reason to.
      out_score += 50
      reasons << ["regenerator_pivot", 50]
    end
    if config["memory"] && memory_count(snapshot, actor["index"], "switch") > 1
      out_score -= 120
      reasons << ["switch_loop", -120]
    end

    # The gate. Without a named reason to leave, the switch is not considered at all,
    # so the actor falls through to its moves — the shape of Reborn Intense's
    # `next if shouldSwitchintense?` (PokeBattle_AI_2.rb:1571), rather than the
    # non-Intense `shouldswitchscore > maxmovescore` comparison at :1576.
    if config["switch_gate"] && escapes.empty? && !Model.truthy(action["forced"])
      reasons << ["no_escape_reason", HARD_REJECT]
      return HARD_REJECT
    end
    reasons << ["escape_reasons", escapes.length] if !escapes.empty?
    out_score
  end

  def self.choose_joint(snapshot, scored_by_actor, config)
    if scored_by_actor.length == 1 || !config["coordination"]
      return [scored_by_actor.map { |items| items[0] }, 0]
    end

    candidates = scored_by_actor
    if (config["doubles_adversarial"] || config["doubles_search"]) && doubles?(snapshot)
      candidates = scored_by_actor.map { |items| prune_doubles_candidates(items, 5) }
    end

    best_actions = nil
    best_score = nil
    best_adjustment = 0
    candidates[0].each do |left|
      candidates[1].each do |right|
        next if left["type"] == "switch" && right["type"] == "switch" &&
                left["slot"].to_i == right["slot"].to_i
        adjustment = joint_adjustment(snapshot, left, right, config)
        score = left["score"] + right["score"] + adjustment
        pair = [left, right]
        if best_score.nil? || score > best_score ||
           (score == best_score && pair_key(pair) < pair_key(best_actions))
          best_actions = pair
          best_score = score
          best_adjustment = adjustment
        end
      end
    end
    raise ArgumentError, "no legal joint action pair" if best_actions.nil?
    [best_actions, best_adjustment]
  end

  # Keep search cost bounded without reducing every actor to its five highest raw
  # scores. Doubles plans often depend on one lower-ranked Protect, redirect, speed
  # control, Fake Out, or switch candidate that creates a strong joint action.
  def self.prune_doubles_candidates(items, limit = 5)
    return items.dup if items.length <= limit
    selected = [items[0]]
    roles = %w[switch protect redirect field_speed first_turn_only]
    roles.each do |role|
      candidate = items.find do |item|
        !selected.include?(item) && doubles_candidate_role(item) == role
      end
      selected << candidate if candidate
      break if selected.length >= limit
    end
    items.each do |item|
      break if selected.length >= limit
      selected << item if !selected.include?(item)
    end
    selected
  end

  def self.doubles_candidate_role(action)
    return "switch" if action["type"] == "switch"
    tags = Effects.describe(action["move_id"].to_s, action["tags"])
    return "protect" if tags.include?("protect") || tags.include?("team_protect")
    return "redirect" if tags.include?("redirect")
    return "field_speed" if tags.include?("field_speed")
    return "first_turn_only" if tags.include?("first_turn_only")
    nil
  end

  def self.joint_adjustment(snapshot, left, right, config)
    if (config["doubles_outcomes"] || config["doubles_search"]) && doubles?(snapshot)
      exact = doubles_outcome_value(snapshot, [left, right], config)
      independent = doubles_independent_outcome_value(snapshot, left, config) +
                    doubles_independent_outcome_value(snapshot, right, config)
      return exact - independent + doubles_combo_adjustment(snapshot, left, right, config)
    end
    adjustment = 0
    if left["type"] == "switch" && right["type"] == "switch" &&
       left["slot"].to_i == right["slot"].to_i
      return HARD_REJECT
    end

    if single_target_move?(left) && single_target_move?(right) &&
       left["target"] == right["target"]
      target = target_for(snapshot, left["target"])
      hp = target ? Model.number(target["hp_pct"], 100) : 100
      dl = Model.number(left["expected_damage_pct"], 0)
      dr = Model.number(right["expected_damage_pct"], 0)
      if (dl >= hp || dr >= hp) && alternate_live_target?(snapshot, left["target"])
        adjustment -= 400
      elsif dl + dr > hp * 1.5 && alternate_live_target?(snapshot, left["target"])
        adjustment -= 180
      end
    elsif single_target_move?(left) && single_target_move?(right) &&
          left["target"] != right["target"]
      adjustment += 25
      [left, right].each do |action|
        target = target_for(snapshot, action["target"])
        if target && Model.number(target["hp_pct"], 100) <= 35
          quality = Model.number(action["effectiveness"], 1) * 100
          adjustment += quality
        end
      end
    end

    adjustment += doubles_combo_adjustment(snapshot, left, right, config)
    adjustment
  end

  # Score interactions whose value only exists when both active Pokemon choose their
  # actions together. Individual move scoring cannot see these combinations.
  def self.doubles_combo_adjustment(snapshot, left, right, config)
    return 0 if !doubles?(snapshot)
    pairs = [[left, right], [right, left]]
    adjustment = 0

    pairs.each do |support, partner|
      support_tags = Effects.describe(support["move_id"].to_s, support["tags"])
      partner_tags = Effects.describe(partner["move_id"].to_s, partner["tags"])

      if config["protect_spread_combo"] && support_tags.include?("protect") &&
         Model.truthy(partner["spread"])
        friendly = Model.number(partner["friendly_fire_pct"], 0.0)
        if friendly > 0
          protected_actor = actor_for(snapshot, support["actor_index"])
          protected_hp = protected_actor ? Model.number(protected_actor["hp_pct"], 100.0) : 100.0
          refund = friendly * 3
          refund += 700 if friendly >= protected_hp
          adjustment += refund
        end
      end

      if config["partner_support_combo"] && support_tags.include?("partner_support") &&
         Model.truthy(partner["damaging"])
        targets_partner = support["target"].nil? ||
                          support["target"] == partner["actor_index"]
        if targets_partner
          adjustment += [40.0, Model.number(partner["expected_damage_pct"], 0.0) * 0.5].max
        end
      end

      if config["redirect_setup_combo"] && support_tags.include?("redirect") &&
         (partner_tags.include?("setup") || partner_tags.include?("field_speed"))
        protected_actor = actor_for(snapshot, partner["actor_index"])
        adjustment += protected_actor && threatened_lethal?(protected_actor) ? 160 : 70
      end

      if config["fakeout_speed_combo"] && support_tags.include?("first_turn_only") &&
         Model.truthy(support["damaging"]) && partner_tags.include?("field_speed")
        adjustment += 100
      end
    end
    adjustment
  end

  # Resolve both allied actions against plausible opposing attacks. Each foe's strongest
  # known attack is tried into either ally, yielding four response scenarios on a full
  # doubles board. Hit/miss branches remain probabilistic inside each scenario.
  def self.doubles_outcome_value(snapshot, actions, config)
    responses = doubles_response_scenarios(snapshot, config)
    responses = [{ "actions" => [], "weight" => 1.0 }] if responses.empty?
    variants = [actions]
    if actions.length == 2 &&
       Model.number(actions[0]["priority"], 0) == Model.number(actions[1]["priority"], 0) &&
       doubles_action_speed(snapshot, actions[0]) == doubles_action_speed(snapshot, actions[1])
      variants = [
        [actions[0].merge("tie_order" => 0), actions[1].merge("tie_order" => 1)],
        [actions[0].merge("tie_order" => 1), actions[1].merge("tie_order" => 0)]
      ]
    end
    total = 0.0
    response_values = []
    responses.each do |response|
      response_total = 0.0
      variants.each do |variant|
        value = doubles_timeline_value(snapshot, variant + response["actions"], config)
        total += response["weight"] * value
        response_total += value
      end
      response_values << [response_total / variants.length, response["weight"]]
    end
    expected = total / variants.length
    if config["doubles_search"]
      return doubles_search_response_value(response_values, config["search_foe_mix"])
    end
    return expected if !config["doubles_adversarial"]
    robust_doubles_value(response_values)
  end

  # The best measured native singles search used a 0.5 blend between pick_safest's
  # worst reply and the opponent-weighted expectation. Keep the mix configurable
  # through the same key so a doubles sweep asks the same policy question.
  def self.doubles_search_response_value(weighted_values, mix)
    credible = weighted_values.select { |pair| Model.number(pair[1], 0.0) > 0.0 }
    return 0.0 if credible.empty?
    expected = credible.inject(0.0) do |sum, pair|
      sum + Model.number(pair[0], 0.0) * Model.number(pair[1], 0.0)
    end
    amount = Model.number(mix, 0.5)
    amount = 0.0 if amount < 0.0
    amount = 1.0 if amount > 1.0
    worst = credible.map { |pair| Model.number(pair[0], 0.0) }.min
    worst * (1.0 - amount) + expected * amount
  end

  # Foul Play's search is strong partly because it does not trust a single predicted
  # reply. This shallow analogue values the probability-weighted result while charging
  # for the most punishing credible response and retaining a small upside term.
  def self.robust_doubles_value(weighted_values)
    credible = weighted_values.select { |pair| Model.number(pair[1], 0.0) > 0.0 }
    return 0.0 if credible.empty?
    expected = credible.inject(0.0) do |sum, pair|
      sum + Model.number(pair[0], 0.0) * Model.number(pair[1], 0.0)
    end
    values = credible.map { |pair| Model.number(pair[0], 0.0) }
    expected * 0.6 + values.min * 0.3 + values.max * 0.1
  end

  def self.doubles_timeline_value(snapshot, actions, config = {})
    ordered = actions.sort do |a, b|
      pa = Model.number(a["priority"], 0)
      pb = Model.number(b["priority"], 0)
      if pa != pb
        pb <=> pa
      else
        sa = doubles_action_speed(snapshot, a)
        sb = doubles_action_speed(snapshot, b)
        cmp = snapshot["trick_room_active"] ? sa <=> sb : sb <=> sa
        if cmp == 0 && !a["tie_order"].nil? && !b["tie_order"].nil?
          a["tie_order"] <=> b["tie_order"]
        else
          cmp == 0 ? a["actor_index"].to_i <=> b["actor_index"].to_i : cmp
        end
      end
    end
    state = { "hp" => {}, "protected" => {}, "flinched" => {},
              "value" => 0.0, "probability" => 1.0 }
    (snapshot["targets"] + snapshot["actors"]).each do |mon|
      state["hp"][mon["index"]] = Model.number(mon["hp_pct"], 100.0)
    end
    states = [state]
    ordered.each do |action|
        next_states = []
        states.each do |current|
          idx = action["actor_index"]
          if current["hp"][idx] <= 0
            next_states << current
            next
          end
          if current["flinched"][idx]
            next_states << current
            next
          end
          if action["foe_response"]
            if action["utility_response"]
              apply_foe_utility(current, action, snapshot)
              next_states << current
              next
            end
            target = actor_for(snapshot, action["target"])
            if !target || current["hp"][target["index"]] <= 0 ||
               current["protected"][target["index"]]
              next_states << current
            else
              next_states.concat(doubles_hit_branches([current], target["index"],
                { "damage_pct" => action["expected_damage_pct"],
                  "accuracy" => action["accuracy"] }, action, target, "enemy", config))
            end
            next
          end
          tags = Effects.describe(action["move_id"], action["tags"])
          if action["type"] == "move" && tags.include?("protect") &&
             memory_count(snapshot, idx, "protect") == 0 && !action["immune"]
            current["protected"][idx] = true
          end
          if !action["outcome_scored"]
            next_states << current
            next
          end
          hits = action["damage_by_target"]
          if !hits
            hits = { action["target"].to_s => {
              "damage_pct" => action["immune"] ? 0.0 : action["expected_damage_pct"],
              "accuracy" => action["accuracy"] } }
          end
          branches = [current]
          hits.each do |target_index, hit|
            resolved_index = target_index
            if !Model.truthy(action["spread"]) && current["redirector"] &&
               current["hp"][current["redirector"]].to_f > 0
              resolved_index = current["redirector"]
            end
            target = snapshot["targets"].find { |mon| mon["index"].to_s == resolved_index.to_s }
            next if target.nil?
            exposed = []
            branches.each do |branch|
              if branch["protected"][target["index"]] &&
                 action["opponent_protect_blocks"] != false
                exposed << branch
              else
                exposed.concat(doubles_hit_branches(
                  [branch], target["index"], hit, action, target, false, config))
              end
            end
            branches = exposed
          end
          friendly = Model.number(action["friendly_fire_pct"], 0)
          partner = snapshot["actors"].find { |mon| mon["index"] != idx }
          if friendly > 0 && partner
            exposed = []
            branches.each do |branch|
              if branch["protected"][partner["index"]] && action["partner_protect_blocks"] == true
                exposed << branch
              else
                exposed.concat(doubles_hit_branches([branch], partner["index"],
                  { "damage_pct" => friendly, "accuracy" => action["accuracy"] },
                  action, partner, "friendly", config))
              end
            end
            branches = exposed
          end
          next_states.concat(branches)
        end
        states = next_states
    end
    states.inject(0.0) { |sum, current| sum + current["value"] * current["probability"] }
  end

  def self.doubles_action_speed(snapshot, action)
    return Model.number(action["speed"], 0) if action["foe_response"]
    actor = actor_for(snapshot, action["actor_index"])
    actor ? Model.number(actor["speed"], 0) : 0
  end

  def self.apply_foe_utility(state, action, snapshot)
    kind = action["utility_response"]
    case kind
    when "protect"
      state["protected"][action["actor_index"]] = true
    when "team_protect"
      (snapshot["targets"] || []).each do |foe|
        state["protected"][foe["index"]] = true if state["hp"][foe["index"]].to_f > 0
      end
    when "redirect"
      state["redirector"] = action["actor_index"]
    when "field_speed"
      state["value"] -= Model.number(action["utility_value"], 104.0)
    when "status", "disrupt"
      state["value"] -= 60.0
    when "setup"
      state["value"] -= 70.0
    when "screen"
      state["value"] -= 60.0
    when "partner_support"
      state["value"] -= 50.0
    end
  end

  def self.doubles_response_scenarios(snapshot, config = {})
    actors = snapshot["actors"] || []
    return [] if actors.length != 2
    scenarios = [{ "actions" => [], "weight" => 1.0 }]
    (snapshot["targets"] || []).each do |foe|
      choices = []
      actors.each do |actor|
        threats = actor["threats_by_foe"] || {}
        threat = threats[foe["index"].to_s] || threats[foe["index"]]
        next if !threat || Model.number(threat["damage_pct"], 0) <= 0
        choices << {
          "foe_response" => true, "actor_index" => foe["index"],
          "target" => actor["index"], "expected_damage_pct" => threat["damage_pct"],
          "accuracy" => threat["accuracy"], "priority" => threat["priority"],
          "speed" => foe["speed"], "target_full_hp" => actor["full_hp"],
          "target_item" => actor["item"], "target_ability" => actor["ability"]
        }
      end
      attack_probability = [[Model.number(foe["attack_probability"], 1.0), 0.0].max, 1.0].min
      attack_probability = 0.0 if choices.empty?
      options = choices.map do |choice|
        { "action" => choice, "weight" => attack_probability / choices.length }
      end
      if attack_probability < 1.0
        utility = config["opponent_utility"] ? foe["utility_response"] : nil
        utility_action = nil
        if utility
          utility_action = {
            "foe_response" => true, "utility_response" => utility["kind"],
            "utility_value" => utility["value"], "actor_index" => foe["index"],
            "priority" => utility["priority"], "speed" => foe["speed"]
          }
        end
        options << { "action" => utility_action, "weight" => 1.0 - attack_probability }
      end
      expanded = []
      scenarios.each do |scenario|
        options.each do |option|
          actions = scenario["actions"].dup
          actions << option["action"] if option["action"]
          expanded << {
            "actions" => actions,
            "weight" => scenario["weight"] * option["weight"]
          }
        end
      end
      scenarios = expanded
    end
    scenarios
  end

  # The damage value already present in each independently scored action. Subtract it
  # before adding the exact pair result so every hit and KO is counted once.
  def self.doubles_independent_outcome_value(snapshot, action, config)
    return 0.0 if !action["outcome_scored"]
    value = 0.0
    if Model.truthy(action["spread"])
      damage = action["damage_by_target"].inject(0.0) do |sum, pair|
        sum + Model.number(pair[1]["damage_pct"], 0)
      end
      value = [damage, 100.0].min * 0.8
      # Spread attacks use one accuracy roll for all targets.
      value *= accuracy_factor(action, config)
    else
      target = target_for(snapshot, action["target"])
      hp = target ? Model.number(target["hp_pct"], 100) : 100
      damage = Model.number(action["expected_damage_pct"], 0)
      lethal = damage >= hp && hp > 0
      value = damage_value(lethal, damage) * accuracy_factor(action, config)
    end
    friendly = Model.number(action["friendly_fire_pct"], 0)
    if friendly > 0
      partner_hp = Model.number(action["partner_hp_pct"], 100)
      value -= friendly * 3
      value -= 700 if friendly >= partner_hp
    end
    value
  end

  def self.doubles_hit_branches(states, index, hit, action, target, cost_kind, config = {})
    accuracy = Model.number(hit["accuracy"], 100.0)
    accuracy = 100.0 if accuracy <= 0 # engine convention: always hits
    chance = [[accuracy / 100.0, 0.0].max, 1.0].min
    damage = [Model.number(hit["damage_pct"], 0.0), 0.0].max
    out = []
    states.each do |state|
      hp = state["hp"][index]
      if hp <= 0 || damage <= 0
        out << state
        next
      end
      if chance < 1.0
        miss = state.merge("hp" => state["hp"].dup,
                           "protected" => state["protected"].dup,
                           "flinched" => state["flinched"].dup)
        miss["probability"] *= 1.0 - chance
        out << miss
      end
      landed = state.merge("hp" => state["hp"].dup,
                           "protected" => state["protected"].dup,
                           "flinched" => state["flinched"].dup)
      actual = [damage, hp].min
      # Break a full-HP Sash/Sturdy once; a later hit can finish the target.
      if hp >= 100 && one_hit_guard?(action, target) && !action["multi_hit"]
        actual = [actual, hp - 0.01].min
      end
      landed["hp"][index] = hp - actual
      if config["fakeout_timeline"] && action["move_id"].to_s.upcase == "FAKEOUT" &&
         (target["ability"] || "").to_s.upcase != "INNERFOCUS" &&
         (target["ability"] || "").to_s.upcase != "SHIELDDUST" &&
         !Model.truthy(target["substitute"])
        landed["flinched"][index] = true
      end
      landed["probability"] *= chance
      if cost_kind == "friendly"
        if config["doubles_search"] && config["doubles_search_leaf"]
          landed["value"] -= actual + (actual >= hp ? 30.0 : 0.0)
        else
          landed["value"] -= actual * 3.0
          landed["value"] -= 700.0 if actual >= hp
        end
      elsif cost_kind == "enemy"
        # Zero-sum with our own damage: ordinary chip is worth 0.8 per percent and a
        # knockout is 500. Friendly fire stays much harsher because it is avoidable.
        if config["doubles_search"] && config["doubles_search_leaf"]
          landed["value"] -= actual + (actual >= hp ? 30.0 : 0.0)
        else
          initial = Model.number(target["hp_pct"], 100.0)
          before = (initial - hp) * 0.8
          after = actual >= hp ? 500.0 : (initial - hp + actual) * 0.8
          landed["value"] -= after - before
        end
      else
        # Marginal value: the second hit earns the remaining KO value, never a
        # second full KO bonus for a foe the first hit already defeated.
        if config["doubles_search"] && config["doubles_search_leaf"]
          landed["value"] += actual + (actual >= hp ? 30.0 : 0.0)
        else
          initial = Model.number(target["hp_pct"], 100.0)
          before = (initial - hp) * 0.8
          after = actual >= hp ? 500.0 : (initial - hp + actual) * 0.8
          landed["value"] += after - before
        end
      end
      out << landed
    end
    out
  end

  def self.actor_for(snapshot, index)
    snapshot["actors"].each { |actor| return actor if actor["index"] == index }
    nil
  end

  def self.single_target_move?(action)
    return false if action.nil? || action["type"] != "move"
    !Model.truthy(action["spread"]) && !action["target"].nil?
  end

  def self.alternate_live_target?(snapshot, used_index)
    snapshot["targets"].any? do |target|
      target["index"] != used_index && Model.number(target["hp_pct"], 0) > 0
    end
  end

  def self.target_for(snapshot, index)
    return nil if index.nil?
    snapshot["targets"].each { |target| return target if target["index"] == index }
    snapshot["actors"].each { |actor| return actor if actor["index"] == index }
    nil
  end

  def self.occupied_status?(status)
    return false if status.nil? || status == 0 || status == "0"
    value = status.to_s.downcase
    value != "" && value != "none" && value != "healthy"
  end

  # pbRoughDamage is a single deterministic number, but the engine rolls 85-100% of it.
  # A rule that costs a move 400 points should only fire where no roll rescues the
  # battler, so "this hit kills me" is tested against the LOW roll rather than the
  # estimate. The estimate itself still answers the softer question of whether healing
  # might help (threatened_lethal?), which is what earns the bonus.
  MIN_DAMAGE_ROLL = 0.85

  # What a move the actor will not live to click keeps of its score (dead_before_
  # moving). Not zero: the death is certain only on the estimate, and a quarter keeps
  # the moves ranked among themselves for the turns where no switch is allowed.
  DEAD_BEFORE_MOVING_SCALE = 0.25

  # The incoming hit kills through any damage roll, not merely through the estimate.
  # threatened_lethal? is the softer question and stays what the 0.3.2 rules ask.
  def self.certain_lethal_threat?(actor, config = {})
    hp = Model.number(actor["hp_pct"], 100.0)
    return false if hp <= 0
    # 0.6.6. When the adapter knows which move the foe has committed to, THAT hit is
    # the one that decides whether death is certain -- a declared Toxic makes it
    # false whatever the foe's Earthquake would have done, and a declared 95% Air
    # Slash makes it nearly true where strict_threat's "under 100% is 0%" made it
    # false (Xatu at 28% Roosted into a 48% Air Slash, gen5uu_a team1_vs_team2 104729
    # t30). The figure is the declared hit on its minimum roll, discounted by its
    # hit chance: no threshold constant, and a 70% Focus Blast has to overkill by a
    # third before it counts as certain. Absent, the 0.6.5 predicate stands.
    if actor.key?("predicted_incoming_damage_pct")
      hit = Model.number(actor["predicted_incoming_damage_pct"], 0.0)
      accuracy = actor["predicted_incoming_accuracy"]
      hit *= [Model.number(accuracy, 100.0), 100.0].min / 100.0 if !accuracy.nil?
      return hit * MIN_DAMAGE_ROLL >= hp
    end
    incoming = actor["incoming_damage_pct"]
    # Under strict_threat only a hit that cannot fail to happen (100% accurate, foe
    # awake) makes death certain; adapters that export no such figure keep the loose
    # one, so the key is inert where the evidence is missing.
    strict = actor["certain_incoming_damage_pct"]
    incoming = strict if config["strict_threat"] && !strict.nil?
    return Model.truthy(actor["threatened_lethal"]) if incoming.nil?
    Model.number(incoming, 0.0) * MIN_DAMAGE_ROLL >= hp
  end

  # Tri-state speed order: true, false, or nil when the adapter exports none. Rules
  # that would cost the actor points treat nil as "faster", so a missing field never
  # penalises it; the priority gate skips itself entirely instead.
  def self.faster_flag(actor)
    value = actor["faster"]
    return nil if value.nil?
    Model.truthy(value)
  end

  # Reborn's (accuracy + 100) / 200 (PokeBattle_AI_2.rb:3349), softened by
  # config["accuracy_weight"] so 0 reproduces 0.3.2 and 1 is Reborn's own weight.
  # Adapters that export no accuracy contribute nothing.
  def self.accuracy_factor(action, config)
    weight = Model.number(config["accuracy_weight"],
                          Model::DEFAULT_CONFIG["accuracy_weight"])
    return 1.0 if weight == 0
    return 1.0 if !action.key?("accuracy") || action["accuracy"].nil?
    accuracy = Model.number(action["accuracy"], 100.0)
    accuracy = 100.0 if accuracy > 100.0
    accuracy = 0.0 if accuracy < 0
    1.0 + (((accuracy + 100.0) / 200.0) - 1.0) * weight
  end

  # Percentage points of maximum HP a recovery move restores, in the same units as
  # hp_pct and incoming_damage_pct.
  def self.heal_amount(snapshot, tags)
    Effects.heal_amount(snapshot, tags)
  end

  # Does healing change who is alive at the end of the turn? Reborn's recovercode
  # (PokeBattle_AI_2.rb:7558) asks that; Portable 0.3.2 scored recovery on the healer's
  # own HP alone, which is why a quarter of its heals were the healer's last act and
  # 61% of the ones below 25% HP were (PORTABLE-AI-DIAGNOSIS.md section 2). These are
  # Reborn's multipliers rewritten as additive score units, plus the question Reborn
  # never asks -- whether it moves first -- which costs Reborn 18% of its own slow
  # heals. The existing hp_pct bonuses stay underneath: this rule only fires when the
  # actor is actually being threatened, so the plain low-HP heal is untouched.
  def self.heal_gate(snapshot, actor, action, tags, score, reasons, config = {})
    hp = Model.number(actor["hp_pct"], 100.0)
    incoming = Model.number(actor["incoming_damage_pct"], 0.0)
    # threatened_lethal is the adapter's own verdict; honour it when the raw number is
    # absent or disagrees.
    incoming = hp if Model.truthy(actor["threatened_lethal"]) && incoming < hp
    heal = heal_amount(snapshot, tags)
    headroom = 100.0 - hp
    heal = headroom if heal > headroom
    heal = 0.0 if heal < 0
    faster = faster_flag(actor)
    # Penalise only what no damage roll can rescue; reward wherever the heal might be
    # what survives the turn.
    will_die = certain_lethal_threat?(actor, config)
    might_die = threatened_lethal?(actor)

    if will_die && faster == false
      score -= 400
      reasons << ["heal_cannot_resolve", -400]
    elsif will_die && incoming * MIN_DAMAGE_ROLL >= hp + heal
      score -= 400
      reasons << ["heal_does_not_save", -400]
    elsif might_die
      # 0.6.3. A heal that restores less than the next hit takes, while the race is
      # already lost, saves nothing: it buys one turn at a net loss and the same
      # question comes back a turn later, a little lower. Zapdos at 13% Roosted +50
      # into a 57% Lava Plume five turns running and every one was scored a save
      # (Realidea shadow run, team3_vs_team1 155921 t23-28; 43 such turns in 3,033,
      # all 43 in a lost race). Charged what heal_losing_race charges outside a
      # threat, because it is the same fact with worse timing -- and so that a bench
      # candidate, once race_switch_to_winner opens the gate, can be heard over it.
      lost = config["heal_outpace"] ? worst_race(snapshot, actor, config) : nil
      if race_lost_by_a_hit?(lost) && heal <= incoming
        score -= 120
        reasons << ["heal_only_delays", -120]
      else
        score += 150
        reasons << ["heal_saves_battler", 150]
      end
    elsif incoming > heal
      score -= 120
      reasons << ["heal_losing_race", -120]
    end

    # Reborn's x0.3 when the foe is on its last Pokemon and a KO is in hand: there is
    # nothing left to outlast.
    if Model.number(action["foe_reserves"], 1) <= 0 && has_lethal_move?(snapshot, actor)
      score -= 200
      reasons << ["finish_instead_of_heal", -200]
    end
    score
  end

  # Every damaging action of this actor that can actually land, with the target each
  # one is scored against. has_lethal_move? and damage_race must agree on what counts
  # as "a hit on that target", so the matching lives here once. A spread move and a
  # single-foe snapshot's untargeted move both count against whichever target is asked
  # about, which is the same latitude has_lethal_move? has always taken.
  def self.each_damaging_action(snapshot, actor, only_target = nil)
    (actor["actions"] || []).each do |other|
      next if other["type"] != "move"
      next if !Model.truthy(other["damaging"]) || Model.truthy(other["immune"])
      next if Model.number(other["effectiveness"], 1.0) <= 0
      target = target_for(snapshot, other["target"])
      if !only_target.nil?
        aimed = (other["target"] == only_target["index"]) ||
                Model.truthy(other["spread"]) ||
                (other["target"].nil? && (snapshot["targets"] || []).length <= 1)
        next if !aimed
        target = only_target
      end
      target_hp = target ? Model.number(target["hp_pct"], 100.0) :
                           Model.number(other["target_hp_pct"], 100.0)
      next if target_hp <= 0
      yield other, target, target_hp
    end
  end

  def self.has_lethal_move?(snapshot, actor)
    each_damaging_action(snapshot, actor) do |other, _target, target_hp|
      return true if Model.number(other["expected_damage_pct"], 0.0) >= target_hp
    end
    false
  end

  # HOW MANY HITS EACH SIDE NEEDS, AND WHO LANDS THE LAST ONE.
  #
  # Every other rule in this core asks a one-hit question -- does the next hit kill me,
  # does my next hit kill it. This is the two-hit question a bulky team plays by.
  # Reborn has no explicit hits-to-KO either, but `maxdam*2 > hp` gates its setup
  # (PokeBattle_AI_2.rb:6007), its recovery (:7588) and Rest (:7667), hpGainPerTurn
  # (:10112) folds residual into the same comparison, and pbAIfaster? (:10051) orders
  # the final hit per move PAIR -- so a priority move on either side rewrites who lands
  # last. Radical Red states the same thing in five lines (ANALYSIS.md :655-684).
  #
  # Pure: it reads the snapshot and nothing else, so the adapter can call it on a
  # snapshot it has just built (view_trace does exactly that). Returns nil the moment
  # an input is missing -- an adapter with no threats_by_foe, an actor with no damaging
  # move -- and every consumer is written to go inert on nil. That is the same "a
  # missing field never penalises the actor" contract as faster_flag.
  #
  # Point estimates, not low rolls. The race is the soft question, the way
  # threatened_lethal? is; the consumers only ever withhold a bonus or add an escape
  # reason, never a -400. Accuracy is deliberately ignored, as Reborn's maxdam ignores
  # it too.
  def self.damage_race(snapshot, actor, target, config)
    return nil if !config["damage_race"] || actor.nil? || target.nil?

    target_hp = Model.number(target["hp_pct"], 100.0)
    actor_hp = Model.number(actor["hp_pct"], 100.0)
    return nil if target_hp <= 0 || actor_hp <= 0

    mine_best = 0.0
    mine_priority = 0.0
    guard = false
    each_damaging_action(snapshot, actor, target) do |other, target_view, _hp|
      damage = Model.number(other["expected_damage_pct"], 0.0)
      next if damage <= 0
      mine_best = damage if damage > mine_best
      guard = true if one_hit_guard?(other, target_view) && damage >= target_hp
      mine_priority = damage if Model.number(other["priority"], 0) > 0 &&
                                damage > mine_priority
    end

    # A race needs both sides. With no hit of my own on this target there is no
    # hit-count question to answer, and the rules that already cover that position
    # (no_effective_move, weak_current_attacks) are the ones that should speak.
    return nil if mine_best <= 0

    threats = actor["threats_by_foe"]
    return nil if threats.nil?
    threat = threats[target["index"].to_s] || threats[target["index"]]
    return nil if threat.nil?
    theirs_best = Model.number(threat["damage_pct"], 0.0)
    theirs_priority = Model.number(threat["priority_damage_pct"], 0.0)
    faster = threat["faster"]
    faster = nil if faster != true && faster != false

    # Sturdy and Focus Sash do not reduce the hit, they cost a whole extra one: the
    # blow that would have killed leaves the target on 1 HP. This is the ONE place the
    # guard belongs -- 0.5.0 deliberately left the kill call alone (see the note in
    # score_move), because cancelling `lethal` deletes the move's value, whereas
    # spending a hit is exactly what the guard actually does.
    mine = hits_needed(target_hp, mine_best)
    mine += 1 if !mine.nil? && guard && mine < RACE_MAX_HITS

    # Residual is on MY side only: the actor's own toxic and leech are exported, the
    # foe's are not. Reborn's hpGainPerTurn is the same one-sided term.
    residual = Model.number(actor["residual_damage_pct"], 0.0)
    theirs = hits_needed(actor_hp, theirs_best + residual)

    winning = nil
    last_hit_first = nil
    if !mine.nil? && !theirs.nil?
      if mine < theirs
        # A hit-count gap cannot be closed by speed or priority: the side needing
        # fewer hits simply finishes on an earlier turn.
        winning = true
      elsif mine > theirs
        winning = false
      else
        # Equal counts, so the exchange is decided by who lands the FINAL hit. This is
        # pbAIfaster?(attackermove, opponentmove) restricted to the last exchange: a
        # priority move only decides it if it is big enough to finish the job.
        mine_finishes = mine_priority > 0 &&
                        mine_priority >= target_hp - (mine - 1) * mine_best
        theirs_finishes = theirs_priority > 0 &&
                          theirs_priority >= actor_hp - (theirs - 1) * (theirs_best + residual)
        if mine_finishes && !theirs_finishes
          last_hit_first = true
        elsif theirs_finishes && !mine_finishes
          last_hit_first = false
        else
          last_hit_first = faster
        end
        winning = last_hit_first if !last_hit_first.nil?
      end
    end

    { "mine" => mine, "theirs" => theirs, "faster" => faster,
      "last_hit_first" => last_hit_first, "winning" => winning }
  end


  # "The foe kills me in two and I do not move first." Silent -- false, never a
  # penalty -- whenever the race is unavailable.
  # The race against whichever current foe the actor is doing worst against. In
  # singles that is the only foe; in doubles, losing to either one is a reason to
  # leave. nil when no target yields a race at all.
  # Radical Red's switch-in table, scaled x5 into Portable's switch units. The bands
  # are hits the FOE needs to knock this candidate out; the +70 is for outrunning it.
  # Keyed off the candidate's own HP, not 100%, because a chipped bench mon that dies
  # in one is exactly the candidate this is meant to refuse.
  # Radical Red's switch-in table, scaled x5 into Portable's switch units (a neutral
  # matchup is 32 there, and one super-effective step is another 32). The bands are
  # how many hits the FOE needs to knock this candidate out.
  SWITCHIN_RACE_OUTSPEED = 70

  # 0.6.6. THE HIT A SWITCH CANDIDATE EATS ON THE WAY IN. The adapter's
  # incoming_damage_pct is the worst the foe has against the candidate. When it also
  # knows which move the foe has committed to -- predicted_incoming_damage_pct, the
  # oracle arm today and a predictor's export later -- that is the entry hit, and the
  # worst case stays what the exchange AFTER entry is run on (candidate_race,
  # switchin_race_bonus): the foe is committed for one turn, not for the race. Absent,
  # this is the 0.6.5 number, so every consumer is unchanged on a run without it.
  def self.entry_hit_pct(action)
    key = action.key?("predicted_incoming_damage_pct") ?
          "predicted_incoming_damage_pct" : "incoming_damage_pct"
    Model.number(action[key], 0.0)
  end

  def self.switchin_race_bonus(action)
    # The candidate's OWN hp, not 100: a chipped bench mon that dies in one is exactly
    # the candidate this is here to refuse.
    hp = Model.number(action["candidate_hp_pct"], 100.0)
    hp = 100.0 if hp <= 0
    theirs = hits_needed(hp, Model.number(action["incoming_damage_pct"], 0.0))
    bonus = 0
    if theirs.nil? || theirs >= 4
      bonus += 85            # nothing the foe has gets through in a hurry
    elsif theirs == 3
      bonus += 10
    elsif theirs == 2
      bonus -= 5
    else
      bonus -= 70            # it dies on the turn it arrives
    end
    # Reborn scales a switch-in's damage OUTPUT by whether it outruns the foe
    # (:11755-11764, x1.5 against x0.75), so the premium belongs to a candidate that
    # has output to scale. One that deals nothing gains nothing by moving first.
    if action["faster"] == true &&
       Model.number(action["outgoing_damage_pct"], 0.0) > 0
      bonus += SWITCHIN_RACE_OUTSPEED
    end
    bonus
  end

  def self.worst_race(snapshot, actor, config)
    worst_race_with_target(snapshot, actor, config)[0]
  end

  # The same, keeping WHICH foe it is: the bench candidate's race has to be run against
  # the foe the actor is actually losing to. [nil, nil] when no target yields a race.
  def self.worst_race_with_target(snapshot, actor, config)
    worst = nil
    worst_target = nil
    (snapshot["targets"] || []).each do |target|
      race = damage_race(snapshot, actor, target, config)
      next if race.nil?
      if worst.nil? || race_rank(race) < race_rank(worst)
        worst = race
        worst_target = target
      end
    end
    [worst, worst_target]
  end

  # damage_race's question asked of a BENCH candidate: once it is in, who lands the
  # last hit. The switch turn is paid for -- the candidate eats one free hit on entry,
  # on top of the hazards, and attacks nothing that turn -- and only then does the
  # exchange start. Built from the two estimates the adapter puts on the switch action
  # (switch_outgoing_damage / switch_incoming_damage); nil when either is missing, and
  # every consumer goes inert on nil, the contract damage_race keeps. Point estimates
  # and no priority term: the candidate's moves are not exported one by one, and this
  # is the soft question. `theirs` counts the free hit.
  def self.candidate_race(action, target)
    return nil if action.nil? || target.nil?
    return nil if !action.key?("outgoing_damage_pct") ||
                  !action.key?("incoming_damage_pct")
    target_hp = Model.number(target["hp_pct"], 100.0)
    return nil if target_hp <= 0
    incoming = Model.number(action["incoming_damage_pct"], 0.0)
    mine = hits_needed(target_hp, Model.number(action["outgoing_damage_pct"], 0.0))
    return nil if mine.nil?
    # At the cap the count carries no information (see RACE_MAX_HITS): a candidate
    # that needs eight or more hits is not winning a race, it is walling, and an
    # immune wall "wins" against anything by this arithmetic. Gengar into a Snorlax
    # mirror -- Body Slam does nothing to it, Shadow Ball does 7% -- was the case
    # (no_switch_full_hp_neutral, Reborn probe).
    return { "mine" => mine, "theirs" => nil, "winning" => false } if mine >= RACE_MAX_HITS
    # The free hit is the DECLARED one when the adapter knows it (entry_hit_pct);
    # the hits after it are the worst the foe has.
    left = Model.number(action["candidate_hp_pct"], 100.0) -
           Model.number(action["entry_damage_pct"], 0.0) - entry_hit_pct(action)
    return { "mine" => mine, "theirs" => 1, "winning" => false } if left <= 0
    more = hits_needed(left, incoming)
    winning = if more.nil? then true            # nothing of theirs gets through
              elsif mine < more then true
              elsif mine > more then false
              else action["faster"] == true
              end
    { "mine" => mine, "theirs" => (more.nil? ? nil : more + 1), "winning" => winning }
  end

  # Tri-state: true when the candidate's best hit on the current foes clears the
  # weak_current_attacks line (10% of the target), false when it does not, nil when
  # the adapter exported no estimate or the key is off -- and nil never withholds a
  # reason, the same contract every other missing field keeps.
  WEAK_ATTACK_PCT = 10

  #
  # 0.6.4 (escape_wall_margin): clearing the line is not enough. The bench estimate
  # and the field estimate are built from different battlers and disagree by a few
  # points, so a body at 11% on the bench read as weak once it stood there and went
  # straight back -- 62 of the 133 switch-backs left in the 0.6.3 run were that. The
  # candidate has to BEAT the actor at the actor's own game: two whole hits fewer to
  # the knockout, and no more than four of its own, against some foe on the field.
  # Both counts are hits_needed on the same foe HP, so the comparison is honest
  # about a chipped wall: at 40% a 15% hit is three, not "weak".
  WALL_BREAK_MARGIN = 2
  WALL_BREAK_MAX_HITS = 4

  # The foe needs this many hits or more to remove the actor -- the band
  # switchin_race_bonus calls "nothing the foe has gets through in a hurry" -- and the
  # actor has a non-damaging move that WORKS ON THE FOE OR THE FIELD and can still
  # land: a status, a hazard below its cap, a phaze, a disruption, a stage reset or
  # an item trick. Not a boost, a heal, a Substitute or a Protect -- those are what an
  # Alakazam has in front of a Toxic Umbreon, and doing them forever is not a plan;
  # the 0.6.3 card no_effective_move_needs_a_body_that_breaks_the_wall is exactly
  # that board and it must keep leaving. Residual damage counts against the actor
  # the way damage_race counts it. False without an incoming estimate: a missing
  # field never closes a gate that would otherwise open.
  WALL_SAFE_HITS = 4
  WALL_WORK_TAGS = %w[status hazard force_switch disrupt reset_stages item_control]

  def self.walled_but_safe?(actor)
    hp = Model.number(actor["hp_pct"], 100.0)
    return false if hp <= 0 || actor["incoming_damage_pct"].nil?
    per_hit = Model.number(actor["incoming_damage_pct"], 0.0) +
              Model.number(actor["residual_damage_pct"], 0.0)
    theirs = hits_needed(hp, per_hit)
    return false if !theirs.nil? && theirs < WALL_SAFE_HITS
    (actor["actions"] || []).any? do |other|
      next false if other["type"] != "move" || Model.truthy(other["damaging"])
      next false if Model.truthy(other["immune"])
      tags = Effects.describe(other["move_id"].to_s.upcase, other["tags"])
      next false if (tags & WALL_WORK_TAGS).empty?
      if tags.include?("hazard")
        next false if Model.number(other["existing_layers"], 0) >=
                      Model.number(other["max_layers"], 1)
      end
      true
    end
  end

  def self.candidate_can_hit?(snapshot, actor, action, config)
    return nil if !config["escape_needs_hitter"]
    return nil if !action.key?("outgoing_damage_pct") || action["outgoing_damage_pct"].nil?
    outgoing = Model.number(action["outgoing_damage_pct"], 0.0)
    return outgoing >= WEAK_ATTACK_PCT if !config["escape_wall_margin"]
    actor_best = Model.number(actor["best_damage_pct"], 0.0)
    live = (snapshot["targets"] || []).select { |t| Model.number(t["hp_pct"], 100.0) > 0 }
    return nil if live.empty?
    live.any? do |target|
      hp = Model.number(target["hp_pct"], 100.0)
      mine = hits_needed(hp, outgoing) || RACE_MAX_HITS
      actors = hits_needed(hp, actor_best) || RACE_MAX_HITS
      mine <= WALL_BREAK_MAX_HITS && mine <= actors - WALL_BREAK_MARGIN
    end
  end

  # KILL ORDER, GRADED. candidate_race's answer as a number: the margin in hits
  # between what the foe needs on the candidate (free hit included) and what the
  # candidate needs on the foe. Positive is "it finishes first", by that many hits;
  # zero is decided by speed. In doubles the candidate has to win against both, so
  # the worse of its two races is the one that counts. 0 without estimates and 0 at
  # the cap (a wall is graded by the defensive bands, not by a race it never
  # finishes), so every consumer is inert exactly where candidate_race is.
  #
  # The bands: a win by two whole hits is the Scizor-into-Espeon case and worth more
  # than 0.6.3's flat 110; one hit is that 110; a win on the tiebreak is worth
  # less, because the adapters call a speed tie "slower" and this is where that
  # error lives. The losing side mirrors it, short of the -500 a death on entry
  # already pays.
  KILL_ORDER_GRADES = { 2 => 150, 1 => 110, 0 => 70, -1 => -70, -2 => -110 }
  KILL_ORDER_TIE_LOST = -30

  def self.kill_order_grade(race)
    return 0 if race.nil? || race["mine"].nil? || race["mine"] >= RACE_MAX_HITS
    # `theirs` counts the free entry hit, which the candidate answers with nothing,
    # so the exchange proper is theirs - 1 against mine.
    theirs = race["theirs"].nil? ? RACE_MAX_HITS : race["theirs"]
    margin = (theirs - 1) - race["mine"]
    return (race["winning"] ? KILL_ORDER_GRADES[0] : KILL_ORDER_TIE_LOST) if margin == 0
    KILL_ORDER_GRADES[[[margin, -2].max, 2].min]
  end

  def self.candidate_race_grade(snapshot, action)
    worst = nil
    (snapshot["targets"] || []).each do |target|
      race = candidate_race(action, target)
      next if race.nil?
      grade = kill_order_grade(race)
      worst = grade if worst.nil? || grade < worst
    end
    worst || 0
  end

  # ---------------------------------------------------------------------------
  # 0.6.5. CONSUMERS OF THE PARTY x PARTY DAMAGE MATRIX.
  #
  # The readers themselves -- matrix_cell, cell_verdict, matrix_answers and the rest
  # -- moved to matrix.rb in 0.7.0, so the search planner can read the same board
  # without loading the rule engine. What stays here is what SCORES: the rules below
  # turn a verdict into a reason term. Both layers go inert together when the adapter
  # exports no snapshot["matrix"] (Reborn), which is what makes its gauntlet a control.

  # CONSUMER A. The only answer to a foe is not a body to spend.
  #
  # Read off the 0.6.4 shadow trace: stock sent its only answer to their Scizor into
  # an Azumarill it loses to, with a body on the bench that beats the Azumarill and
  # nothing else that beats the Scizor (team4_vs_team1 seed 130363, stock arm, a
  # 19-turn loss). No per-turn rule can see that, because on the turn it happens the
  # Azumarill is the only foe on the field and the candidate is simply losing to it.
  #
  # Both terms are negative and neither is an escape reason: this rule answers WHO
  # comes in, never whether to leave. Adding a gate-opener here would reopen the
  # switch programme the diagnosis closed (PORTABLE-AI-DIAGNOSIS.md §4).
  #
  # -150 is the top KILL_ORDER_GRADES band: trading away the only answer to something
  # is a future win thrown away by about that margin. It stays clear of the -500
  # dies_on_entry pays, so a candidate that dies this turn still ranks below one that
  # merely spends its later value. -45 is below the 70 tiebreak grade on purpose, so
  # the reserve term only reorders bodies that were otherwise inside one band.
  SOLE_ANSWER_EXPOSED = -150
  SOLE_ANSWER_EXPOSED_CAP = -300
  SOLE_ANSWER_RESERVED = -45
  SOLE_ANSWER_RESERVED_CAP = -135

  # [value, reason] or nil. Inert without the key, without a matrix, and for a
  # candidate whose only unique value is the foe already standing in front of it --
  # that body is answering it right now, which is what it is for.
  def self.sole_answer_value(snapshot, actor, action, config)
    return nil if !config["sole_answer"]
    m = matrix(snapshot)
    return nil if m.nil?
    slot = action["slot"]
    return nil if slot.nil?
    actor_slot = matrix_slot(m["own"], (actor || {})["index"])
    active = []
    (snapshot["targets"] || []).each do |t|
      next if t.nil? || Model.number(t["hp_pct"], 100.0) <= 0
      foe_slot = matrix_slot(m["foe"], t["index"])
      active << foe_slot if !foe_slot.nil? && !active.include?(foe_slot)
    end
    return nil if active.empty?

    # What this body is worth LATER: the live foes nothing else on the bench beats.
    # The foes on the field are excluded because their answer is being decided now,
    # by this very score.
    unique = sole_answers(snapshot, slot).reject { |foe_slot| active.include?(foe_slot) }
    return nil if unique.empty?

    # Someone else can take the turn in front. The actor is dropped from the pool
    # along with the candidate: it is the body leaving.
    covered = {}
    active.each do |foe_slot|
      covered[foe_slot] =
        !(matrix_answers(snapshot, foe_slot) - [slot, actor_slot]).empty?
    end

    # Doubles takes the harsher target, the candidate_race_grade convention: losing
    # to EITHER foe on the field exposes the body.
    exposed = active.any? do |foe_slot|
      matrix_verdict(snapshot, slot, foe_slot) == "L" && covered[foe_slot]
    end
    if exposed
      return [[SOLE_ANSWER_EXPOSED * unique.length, SOLE_ANSWER_EXPOSED_CAP].max,
              "sole_answer_exposed"]
    end

    # It beats what is in front -- and so does something else, so the turn does not
    # need this body in particular. This is the forced replacement's question: of the
    # bodies that all handle the board, send the one holding the least unique value.
    # Every active foe has to be covered, not just one: a foe only this body answers
    # is a foe it is needed against now.
    if active.all? { |foe_slot| matrix_verdict(snapshot, slot, foe_slot) == "W" } &&
       active.all? { |foe_slot| covered[foe_slot] }
      return [[SOLE_ANSWER_RESERVED * unique.length, SOLE_ANSWER_RESERVED_CAP].max,
              "sole_answer_reserved"]
    end
    nil
  end

  # CONSUMER B. A boost is worth the cells it flips.
  #
  # The first setup move of a battle has been paying a flat 55 since 0.3.0, whether
  # it wins the game or wastes the turn. A boost is a SWEEP: what it is worth is how
  # many of their remaining bodies stop beating this one, bench included, which is
  # exactly the question the matrix answers and no per-turn rule can.
  #
  # The four safety branches above (Contrary, Unaware, unsafe, setup_into_2hko) run
  # first and are untouched: this arm only ever replaces the flat bonus, so the worst
  # it can do is decline to pay it. It never returns a negative -- being punished for
  # setting up is what those branches are for.
  SETUP_FLIP_TO_WIN = 55
  SETUP_FLIP_TO_STALL = 25
  SETUP_FLIP_CAP = 220

  # {"value","reason"} or nil, and nil restores first_setup exactly: no matrix, no
  # stage row for this move, or no slot for the actor.
  def self.setup_matrix_value(snapshot, actor, action, config)
    stages = Effects.setup_stages(action["move_id"])
    return nil if stages.nil?
    m = matrix(snapshot)
    return nil if m.nil?
    own_slot = matrix_slot(m["own"], (actor || {})["index"])
    return nil if own_slot.nil?
    own = matrix_entry(m["own"], own_slot)
    return nil if own.nil?
    own_hp = Model.number(own["hp_pct"], 100.0)
    return nil if own_hp <= 0
    trick_room = Model.truthy(snapshot["trick_room_active"])

    # Which foes are on the field, by slot, and what the actor's own scoring already
    # knows about them. A boost is paid for in a turn, and the turn is spent in front
    # of these.
    active = {}
    (snapshot["targets"] || []).each do |t|
      next if t.nil? || Model.number(t["hp_pct"], 100.0) <= 0
      foe_slot = matrix_slot(m["foe"], t["index"])
      active[foe_slot] = t if !foe_slot.nil?
    end
    return nil if active.empty?

    transformed = {}
    matrix_live_slots(m["foe"]).each do |foe_slot|
      cell = matrix_cell(snapshot, own_slot, foe_slot)
      next if cell.nil?
      foe = matrix_entry(m["foe"], foe_slot)
      next if foe.nil?
      transformed[foe_slot] =
        matrix_transform_cell(cell, stages, own["speed"], foe["speed"], trick_room)
    end
    return nil if transformed.empty?

    # THE BUDGET IN FRONT: does the actor live to spend what it is buying? One turn for
    # the setup, then the hits the boosted attack still needs, against what the foe
    # needs to remove it. `theirs` prefers the actor's real per-foe threat
    # (damage_race, which carries residual, the priority order and the Choice lock)
    # over the cell, which carries none of those; it is deliberately the UNBOOSTED
    # number, because the defensive half of a boost cannot be spent on the turn it is
    # bought.
    #
    # Refuses only what it can actually see is unaffordable -- STRICTLY more turns than
    # the foe needs. A tie is not a refusal, and the 0.6.5 tier run is why: both
    # battles this rule lost were a boost declined at exactly `post + 1 == theirs`.
    # Scizor's Swords Dance in front of a Metagross it was winning against on Bullet
    # Punch priority (team2_vs_team1 262147 t2 -- the cells carry no priority term, so
    # the matrix reads that race as lost), and Clefable's Calm Mind against a Gliscor
    # at 76% (team3_vs_team1 104729 t52). In both, withholding the flat 55 handed the
    # turn to an attack and lost a battle 0.6.4 won. The genuinely dangerous boards --
    # the 2HKO, the low HP, the lethal threat -- are the four safety branches above,
    # which run first and are untouched; this test is only here for "you die before
    # you can use it".
    active.each do |foe_slot, target|
      cell = transformed[foe_slot]
      return { "value" => 0, "reason" => "setup_no_budget" } if cell.nil?
      foe_hp = Model.number(target["hp_pct"], 100.0)
      race = damage_race(snapshot, actor, target, config)
      theirs = race.nil? ? nil : race["theirs"]
      if race.nil?
        base = matrix_cell(snapshot, own_slot, foe_slot)
        theirs = base.nil? ? nil : hits_needed(own_hp, Model.number(base["in"], 0.0))
      end
      next if theirs.nil?           # nothing of theirs gets through: the turn is free
      post = hits_needed(foe_hp, Model.number(cell["out"], 0.0)) || RACE_MAX_HITS
      return { "value" => 0, "reason" => "setup_no_budget" } if post + 1 > theirs
    end

    # WHAT IT FLIPS, over their whole live party. A body that stops losing is the
    # win; a body that stops losing but only reaches a stall is worth less and still
    # worth something, because a stall is a body their sweeper has to answer.
    #
    # Three answers, not two, and the middle one is why. A boost that flips nothing
    # but still shortens a race the actor was already winning is NOT worthless -- the
    # probe said so: Heracross at 45% in front of a Shuckle it beats either way halves
    # its hit count with Swords Dance, and a rule that paid 0 there dropped the boost
    # behind Close Combat and broke `an_unboosted_sweeper_still_sets_up`, a card that
    # has held since 0.4.0. So this rule speaks only where it has something to say:
    # it pays for flips, it refuses a boost that moves no number anywhere, and in
    # between it returns nil and the flat first_setup 55 stands exactly as at 0.6.4.
    #
    # One flip is worth 55 on purpose -- the same as the flat bonus it replaces, which
    # is the only calibration point this scorer has for "a boost was worth the turn".
    value = 0
    changed = false
    transformed.each do |foe_slot, cell|
      base = matrix_cell(snapshot, own_slot, foe_slot)
      foe = matrix_entry(m["foe"], foe_slot)
      next if base.nil? || foe.nil?
      foe_hp = Model.number(foe["hp_pct"], 100.0)
      changed = true if matrix_hits(cell, own_hp, foe_hp) !=
                        matrix_hits(base, own_hp, foe_hp)
      before = cell_verdict(base, own_hp, foe_hp)
      after = cell_verdict(cell, own_hp, foe_hp)
      next if before.nil? || after.nil? || before == "W"
      if after == "W"
        value += SETUP_FLIP_TO_WIN
      elsif before == "L" && after == "S"
        value += SETUP_FLIP_TO_STALL
      end
    end
    if value <= 0
      return nil if changed
      return { "value" => 0, "reason" => "setup_no_flip" }
    end
    value = SETUP_FLIP_CAP if value > SETUP_FLIP_CAP
    { "value" => value, "reason" => "setup_flips" }
  end

  # The most any recovery move this battler carries restores, in hp_pct units and
  # UNCLIPPED by its current headroom: the question is what the heal is worth when it
  # is needed, not what it would restore this instant. 0 without one.
  def self.best_heal_pct(snapshot, actor)
    best = 0.0
    (actor["actions"] || []).each do |other|
      next if other["type"] != "move"
      tags = Effects.describe(other["move_id"], other["tags"])
      next if !(tags.include?("heal") || tags.include?("variable_heal"))
      amount = heal_amount(snapshot, tags)
      best = amount if amount > best
    end
    best
  end

  # A healer alternates healing and attacking, so to sustain, one heal has to cover
  # TWO of the foe's hits: Recover (50) holds against 20 a hit and bleeds out against
  # 30. Below that line a race counted in hits is as lost as it looks.
  def self.heal_cannot_outpace?(snapshot, actor)
    incoming = Model.number(actor["incoming_damage_pct"], 0.0)
    best_heal_pct(snapshot, actor) < incoming * 2
  end

  # Lost by a WHOLE hit, not on the tiebreak. The adapters export `faster` as a plain
  # "outspeeds" -- a speed tie reads as slower on both sides -- so two identical
  # Snorlax each see an equal-count race they "lose", and a rule that acted on that
  # would have both of them running from a mirror (the no_switch_full_hp_neutral card
  # caught exactly this). The 0.6.3 rules act only on the hit-count gap, which no
  # tiebreak can manufacture; the equal-count-and-slower case stays with the 0.6.0
  # flag, which is off.
  def self.race_lost_by_a_hit?(race)
    return false if race.nil? || race["winning"] != false
    return false if race["mine"].nil? || race["theirs"].nil?
    race["mine"] > race["theirs"]
  end

  # Lower is worse for the actor: losing < unknown < winning, and within losing the
  # one that kills it soonest.
  def self.race_rank(race)
    base = if race["winning"] == false then 0
           elsif race["winning"].nil? then 1
           else 2
           end
    theirs = race["theirs"].nil? ? RACE_MAX_HITS : race["theirs"]
    base * 100 + theirs
  end

  # A setup move is a STATUS move and the adapter gives it no scoring target, so
  # `target` is nil here in singles as well as doubles. Fall back to the foe the actor
  # is doing worst against, which is the one the setup has to survive. This cost a
  # portable probe run: the rule was silently inert on every card until the nil-target
  # case was found, and the unit test had been written with a target on the setup move.
  def self.setup_into_2hko?(snapshot, actor, target, config)
    race = target.nil? ? worst_race(snapshot, actor, config) :
                         damage_race(snapshot, actor, target, config)
    return false if race.nil?
    theirs = race["theirs"]
    return false if theirs.nil? || theirs > 2
    race["faster"] == false
  end

  def self.threatened_lethal?(actor)
    Model.truthy(actor["threatened_lethal"]) ||
      Model.number(actor["incoming_damage_pct"], 0) >= Model.number(actor["hp_pct"], 100)
  end

  def self.memory_count(snapshot, actor_index, key)
    memory = snapshot["memory"] || {}
    actor = memory[actor_index.to_s] || memory[actor_index] || {}
    Model.number(actor[key], 0).to_i
  end

  def self.memory_updates(actions)
    Effects.memory_updates(actions)
  end

  # ---------------------------------------------------------------------------
  # 0.5.0 tables.
  #
  # Reborn multiplies a move's damage-percent score by a per-move `miniscore`;
  # Portable adds. The quantity that multiplier scales is the move's DAMAGE score,
  # which here is the flat lethal bonus when the move kills and the capped damage term
  # when it does not — so scaling that same quantity keeps a x0.9 recoil charge worth
  # a tenth of what the move is actually being clicked for, instead of a tenth of a
  # number that stops mattering the moment the move is lethal.
  # ---------------------------------------------------------------------------
  def self.damage_value(lethal, damage)
    return 500.0 if lethal
    [Model.number(damage, 0.0), 100.0].min * 0.8
  end

  def self.multiplier_delta(m, lethal, damage)
    (m - 1.0) * damage_value(lethal, damage)
  end

  # Reborn's pbReduceWhenKills (:9887): once the damage score is at the cap, the
  # multiplier is square-rooted. x1.68 becomes x1.30 and x0.9 becomes x0.95 — bonuses
  # and costs soften alike, because by then the move is being clicked for the knockout
  # and not for what it does afterwards.
  def self.reduce_when_kills(m, lethal)
    return m if !lethal || m <= 0
    Math.sqrt(m)
  end

  # A secondary that fires 30% of the time is worth 30% of the effect. Reborn does NOT
  # do this — burncode/paracode/poisoncode/freezecode never read the move's addlEffect,
  # so Scald's 30% burn and Will-O-Wisp's 100% burn are priced identically (measured,
  # PORTABLE-AI-REBORN.md "0.5.0 Phase A", finding 6). This is a deliberate DEPARTURE.
  # A chance of exactly 0 means the effect is negated outright (Sheer Force, Shield
  # Dust, Covert Cloak) and the whole row is skipped by the caller.
  def self.chance_scaled(m, chance)
    return m if chance.nil?
    fraction = Model.number(chance, 100.0) / 100.0
    fraction = 1.0 if fraction > 1.0
    1.0 + (m - 1.0) * fraction
  end

  # Fact about the move's target, from the target view when the snapshot carries one
  # and from the action otherwise. Spread moves have no single target and read the
  # action's copy; unit tests may use either.
  def self.target_fact(action, target, key)
    return target[key] if target && !target[key].nil?
    action["target_" + key]
  end

  def self.actor_ability(actor)
    value = (actor || {})["ability"]
    value.nil? ? nil : value.to_s.upcase
  end

  def self.doubles?(snapshot)
    return true if (snapshot["format"] || "").to_s == "double"
    (snapshot["actors"] || []).length > 1
  end

  def self.doubles_outcomes_enabled?(snapshot, config)
    (config["doubles_outcomes"] || config["doubles_search"]) && config["coordination"] &&
      doubles?(snapshot) && (snapshot["actors"] || []).length == 2
  end

  # Sturdy and Focus Sash both mean "survives one hit from full HP". Mold Breaker turns
  # Sturdy off and a multi-hit move beats both, which is exactly Reborn's notOHKO?
  # (:17401-17409) minus the field- and form-specific rows.
  # Sturdy, or a Focus Sash, on a full-HP target: it survives one hit whatever that
  # hit was. Mold Breaker turns Sturdy off. Read by the multi-hit row, which is the
  # only place 0.5.0 prices it -- see the note in score_move.
  def self.one_hit_guard?(action, target)
    return false if !Model.truthy(target_fact(action, target, "full_hp"))
    item = (target_fact(action, target, "item") || "").to_s.upcase
    return true if item == "FOCUSSASH"
    ability = (target_fact(action, target, "ability") || "").to_s.upcase
    ability == "STURDY" && !Model.truthy(action["mold_breaker"])
  end

  # Abilities the TARGET has that make a status worth less, keyed by status kind.
  # Copied from Reborn's burncode (:5647), paracode (:5605) and poisoncode, which is
  # where the numbers come from; nothing here is invented.
  STATUS_DETERRENTS = {
    "burn" => { "GUTS" => 0.1, "FLAREBOOST" => 0.1, "QUICKFEET" => 0.3,
                "NATURALCURE" => 0.3, "MAGICGUARD" => 0.5, "SYNCHRONIZE" => 0.5,
                "MARVELSCALE" => 0.7, "SHEDSKIN" => 0.7, "WATERVEIL" => 0.0 },
    "poison" => { "POISONHEAL" => 0.1, "MAGICGUARD" => 0.1, "TOXICBOOST" => 0.2,
                  "GUTS" => 0.2, "QUICKFEET" => 0.3, "NATURALCURE" => 0.3,
                  "SYNCHRONIZE" => 0.5, "SHEDSKIN" => 0.7, "IMMUNITY" => 0.0 },
    "paralyze" => { "GUTS" => 0.2, "QUICKFEET" => 0.2, "NATURALCURE" => 0.3,
                    "MARVELSCALE" => 0.5, "SYNCHRONIZE" => 0.5, "SHEDSKIN" => 0.7,
                    "LIMBER" => 0.0 },
    "freeze" => { "NATURALCURE" => 0.3, "SYNCHRONIZE" => 0.5, "MARVELSCALE" => 0.8,
                  "MAGMAARMOR" => 0.0 },
    "sleep" => { "NATURALCURE" => 0.3, "SHEDSKIN" => 0.7, "EARLYBIRD" => 0.5,
                 "INSOMNIA" => 0.0, "VITALSPIRIT" => 0.0 }
  }

  STATUS_KINDS = %w[burn poison paralyze freeze sleep confuse]

  def self.status_kind(tags)
    STATUS_KINDS.each { |kind| return kind if tags.include?(kind) }
    nil
  end

  def self.status_deterrent(kind, ability)
    return 1.0 if kind.nil? || ability.nil?
    row = STATUS_DETERRENTS[kind]
    return 1.0 if !row
    value = row[ability.to_s.upcase]
    value.nil? ? 1.0 : value
  end

  # A pure status move aimed at a target that profits from the status. Reborn's own
  # multipliers, restated: at x0.3 or worse the move is a mistake rather than merely a
  # weak choice, so the flat +25 the status block just paid becomes -150.
  def self.status_deterrent_rule(action, tags, target, score, reasons)
    m = status_deterrent(status_kind(tags), target_fact(action, target, "ability"))
    return score if m >= 1.0
    if m <= 0.3
      score -= 175
      reasons << ["status_deterred", -175]
    else
      penalty = (1.0 - m) * 100.0
      score -= penalty
      reasons << ["status_deterred", -penalty]
    end
    score
  end

  # Item removal is worth what the item was worth. Reborn's knockcode (:8072) is a
  # short whitelist and returns a flat 1 for everything else -- including Focus Sash,
  # which a human would certainly rather remove. Copied as-is rather than extended:
  # the probe measured Knock Off at 75 / 58 / 39 against Leftovers / Sash / no item,
  # and the 58 is the ENGINE's own x1.5 damage boost against an item holder, which
  # reaches the core through expected_damage_pct without any rule's help.
  ITEM_REMOVAL_VALUE = {
    "LEFTOVERS" => 1.3, "BLACKSLUDGE" => 1.3,
    "LIFEORB" => 1.2, "CHOICESCARF" => 1.2, "CHOICEBAND" => 1.2,
    "CHOICESPECS" => 1.2, "ASSAULTVEST" => 1.2
  }

  CONTACT_PUNISHERS = %w[ROUGHSKIN IRONBARBS UNBREAKABLEBODY]

  ABSORB_ABILITIES = {
    "FLASHFIRE" => "FIRE", "WELLBAKEDBODY" => "FIRE",
    "WATERABSORB" => "WATER", "STORMDRAIN" => "WATER", "DRYSKIN" => "WATER",
    "SAPSIPPER" => "GRASS", "EARTHEATER" => "GROUND",
    "VOLTABSORB" => "ELECTRIC", "LIGHTNINGROD" => "ELECTRIC",
    "MOTORDRIVE" => "ELECTRIC", "JUSTIFIED" => "DARK"
  }

  REDIRECT_ABILITIES = { "LIGHTNINGROD" => "ELECTRIC", "STORMDRAIN" => "WATER" }

  # Every per-move side effect that scales the damage the move already does. One pass,
  # one named reason per row that fires, so a trace says which table entry moved the
  # score.
  # flat_kill (0.6.2, config["lethal_flat"]) drops the rows that only pay out if the
  # target is still standing afterwards -- the secondary status/flinch/stat-drop, and
  # the knocked item. The rows that survive it are the ones about whether the knockout
  # HAPPENS or what it costs the actor: multi_hit versus Sturdy/Sash, recoil, drain.
  def self.side_effect_rules(snapshot, actor, action, tags, target, damage,
                             lethal, faster, score, reasons, flat_kill = false)
    chance = action.key?("effect_chance") ? Model.number(action["effect_chance"], 100.0) : nil
    kind = action["effect_kind"]
    kind = Effects.kind_of(tags, "secondary") if kind.nil?
    kind = kind.nil? ? nil : kind.to_s
    target_ability = (target_fact(action, target, "ability") || "").to_s.upcase
    target_item = (target_fact(action, target, "item") || "").to_s.upcase

    # chance == 0 is the engine saying the secondary is negated outright (Sheer Force,
    # Shield Dust, Covert Cloak). No row fires, and the move is judged on damage alone.
    if kind && !(chance && chance <= 0) && !flat_kill
      m = secondary_multiplier(kind, action, actor, target, target_ability,
                               lethal, faster)
      if m != 1.0
        m = chance_scaled(m, chance)
        m = reduce_when_kills(m, lethal)
        delta = multiplier_delta(m, lethal, damage)
        if delta != 0
          # A status the target profits from is a reason NOT to click the move, and the
          # deterrent table is the same one the pure status moves use.
          score += delta
          reasons << ["secondary_" + kind, delta]
        end
      end
    end

    if Model.truthy(action["multi_hit"])
      m = 1.0
      m *= 1.3 if one_hit_guard?(action, target)
      if Model.truthy(action["contact"]) &&
         (CONTACT_PUNISHERS.include?(target_ability) || target_item == "ROCKYHELMET")
        m *= 0.7
      end
      if m != 1.0
        delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
        score += delta
        reasons << ["multi_hit", delta]
      end
    end

    recoil = Model.number(action["recoil_fraction"], 0.0)
    if recoil > 0 && actor_ability(actor) != "ROCKHEAD" && actor_ability(actor) != "MAGICGUARD"
      hp = Model.number(actor["hp_pct"], 100.0)
      m = 0.9
      m *= 0.8 if hp > 10 && hp < 40
      delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
      score += delta
      reasons << ["recoil_cost", delta]
    end

    drain = Model.number(action["drain_fraction"], 0.0)
    if drain > 0
      hp = Model.number(actor["hp_pct"], 100.0)
      missing = 100.0 - hp
      if missing <= 0 && faster == true
        # Nothing to restore and the drain resolves after the hit either way
        # (absorbcode's guard clause, :7742).
      else
        healed = [Model.number(damage, 0.0) * drain, missing].min
        m = 1.0 + 0.5 * healed / 100.0
        m = 2.0 - m if target_ability == "LIQUIDOOZE"
        delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
        if delta != 0
          score += delta
          reasons << ["drain_heal", delta]
        end
      end
    end

    if tags.include?("item_removal") && target_item != "" && !flat_kill
      m = ITEM_REMOVAL_VALUE[target_item] || 1.0
      if m != 1.0
        delta = multiplier_delta(reduce_when_kills(m, lethal), lethal, damage)
        score += delta
        reasons << ["knocks_item", delta]
      end
    end
    score
  end

  # The per-kind multiplier before chance and the kill reduction are applied.
  def self.secondary_multiplier(kind, action, actor, target, target_ability,
                                lethal, faster)
    deterrent = status_deterrent(kind, target_ability)
    case kind
    when "burn"
      m = 1.2
      m *= 1.4 if Model.truthy(target_fact(action, target, "physical_attacker"))
      m * deterrent
    when "poison", "freeze", "sleep"
      1.2 * deterrent
    when "paralyze"
      m = 1.0
      # Worth something only where halving the target's Speed changes who moves first.
      if faster == false
        target_speed = Model.number(target_fact(action, target, "speed"), 0.0)
        actor_speed = Model.number(actor["speed"], 0.0)
        m *= 1.2 if target_speed > 0 && actor_speed > 0 && target_speed / 2.0 < actor_speed
      end
      m *= 1.1 if Model.truthy(target_fact(action, target, "special_attacker"))
      m * deterrent
    when "flinch"
      # A flinch you never inflict is worth nothing: Reborn returns a flat 1 when the
      # user is slower or the move already kills (:5691).
      return 1.0 if faster != true || lethal
      return 1.0 if target_ability == "INNERFOCUS" || target_ability == "SHIELDDUST"
      return 1.0 if Model.truthy(target_fact(action, target, "substitute"))
      1.3
    when "drop"
      stat = (action["effect_stat"] || "").to_s.downcase
      return 1.0 if target_ability == "CLEARBODY" || target_ability == "WHITESMOKE" ||
                    target_ability == "FULLMETALBODY" || target_ability == "GOODASGOLD"
      case stat
      when "speed"
        faster == false ? 1.3 : 1.0
      when "spa"
        Model.truthy(target_fact(action, target, "special_attacker")) ? 1.2 : 1.0
      when "atk"
        Model.truthy(target_fact(action, target, "physical_attacker")) ? 1.2 : 1.0
      when "def", "spd"
        lethal ? 1.0 : 1.1
      else
        1.0
      end
    else
      1.0
    end
  end

  # Rules about what a move does to the SHAPE of the turn rather than to its damage:
  # speed control, first-turn-only moves, delayed damage. Flat score units, because
  # none of these three is a multiplier on damage the move does now.
  def self.turn_shape_rules(snapshot, actor, action, tags, faster, score, reasons)
    if tags.include?("first_turn_only")
      if Model.number(actor["turncount"], 0) == 0
        score += 115
        reasons << ["first_turn_hit", 115]
      else
        reasons << ["first_turn_over", HARD_REJECT]
        return HARD_REJECT
      end
    end

    if tags.include?("delayed_damage")
      if Model.truthy(action["effect_active"])
        score -= 200
        reasons << ["delayed_damage_pending", -200]
      elsif !threatened_lethal?(actor)
        score += 40
        reasons << ["delayed_damage", 40]
      end
    end

    if tags.include?("field_speed")
      move_id = action["move_id"].to_s.upcase
      active = move_id == "TRICKROOM" ? Model.truthy(snapshot["trick_room_active"]) :
                                        Model.truthy(snapshot["tailwind_active"])
      if active
        score -= 500
        reasons << ["speed_control_redundant", -500]
      elsif faster == false
        bonus = move_id == "TRICKROOM" ? 120 : 80
        # Trick Room is a whole-team investment: it is only worth a turn if the bench
        # is slow too, otherwise it hurts the mons that come in after this one.
        if move_id == "TRICKROOM"
          bench = Model.number(actor["slower_bench_count"], -1)
          reserves = Model.number(action["own_reserves"], 0)
          if bench >= 0 && reserves > 0 && bench * 2 < reserves
            bonus = 0
            reasons << ["trick_room_bench_is_fast", 0]
          end
        end
        bonus = (bonus * 1.3).round if bonus > 0 && doubles?(snapshot)
        if bonus > 0
          score += bonus
          reasons << ["speed_control_value", bonus]
        end
      end
    end
    score
  end

  # Doubles-only. Everything here is inert in singles except partner_heal, which is a
  # dead move there and says so.
  def self.format_rules(snapshot, actor, action, tags, score, reasons)
    if tags.include?("partner_heal")
      if !doubles?(snapshot)
        reasons << ["partner_heal_in_singles", HARD_REJECT]
        return HARD_REJECT
      end
      partner_hp = Model.number(actor["partner_hp_pct"], 100.0)
      if !Model.truthy(actor["partner_alive"])
        reasons << ["partner_heal_no_partner", HARD_REJECT]
        return HARD_REJECT
      elsif partner_hp >= 85
        score -= 500
        reasons << ["partner_heal_near_full", -500]
      elsif partner_hp <= 35
        bonus = 220 + (35 - partner_hp) * 3
        score += bonus
        reasons << ["partner_heal_low_hp", bonus]
      elsif partner_hp <= 60
        score += 90
        reasons << ["partner_heal_mid_hp", 90]
      end
    end
    return score if !doubles?(snapshot)

    move_type = (action["move_type"] || "").to_s.upcase
    return score if move_type == ""
    damage = Model.number(action["expected_damage_pct"], 0.0)

    if Model.truthy(action["spread"]) && Model.truthy(actor["partner_alive"])
      partner_ability = (actor["partner_ability"] || "").to_s.upcase
      if ABSORB_ABILITIES[partner_ability] == move_type
        # The partner does not merely survive the spread move, it profits from it:
        # Reborn doubles the score (:2031) and the probe measured Discharge at 280
        # against Thunderbolt's 112 on exactly that board.
        delta = multiplier_delta(2.0, false, damage)
        score += delta
        reasons << ["partner_absorbs", delta]
      elsif move_type == "GROUND" && Model.truthy(actor["partner_airborne"])
        reasons << ["partner_immune", 0]
      end
    end

    if !Model.truthy(action["spread"]) && !action["target"].nil?
      target = target_for(snapshot, action["target"])
      actor_ability_name = actor_ability(actor)
      steals = actor_ability_name != "STALWART" && actor_ability_name != "PROPELLERTAIL"
      if steals && target && REDIRECT_ABILITIES[(target["partner_ability"] || "").to_s.upcase] == move_type
        # The foe's partner takes the move instead, so it never reaches what it was
        # aimed at. Reborn already returns -1 for this (:3005) and the probe confirms;
        # the rule is here so the core does not depend on the adapter noticing.
        reasons << ["redirected_by_partner", HARD_REJECT]
        return HARD_REJECT
      end
      partner_ability = (actor["partner_ability"] || "").to_s.upcase
      if steals && REDIRECT_ABILITIES[partner_ability] == move_type
        # Reborn does NOT have this row: measured, it clicks Thunderbolt into a board
        # where its own Lightning Rod partner absorbs it (finding 2). Its own :3010
        # x0.3 is the symmetric case it does implement, so this is that number applied
        # to the direction the reference misses.
        delta = multiplier_delta(0.3, false, damage)
        score += delta
        reasons << ["own_partner_steals", delta]
      end
    end
    score
  end

  # Abilities on the TARGET that change what a damaging move is worth without changing
  # what it does.
  def self.damaging_ability_rules(action, target, lethal, score, reasons)
    return score if lethal
    ability = (target_fact(action, target, "ability") || "").to_s.upcase
    if ability == "JUSTIFIED" && (action["move_type"] || "").to_s.upcase == "DARK"
      # A Dark move that does not kill hands a Justified target a free Attack stage.
      score -= 40
      reasons << ["feeds_justified", -40]
    end
    score
  end

  def self.compare_candidates(a, b)
    by_score = b["score"] <=> a["score"]
    return by_score if by_score != 0
    action_key(a) <=> action_key(b)
  end

  def self.action_key(action)
    kind = action["type"] == "move" ? "0" : "1"
    [kind, action["slot"].to_i, action["target"].nil? ? -1 : action["target"].to_i,
     action["move_id"].to_s].join(":")
  end

  def self.pair_key(pair)
    pair.map { |action| action_key(action) }.join("|")
  end
end
# ===== END portable_ai/core.rb =====

# ===== BEGIN portable_ai/search.rb =====
# 0.7.0. A SECOND PLANNER: one-ply search over the joint action grid.
#
# Requires model.rb, effects.rb and matrix.rb. It does NOT require core.rb and must
# not come to: core.rb scores ACTIONS by summing 107 hand-tuned reason terms, and this
# scores the STATE an action leads to. Two answers to two different questions. Mixing
# them would give a number that is neither, so they share the board readers (matrix.rb)
# and nothing else. The adapter picks one per run; the rule planner is the default and
# this is off unless `search_planner` is set.
#
# PROVENANCE. The shape is poke-engine's legacy `expectiminimax_search` + `pick_safest`
# (https://github.com/pmariglia/poke-engine, src/search.rs, GPL-3.0), the path the
# older Foul Play "safest" bot ran; Foul Play today runs the engine's MCTS instead.
# Three ideas are borrowed, no code is:
#   * `pick_safest` -- pick by maximin over the joint own x foe payoff grid, not by
#     expected value against a guessed foe move.
#   * a state-value leaf -- the board after the turn is worth what stands on it. The
#     original's `evaluate` is a PARTY-WIDE sum: every live body is worth its HP plus a
#     flat alive bonus, and there is no matchup term at all. 0.7.1 made this leaf that
#     shape; the first version had the weighting inside out (see THE VALUE SCALE).
#   * chance as branches -- a speed tie and a miss are both two boards at their
#     probabilities, never one board at an averaged damage. The leaf is a step at
#     0 HP, so the value of the expected damage is not the expected value.
# Damage-roll grouping by faint threshold was NOT borrowed through 0.7.8 on the
# belief that a cell carried an expected roll; it carries the MAXIMUM (pbRoughDamage
# has no random factor), and 0.7.9 borrows the original's branching -- see
# roll_outcomes. Still not borrowed: reversible instructions (unnecessary -- the snapshot is a
# plain Hash and Model.copy_hash is the whole undo), and Smogon-corpus set prediction
# (that is the predictor backlog item, and it feeds the same snapshot fields).

module PortableAI
  module Search
    # THE VALUE SCALE, the original's proportions in HP points:
    #   1 point   one percent of a body's HP, every live body on both sides. HP is the
    #             currency, as in poke-engine's evaluate (POKEMON_HP = 100 x fraction).
    #   30        a body being alive at all (POKEMON_ALIVE). So a kill is worth the HP
    #             it removes plus 30, and losing a 5% body costs 35, not the game.
    #   +/-1000   the battle is over (the original's 100 x depth x battle_is_over).
    # NO VERDICT TERM (0.7.4). Through 0.7.3 the leaf added +/-25 for the pair left
    # standing (matrix.rb's W / L), a term the original does not have, kept "small
    # on purpose" after 0.7.0 had it at the top of the scale and fled to every
    # W-verdict bench body. Once the foe-switch column priced each move on its own
    # (out_moves), an attack the bench could wall read as a bad row, and the verdict
    # was what made the pre-emptive switch the better one: 35/60 with the term, 40/60
    # without, on the same build. The pair's matchup is already in the sum -- as the
    # HP each side stands to lose at the next ply -- which is where the original
    # keeps it.
    BODY_ALIVE = 30.0
    BATTLE_OVER = 1000.0
    # A win found a ply earlier is worth more (the original's 100 x depth), and the
    # sentinels the maximin loops start from -- no Float::INFINITY on RGSS's Ruby.
    DEPTH_BONUS = 100.0
    DEFAULT_DEPTH = 2
    HUGE = 1.0e18

    # THE REST OF THE ORIGINAL'S evaluate, at its numbers (poke-engine
    # src/genx/evaluate.rs), for what a turn can change besides HP. 0.7.2: before this
    # a setup, heal, Protect, status or hazard move projected as a wasted turn, so the
    # planner could never click one on purpose.
    STAGE_VALUE = { "atk" => 30.0, "spa" => 30.0, "speed" => 30.0,
                    "def" => 15.0, "spd" => 15.0 }
    STAGE_MULTIPLIER = [0.0, 1.0, 2.0, 2.5, 3.0, 3.15, 3.3]
    # A foe's stage, which the snapshot reports only as a count of positive ones.
    FOE_STAGE_VALUE = 25.0
    STATUS_VALUE = { "toxic" => 30.0, "poison" => 10.0, "burn" => 25.0,
                     "paralyze" => 25.0, "sleep" => 25.0, "freeze" => 40.0,
                     "confuse" => 20.0, "drain" => 30.0 }
    SUBSTITUTE_VALUE = 75.0
    SUBSTITUTE_COST = 25.0
    HAZARD_VALUE = { "STEALTHROCK" => 10.0, "SPIKES" => 7.0, "TOXICSPIKES" => 7.0,
                     "STICKYWEB" => 25.0 }

    # 0.7.9. THE ROLL AND THE TURN'S OTHER CHANCES. Every damage number this planner
    # is handed is pbRoughDamage, a maximum (no random factor, no crit: 085 "Random
    # variance - n/a"); the engine rolls 85..100% of it and crits one time in sixteen
    # for x1.5 (v16). See roll_outcomes. The act chances are the engine's for
    # paralysis and thaw; sleep is a third, the mean over a counter the snapshot does
    # not carry.
    ROLL_MIN = 0.85
    ROLL_AVERAGE = 0.925
    CRIT_RATE = 1.0 / 16.0
    CRIT_MULT = 1.5
    ACT_CHANCE = { "paralyze" => 0.75, "sleep" => 1.0 / 3.0, "freeze" => 0.2 }
    # PBStatuses, as the adapter exports a body's status; the names are what the
    # STATUS_VALUE table above keys on. "toxic" is this planner's own, for a Toxic it
    # landed itself -- the engine reports Toxic as POISON plus a counter it does not
    # export, so a body that arrived already badly poisoned ticks as poisoned.
    STATUS_CODES = { 1 => "sleep", 2 => "poison", 3 => "burn", 4 => "paralyze", 5 => "freeze" }
    STATUS_NAMES = { "paralysis" => "paralyze", "paralyzed" => "paralyze", "frozen" => "freeze",
                     "asleep" => "sleep", "poisoned" => "poison", "burned" => "burn",
                     "badly_poisoned" => "toxic" }
    # THE END OF TURN, in percent of max HP: an eighth for burn, poison, Leech Seed
    # and Black Sludge on the wrong body; a sixteenth for Leftovers, sand, hail and
    # each rung of the Toxic ladder. The engine's own fractions (080:2212-2231).
    RESIDUAL_EIGHTH = 12.5
    RESIDUAL_SIXTEENTH = 6.25
    SAND_PROOF_TYPES = %w[ROCK GROUND STEEL]
    SAND_PROOF_ABILITIES = %w[SANDVEIL SANDRUSH SANDFORCE OVERCOAT]
    HAIL_PROOF_ABILITIES = %w[ICEBODY SNOWCLOAK SLUSHRUSH OVERCOAT]

    # nil means "this planner declines" -- the adapter falls through to the rule planner
    # and the run is unchanged. Declining is the normal path on anything but a singles
    # battle with a matrix, so a build with the key on is still the rule AI everywhere
    # this cannot see the board.
    def self.plan(snapshot, config, rng)
      Model.validate(snapshot)
      # The defaults under the overrides, as the rule engine reads them. Through the
      # first 0.7.5 build this read the overrides alone, so a default that was not
      # spelled out in the harness (search_foe_mix 0.5) was 0 in play and the
      # shipped arm reproduced 0.7.4 to the decision.
      config = Model.config(config)
      return nil if (snapshot["format"] || "single") != "single"
      actors = snapshot["actors"]
      targets = snapshot["targets"] || []
      return nil if actors.length != 1 || targets.length != 1
      return nil if PortableAI.matrix(snapshot).nil?

      board = opening_board(snapshot, config)
      return nil if board.nil?
      own_actions = actors[0]["actions"]
      return nil if !own_actions.is_a?(Array) || own_actions.empty?
      foe_actions = foe_options(snapshot, board)
      return nil if foe_actions.empty?

      # 0.7.6. THE TREE, or the grid. Everything above is shared -- the same guards,
      # the same opening board, the same option lists -- and everything below is the
      # maximin. With the key off this line is the only trace of MCTS in a run.
      return mcts_plan(snapshot, config, board, own_actions, foe_actions) if config["search_mcts"]

      depth = depth_of(config)
      # THE OPPONENT MODEL LIVES AT THE ROOT. The mix and the weights are applied to
      # the root rows only; every ply below is the original's maximin (safest). A
      # prediction exists only for the board in front of us, and blending the deeper
      # grids with a uniform expectation instead was measured as the worse half of
      # every arm (stock model at 0.5: 42 with it, 46 without; the oracle 34 / 46).
      mix = mix_of(config)
      weights = column_weights(foe_actions, board["foe_reply"],
                               config["search_foe_prior"] ? foe_prior(foe_actions) : nil)
      ranked = own_actions.map do |action|
        row = foe_actions.map { |foe| payoff(snapshot, board, action, foe, depth, own_actions) }
        scored = Model.copy_hash(action)
        # Maximin: the action is worth the WORST the foe can do to it. pick_safest.
        # Not an average -- an average rewards a line that is excellent against three
        # foe options and loses the game against the fourth. That is the original,
        # and at search_foe_mix 0 it is all there is. Above 0 the worst reply is
        # blended with the EXPECTED one (row_value): 0.7.4 measured pure maximin as
        # the limit -- an attack's worst case is the bench body that walls it, and
        # the measured foe does not make that reply.
        scored["score"] = row_value(row, weights, mix)
        # The mean breaks a tie in the minimum, and ties are common by construction:
        # every own move projects the SAME number against a switching foe (own_damage),
        # so whenever a foe switch is the worst case the minima collapse. Without this
        # the fallback is the action key, and the planner would click move slot 0 in
        # every such position. Lexicographic, not a weighted sum, so it can never
        # reorder two genuinely different minima however close they are.
        scored["search_mean"] = row.inject(0.0) { |a, b| a + b } / row.length
        # The row itself, in foe_actions order, so a traced run can be read rather than
        # guessed at. The first version had to be debugged from four identical scores.
        scored["search_row"] = row
        # Diagnostic: the on-field cell the leaf and the ordering are read from. A move
        # scored as a certain death against a full-HP actor is either a real cell or a
        # misread one, and nothing else in the trace can tell those apart.
        on_field = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
        scored["search_cell"] = on_field
        scored["reasons"] = [["search_worst_case", row.min],
                             ["search_mean", scored["search_mean"]],
                             ["search_best_case", row.max],
                             ["search_foe_options", foe_actions.length],
                             ["search_expected", expected_value(row, weights)]]
        scored
      end
      ranked.sort! { |a, b| compare(a, b) }

      {
        "actions" => [ranked[0]],
        # The same record the rule planner leaves (Effects.memory_updates), because the
        # projection reads it back: a Protect clicked twice running fails, and only
        # the memory counter can say the last click was one.
        "memory_updates" => Effects.memory_updates([ranked[0]]),
        "diagnostics" => {
          "version" => VERSION,
          "planner" => "search",
          "depth" => depth,
          "foe_mix" => mix,
          "foe_weights" => weights,
          "foe_reply" => board["foe_reply"],
          "format" => "single",
          "joint_adjustment" => 0,
          "foe_options" => foe_actions.map { |f| foe_label(f) },
          "board" => board,
          "candidate_counts" => [ranked.length],
          "rankings" => [ranked]
        }
      }
    end

    # Plies to look ahead: the config key, floored at one. A bare Hash (the tests, an
    # adapter that never merged defaults) gets DEFAULT_DEPTH.
    # The opponent model's one number, clamped to [0, 1]. See DEFAULT_CONFIG.
    def self.mix_of(config)
      mix = Model.number((config || {})["search_foe_mix"], 0.0)
      mix = 0.0 if mix < 0.0
      mix = 1.0 if mix > 1.0
      mix
    end

    # What the adapter predicts the foe on the field will do this turn, if it
    # predicts anything: the chance it switches and, when known, the slot it
    # switches to. From the actor's predicted_foe entry for the target's seat --
    # the oracle's (type switch, chance 1) or a model's (type move, its own chance).
    # nil when nothing was exported, which is every run with both keys off.
    def self.predicted_reply(snapshot)
      actor = snapshot["actors"][0]
      target = snapshot["targets"][0]
      table = actor["predicted_foe"]
      return nil if !table.is_a?(Hash) || target["index"].nil?
      entry = table[target["index"].to_s]
      return nil if !entry.is_a?(Hash)
      if entry["type"].to_s == "switch"
        { "switch_chance" => 1.0, "switch_slot" => entry["slot"] }
      else
        { "switch_chance" => Model.number(entry["switch_chance"], 0.0),
          "switch_slot" => entry["switch_slot"] }
      end
    end

    # One weight per foe column, summing to one. Uniform without a prediction --
    # which, measured, is a bad model of this foe (it says "switches five turns in
    # six"): 29/60 at the root against 46 with the stock model's weights. With
    # one: the switch chance goes to the predicted slot's column, or is shared by
    # every switch column when the slot is unknown, and the rest is the stay column.
    # A column list with no stay (a replacement ply) is uniform whatever was said.
    def self.column_weights(foe_actions, reply, prior = nil)
      n = foe_actions.length
      return [] if n == 0
      uniform = foe_actions.map { 1.0 / n }
      if reply.nil?
        # No opponent model at all. The prior still has something to say -- it is a
        # statement about the foe's MOVES, not about whether it stays -- so the stay
        # columns share exactly the mass uniform gave them, redistributed by damage.
        return uniform if prior.nil?
        stays = []
        foe_actions.each_with_index { |f, i| stays << i if f["kind"] == "stay" }
        return uniform if stays.length < 2
        out = uniform.dup
        spread_stays(out, foe_actions, stays, stays.length.to_f / n, prior)
        return out
      end
      # 0.7.7: there are as many stay columns as the foe has moves, so the mass that
      # is not a switch is shared over all of them. The prediction says whether it
      # stays, never which move it picks -- concentrating this on a predicted move is
      # the next arm, and it is what `stock_move` was exported for.
      stays = []
      switches = []
      foe_actions.each_with_index do |f, i|
        stays << i if f["kind"] == "stay"
        switches << i if f["kind"] == "switch"
      end
      return uniform if stays.empty? || switches.empty?
      chance = Model.number(reply["switch_chance"], 0.0)
      chance = 0.0 if chance < 0.0
      chance = 1.0 if chance > 1.0
      out = foe_actions.map { 0.0 }
      spread_stays(out, foe_actions, stays, 1.0 - chance, prior)
      slot = reply["switch_slot"]
      named = slot.nil? ? nil : switches.find { |i| foe_actions[i]["slot"] == slot }
      if named
        out[named] = chance
      else
        switches.each { |i| out[i] = chance / switches.length }
      end
      out
    end


    # The stay columns' share of `mass`, split by the prior when there is one and
    # evenly when there is not. The prior only ever moves mass BETWEEN STAY COLUMNS:
    # it says which move the foe picks, never whether it stays, so the switch/stay
    # split its caller computed survives untouched.
    def self.spread_stays(out, foe_actions, stays, mass, prior)
      share = nil
      if !prior.nil?
        total = 0.0
        stays.each { |i| total += prior[i] }
        share = total if total > 0.0
      end
      if share.nil?
        stays.each { |i| out[i] = mass / stays.length }
      else
        stays.each { |i| out[i] = mass * prior[i] / share }
      end
    end

    # HOW HARD EACH OF THE FOE'S MOVES HITS, normalised: the free prior over the foe's
    # columns, read straight out of the cell the tree already built. Measured on the
    # 0.7.7 5000-iteration arm (925 decisions): the cell's max-damage move IS the move
    # the foe registers 51.7% of the time, against 43.1% for the tree's own most-visited
    # foe option -- so the tree's opponent model is worse than the one already sitting
    # in its input, and this is what the two `search_foe_prior` arms redistribute by.
    #
    # nil when nothing is priced (no in_moves, or every column zero), which leaves both
    # consumers exactly as they were. Switch columns get 0: the prior is about moves,
    # and its consumers never move mass out of the stay group.
    def self.foe_prior(foe_actions)
      out = foe_actions.map { 0.0 }
      total = 0.0
      foe_actions.each_with_index do |action, i|
        next if action["kind"] != "stay"
        pct = Model.number(action["pct"], 0.0)
        pct = 0.0 if pct < 0.0
        out[i] = pct
        total += pct
      end
      return nil if total <= 0.0
      out.map { |v| v / total }
    end

    def self.expected_value(row, weights)
      total = 0.0
      row.each_with_index { |v, i| total += v * Model.number(weights[i], 0.0) }
      total
    end

    # Worst reply blended with the expected one by the mix: 0 is the min, 1 the
    # expectation.
    def self.row_value(row, weights, mix)
      return row.min if mix <= 0.0
      row.min * (1.0 - mix) + expected_value(row, weights) * mix
    end

    def self.depth_of(config)
      depth = Model.number((config || {})["search_depth"], DEFAULT_DEPTH).to_i
      depth < 1 ? 1 : depth
    end

    # Worst case first, then the mean, then a stable key -- so a tie never depends on
    # the order the adapter happened to export actions in.
    def self.compare(a, b)
      by_score = b["score"] <=> a["score"]
      return by_score if by_score != 0
      by_mean = b["search_mean"] <=> a["search_mean"]
      return by_mean if by_mean != 0
      key(a) <=> key(b)
    end

    def self.key(candidate)
      [candidate["type"].to_s, candidate["slot"].to_i,
       candidate["move_id"].to_s, candidate["target"].to_i]
    end

    # ------------------------------------------------------------------------------
    # The board. Four numbers: which body stands on each side and the HP it stands on.
    # Every other body's HP is read from the side tables, which a turn does not touch.

    def self.opening_board(snapshot, config = {})
      m = PortableAI.matrix(snapshot)
      own_slot = PortableAI.matrix_slot(m["own"], snapshot["actors"][0]["index"])
      foe_slot = PortableAI.matrix_slot(m["foe"], snapshot["targets"][0]["index"])
      return nil if own_slot.nil? || foe_slot.nil?
      own = PortableAI.matrix_entry(m["own"], own_slot)
      foe = PortableAI.matrix_entry(m["foe"], foe_slot)
      return nil if own.nil? || foe.nil?
      actor = snapshot["actors"][0]
      target = snapshot["targets"][0]
      first = (actor["actions"] || [])[0] || {}
      own_hp = Model.number(own["hp_pct"], 100.0)
      foe_hp = Model.number(foe["hp_pct"], 100.0)
      { "own_slot" => own_slot, "foe_slot" => foe_slot,
        "own_hp" => own_hp,
        "foe_hp" => foe_hp,
        # EVERY BODY'S HP AS THIS SEARCH HAS CHANGED IT, by slot; a slot not here still
        # stands on its side-table number. own_hp / foe_hp are the on-field entries of
        # these maps, kept beside them for the readers. Without the maps a body that
        # took a hit and left the field came back at full table HP, so at depth two
        # every hit we landed was erased whenever the foe's worst case was a switch --
        # which it usually is -- and only stages, hazards and status survived a ply.
        # The planner clicked Rock Polish and Stealth Rock everywhere and won 15 of
        # 60. The 0.7.0 bug where a switch-in inherited the OUTGOING body's HP was
        # this one's mirror image.
        "own_hps" => { own_slot => own_hp },
        "foe_hps" => { foe_slot => foe_hp },
        # THE NARROW, THICK VIEW OF THE PAIR ON THE FIELD, kept beside the wide one.
        # A cell deliberately carries no Choice lock, no Intimidate, no hazards and no
        # priority (see matrix.rb) -- it answers "does this body beat that body", not
        # "what happens this turn". Using it as a per-turn damage number was this
        # planner's second bug and a worse one than the first: a Choice-Scarf Galvantula
        # locked into a 24% move read as a 174% Bug Buzz, so a healthy Sceptile scored
        # every move as a certain death and fled. These two fields are what every rule
        # in core.rb reads for the same question, and they are Choice-aware.
        "live_incoming" => (actor["incoming_damage_pct"].nil? ? nil :
                            Model.number(actor["incoming_damage_pct"], 0.0)),
        "live_faster" => actor["faster"],
        # Which pair those two numbers describe. A projected board where either body
        # has changed is not that pair any more, whatever slot it happens to sit on.
        "live_pair" => [own_slot, foe_slot],
        # Root facts a deeper ply needs: whether the actor may leave (only meaningful
        # while it is the body on the field) and whether the foe may.
        "own_trapped" => Model.truthy(actor["trapped"]),
        "foe_trapped" => Model.truthy(target["trapped"]),
        # What the turn can change besides HP, each in the original's evaluate terms.
        # Stages belong to the body on the field and are lost with it (own_stages
        # empties on a switch; foe_boost zeroes on theirs). The rest are DELTAS this
        # turn makes -- a status landed, a hazard laid, a Substitute standing -- so a
        # body's existing status, which every row carries alike, is not re-counted.
        "own_stages" => decode_stages(actor["stages"]),
        # AND WHICH OF THOSE THE ENGINE HAS ALREADY PRICED IN. Every number the root
        # exports -- expected_damage_pct, the live pair's cell, the side table's Speed
        # -- was rolled through the actor's real stages. Scaling them by own_stages
        # again counted a +2 body as +4 (0.7.1-0.7.3). Only the stages this search
        # PROJECTS on top scale a number; the leaf's boost term still reads the total,
        # because a switch really does throw the whole stack away.
        "stage_base" => decode_stages(actor["stages"]),
        "foe_boost" => Model.number(target["positive_stages"], 0.0) * FOE_STAGE_VALUE,
        "foe_status_points" => 0.0,
        "own_status_points" => 0.0,
        "foe_hazard_points" => 0.0,
        "substitute" => Model.truthy(actor["substitute"]),
        "protected" => false,
        "protect_repeats" => memory_count(snapshot, actor["index"], "protect"),
        # The opponent model's input: what the adapter predicts the foe on the field
        # will do. This turn's only -- project drops it, and plan reads it once.
        "foe_reply" => predicted_reply(snapshot),
        # 0.7.9. The foe's side of the same terms, so act_foe has somewhere to put
        # what its move does; the statuses both bodies stand under (they tick, and
        # they decide whether the body acts); what the foe already laid on our side.
        "foe_stages" => {},
        "own_status" => (status_key(own) || status_key(actor)),
        "foe_status" => (status_key(foe) || status_key(target)),
        "own_seeded" => false, "foe_seeded" => false,
        "own_toxic" => 0, "foe_toxic" => 0,
        "foe_substitute" => (Model.truthy(first["target_substitute"]) ||
                             Model.truthy(target["substitute"])),
        "foe_protected" => false,
        "foe_protect_repeats" => 0,
        "own_hazard_points" => 0.0,
        "own_hazard_layers" => Model.number(first["own_hazard_layers"], 0.0),
        "foe_laid" => {} }
    end

    # The adapter exports stages as the engine's array (PBStats order: attack 1,
    # defence 2, speed 3, special attack 4, special defence 5) or, on a thinner
    # adapter, as a Hash in the core's own short names. Either way out come the names.
    STAGE_INDEX = { "atk" => 1, "def" => 2, "speed" => 3, "spa" => 4, "spd" => 5 }

    def self.decode_stages(raw)
      out = {}
      if raw.is_a?(Array)
        STAGE_INDEX.each do |name, index|
          value = Model.number(raw[index], 0.0).to_i
          out[name] = value if value != 0
        end
      elsif raw.is_a?(Hash)
        STAGE_INDEX.each_key do |name|
          value = Model.number(raw[name], 0.0).to_i
          out[name] = value if value != 0
        end
      end
      out
    end

    def self.memory_count(snapshot, actor_index, key)
      memory = snapshot["memory"] || {}
      actor = memory[actor_index.to_s] || memory[actor_index] || {}
      Model.number(actor[key], 0).to_i
    end

    # WHAT THE FOE CAN DO. One column per move it owns, plus one per body on its bench.
    #
    # 0.7.7. THROUGH 0.7.6 THIS WAS ONE `stay` COLUMN priced at the foe's BEST hit --
    # "it attacks, at worst" -- and that was the whole model of the opponent. It made
    # 0.7.6's tree a fair-weather test of MCTS: a search whose entire thesis is that
    # the foe's line should be shaped by the foe's own payoff was handed an opponent
    # with one way to act, so per-side UCB had nothing to discover (41/60 at 1000
    # iterations, 43 at 5000, against the maximin's 46). The cell now carries the
    # foe's own per-move rolls (`in_moves`, matrix version 3 -- the mirror of the
    # `out_moves` 0.7.4 added for us, and the same rolls the adapter was already
    # making to find `in`), so the foe picks a MOVE here, not just "attack".
    #
    # 0.7.9. AND EVERY MOVE, NOT ONLY THE DAMAGING ONES. Version 3 listed the moves
    # `pbIsDamaging?` said yes to, so the tree's foe could attack or switch and do
    # nothing else -- never set up, heal, lay a hazard, Protect or land a status --
    # while our own root row was priced for all of those (0.7.2). The original hands
    # both sides the whole move list. A status column carries pct 0 and its effect
    # triple; `act_foe` plays it the way `act_own` plays ours.
    #
    # A cell without the list -- an older adapter, a pair the matrix never rolled --
    # is one `stay` column at the best hit, which is 0.7.6 exactly. That fallback is
    # also every Reborn run, which exports no matrix at all.
    #
    # NOTE FOR MAXIMIN: its worst case over these columns is still the biggest hit, so
    # `search_foe_mix` 0 is very nearly unchanged by this. What moves is the EXPECTED
    # reply (more columns to spread over, see column_weights) and the tree.
    #
    # A trapped foe has no switch column. The original's option generator respects
    # trapping; without this a trapper's whole advantage was invisible here, and a foe
    # switch was the worst case on 41% of turns.
    #
    # After a faint the ply is a replacement: the side that lost a body picks a
    # replacement and the other side does nothing (the original's force_switch
    # options, MoveChoice::None opposite). Both down, both pick.
    def self.foe_options(snapshot, board)
      m = PortableAI.matrix(snapshot)
      bench = PortableAI.matrix_live_slots(m["foe"]).reject { |slot| slot == board["foe_slot"] }
      return bench.map { |slot| { "kind" => "switch", "slot" => slot } } if board["foe_hp"] <= 0
      return [{ "kind" => "none" }] if board["own_hp"] <= 0
      out = foe_moves(snapshot, board)
      return out if board["foe_trapped"] && board["foe_slot"] == board["live_pair"][1]
      bench.each { |slot| out << { "kind" => "switch", "slot" => slot } }
      out
    end

    # The foe's move columns for the pair standing on the board. Sorted by move id --
    # a Ruby 1.8 Hash has no order of its own, and a column list that varied between
    # two runs of the same position would make every paired arm unrepeatable.
    def self.foe_moves(snapshot, board)
      cell = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
      moves = cell && cell["in_moves"]
      return [{ "kind" => "stay" }] if !moves.is_a?(Hash) || moves.empty?
      out = []
      moves.keys.sort.each do |move_id|
        entry = moves[move_id]
        next if !entry.is_a?(Hash)
        out << { "kind" => "stay", "move_id" => move_id,
                 "pct" => Model.number(entry["pct"], 0.0), "cat" => entry["cat"],
                 "damaging" => (entry.key?("damaging") ? Model.truthy(entry["damaging"]) :
                                Model.number(entry["pct"], 0.0) > 0.0),
                 "acc" => entry["acc"], "priority" => Model.number(entry["priority"], 0.0),
                 "effect" => (entry["effect"].is_a?(Array) ? entry["effect"] : [nil, nil, nil]) }
      end
      out.empty? ? [{ "kind" => "stay" }] : out
    end

    # The cell's own roll of one of the FOE's moves; the mirror of cell_move.
    def self.cell_in_move(cell, move_id)
      return nil if cell.nil? || move_id.nil?
      moves = cell["in_moves"]
      return nil if !moves.is_a?(Hash)
      entry = moves[move_id.to_s.upcase]
      entry.is_a?(Hash) ? entry : nil
    end

    # How a foe column reads in a trace: the move it names, or the body it brings in.
    def self.foe_label(option)
      return "switch:#{option['slot']}" if option["kind"] == "switch"
      return "none" if option["kind"] == "none"
      option["move_id"].nil? ? "stay" : "stay:#{option['move_id']}"
    end

    # OUR options from a projected board, for the plies below the root. The root's
    # exported actions are the truth about THIS turn (legality, PP, the Choice lock,
    # every per-move number against the foe on the field) and they stay the truth as
    # long as the same two bodies stand there. Any other pair has the matrix: 0.7.9,
    # every move the cell lists for the body (out_moves, version 4), built into the
    # same action shape the root exports -- so a switch-in can set up, Protect or
    # land a status below the root, as the original's option generator lets it.
    # Through 0.7.8 it had ONE attack worth the cell, and a switch read as a body
    # that could only ever hit. A cell without the list still gets that one attack.
    def self.own_options(snapshot, board, root_actions)
      m = PortableAI.matrix(snapshot)
      bench = PortableAI.matrix_live_slots(m["own"]).reject { |slot| slot == board["own_slot"] }
      if board["own_hp"] <= 0
        return bench.map { |slot| bench_switch(m, slot, board, root_actions, true) }
      end
      return [{ "type" => "none" }] if board["foe_hp"] <= 0
      out = []
      if live_pair?(board)
        root_actions.each { |a| out << a if a["type"] == "move" }
      else
        cell = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
        out = cell_actions(cell)
      end
      trapped = board["own_trapped"] && board["own_slot"] == board["live_pair"][0]
      bench.each { |slot| out << bench_switch(m, slot, board, root_actions, false) } if !trapped
      out
    end

    # A cell's out_moves as root-shaped actions, sorted by id for the same reason
    # foe_moves sorts. No list: one attack worth the cell's best number.
    def self.cell_actions(cell)
      moves = cell && cell["out_moves"]
      if !moves.is_a?(Hash) || moves.empty?
        return [{ "type" => "move", "move_id" => "MATRIX_ATTACK", "slot" => 0,
                  "damaging" => true, "accuracy" => 100,
                  "expected_damage_pct" => (cell.nil? ? 0.0 : Model.number(cell["out"], 0.0)) }]
      end
      out = []
      moves.keys.sort.each do |move_id|
        entry = moves[move_id]
        next if !entry.is_a?(Hash)
        effect = entry["effect"].is_a?(Array) ? entry["effect"] : [nil, nil, nil]
        pct = Model.number(entry["pct"], 0.0)
        out << { "type" => "move", "move_id" => move_id, "slot" => 0,
                 "damaging" => (entry.key?("damaging") ? Model.truthy(entry["damaging"]) : pct > 0.0),
                 "accuracy" => (entry["acc"].nil? ? 100 : Model.number(entry["acc"], 100.0)),
                 "priority" => Model.number(entry["priority"], 0.0),
                 "expected_damage_pct" => pct,
                 "effect_kind" => effect[0], "effect_stat" => effect[1],
                 "effect_chance" => effect[2], "tags" => [] }
      end
      out
    end

    # A switch to a bench body, priced from the side table -- or, when the root
    # exported this very switch against this very foe, from the root's own numbers.
    # 0.7.9: the hazard damage a switch-in pays does not depend on who it faces, so a
    # switch below the root reads it from the root's export of the same slot, else
    # from the side table -- through 0.7.8 it was 0 there, which made a chain of
    # switches under Stealth Rock free.
    def self.bench_switch(m, slot, board, root_actions, forced)
      exported = nil
      root_actions.each do |a|
        next if a["type"] != "switch" || a["slot"] != slot
        exported = a
        break
      end
      if !exported.nil? && board["foe_slot"] == board["live_pair"][1]
        return exported if !forced
        copy = Model.copy_hash(exported)
        copy["forced"] = true
        return copy
      end
      entry = PortableAI.matrix_entry(m["own"], slot)
      hazard = exported.nil? ? Model.number(entry && entry["entry_damage_pct"], 0.0) :
                               Model.number(exported["entry_damage_pct"], 0.0)
      { "type" => "switch", "slot" => slot, "forced" => forced,
        "candidate_hp_pct" => Model.number(entry && entry["hp_pct"], 100.0),
        "entry_damage_pct" => hazard }
      # (project reads the search's own HP map for this slot first, so a body this
      # search already damaged comes back at that HP, not the table's.)
    end

    def self.live_pair?(board)
      board["own_slot"] == board["live_pair"][0] && board["foe_slot"] == board["live_pair"][1]
    end

    # The value of one cell of the grid: the leaf averaged over every chance branch the
    # turn has (`outcomes`). Through 0.7.8 the branches were the speed order and OUR
    # accuracy, and every damage number was taken as it came. 0.7.9 branches what the
    # original branches: both sides' accuracy, whether a paralysed, asleep or frozen
    # body acts at all, and THE DAMAGE ROLL -- see roll_outcomes for why that one
    # matters more than the rest put together.
    def self.payoff(snapshot, board, own_action, foe_action, depth = 1, root_actions = [])
      total = 0.0
      outcomes(snapshot, board, own_action, foe_action, true).each do |spec|
        after = project(snapshot, board, own_action, foe_action, spec[1], true, spec[2])
        total += spec[0] * value_of(snapshot, after, depth - 1, root_actions)
      end
      total
    end

    # What a board is worth with `depth` plies still to look: the leaf when none are
    # left or the battle is over, otherwise the safest reply grid from it -- the
    # original's expectiminimax, which scores a sub-game by pick_safest.
    def self.value_of(snapshot, board, depth, root_actions)
      return leaf(snapshot, board) if depth <= 0
      over = battle_over(snapshot, board)
      return over + (over > 0 ? DEPTH_BONUS : -DEPTH_BONUS) * depth if !over.nil?
      own = own_options(snapshot, board, root_actions)
      foe = foe_options(snapshot, board)
      return leaf(snapshot, board) if own.empty? || foe.empty?
      safest(snapshot, board, own, foe, depth, root_actions)
    end

    # pick_safest with the original's pruning: a row whose running minimum has already
    # fallen to the best row's minimum cannot become the best row, so the rest of it
    # is never projected.
    def self.safest(snapshot, board, own, foe, depth, root_actions)
      best = -HUGE
      own.each do |action|
        worst = HUGE
        foe.each do |reply|
          value = payoff(snapshot, board, action, reply, depth, root_actions)
          worst = value if value < worst
          break if worst <= best
        end
        best = worst if worst > best
      end
      best
    end

    def self.battle_over(snapshot, board)
      m = PortableAI.matrix(snapshot)
      return -BATTLE_OVER if side_value(m["own"], board["own_hps"])["alive"] == 0
      return BATTLE_OVER if side_value(m["foe"], board["foe_hps"])["alive"] == 0
      nil
    end

    # 0.0..1.0. A switch always "lands"; a move lands at its exported accuracy.
    def self.hit_chance(own_action)
      return 1.0 if own_action["type"] != "move"
      accuracy = Model.number(own_action["accuracy"], 100.0)
      # A self-targeting move exports no meaningful accuracy; it does not miss.
      accuracy = 100.0 if accuracy <= 0 && !Model.truthy(own_action["damaging"])
      accuracy = 100.0 if accuracy > 100.0
      accuracy = 0.0 if accuracy < 0
      accuracy / 100.0
    end

    # The foe's mirror: a named column lands at the cell's accuracy for it (0.7.9;
    # through 0.7.8 the foe never missed, which was maximin's worst case carried into
    # a tree where it no longer meant that). A column without one is certain.
    def self.foe_hit_chance(foe_action)
      return 1.0 if foe_action["kind"] != "stay" || foe_action["acc"].nil?
      accuracy = Model.number(foe_action["acc"], 100.0)
      accuracy = 100.0 if accuracy <= 0 && !Model.truthy(foe_action["damaging"])
      accuracy = 100.0 if accuracy > 100.0
      accuracy = 0.0 if accuracy < 0
      accuracy / 100.0
    end

    # The chance a body under a status gets its move off at all: the engine's own
    # numbers for paralysis and thaw; sleep at a third, the average over a counter the
    # snapshot does not carry. The original branches on all three.
    def self.act_chance(status)
      ACT_CHANCE[status.to_s] || 1.0
    end

    # THE DAMAGE ROLL. Every number the adapter hands this planner -- a cell's pct,
    # a root action's expected_damage_pct -- is pbRoughDamage, which applies NO random
    # factor and no crit: it is the MAXIMUM roll. The engine then rolls 85..100% of
    # it (082:1140). core.rb has always known this (MIN_DAMAGE_ROLL); through 0.7.8
    # this planner took the number as an expected roll, its header said so, and with a
    # step leaf at 0 HP a kill that lands on one roll in sixteen read as certain --
    # on both axes, at every ply. That is the single largest thing the search had
    # wrong about the board.
    #
    # What comes back is a list of [multiplier, probability] on the max roll -- the
    # original's `should_branch_on_damage` shape, at its arithmetic:
    #   * the roll straddles the defender's HP: a KILL branch at the fraction of the
    #     sixteen rolls that reach it, plus the crit rate, against the average of the
    #     rolls that do not;
    #   * every roll falls short: a crit branch at the crit rate, else the average;
    #   * every roll kills: one branch, certain.
    # `branch` false (below the root's children in the tree, as the original) is the
    # average roll and nothing else.
    def self.roll_outcomes(max_pct, hp, branch)
      return [[1.0, 1.0]] if max_pct <= 0.0
      return [[ROLL_AVERAGE, 1.0]] if !branch
      min_pct = max_pct * ROLL_MIN
      if max_pct >= hp && min_pct < hp
        kills = 0
        sum = 0.0
        16.times do |r|
          mult = (85 + r) / 100.0
          if max_pct * mult >= hp
            kills += 1
          else
            sum += mult
          end
        end
        p_kill = (1.0 - CRIT_RATE) * kills / 16.0 + CRIT_RATE
        misses = 16 - kills
        rest = misses > 0 ? sum / misses : ROLL_AVERAGE
        return [[1.0, p_kill], [rest, 1.0 - p_kill]]
      end
      return [[1.0, 1.0]] if min_pct >= hp
      [[ROLL_AVERAGE * CRIT_MULT, CRIT_RATE], [ROLL_AVERAGE, 1.0 - CRIT_RATE]]
    end

    # EVERY CHANCE OUTCOME OF ONE JOINT PAIR, each as [probability, own_first, chance]
    # where `chance` is what project reads: whether each side's move happens at all
    # (accuracy times the status act chance -- a miss and a full paralysis are the
    # same board, so they are one dimension), and the roll multiplier each lands at.
    # The speed order splits first when nothing establishes it. Shared by the maximin
    # (payoff averages over it) and the tree (branches keeps it as children). Sums to
    # one.
    def self.outcomes(snapshot, board, own_action, foe_action, branch_rolls)
      first = moves_first(snapshot, board, own_action, foe_action)
      orders = first.nil? ? [[true, 0.5], [false, 0.5]] : [[first, 1.0]]
      own_does = own_action["type"] == "move" ?
                 hit_chance(own_action) * act_chance(board["own_status"]) : 1.0
      foe_does = foe_action["kind"] == "stay" ?
                 foe_hit_chance(foe_action) * act_chance(board["foe_status"]) : 1.0
      after = resolve_switches(snapshot, board, own_action, foe_action)
      own_rolls = roll_outcomes(own_damage(snapshot, board, after, own_action, foe_action),
                                after["foe_hp"], branch_rolls)
      foe_rolls = roll_outcomes(foe_damage(snapshot, board, after, own_action, foe_action),
                                after["own_hp"], branch_rolls)
      own_side = []
      own_rolls.each { |roll| own_side << [own_does * roll[1], true, roll[0]] } if own_does > 0.0
      own_side << [1.0 - own_does, false, 1.0] if own_does < 1.0
      foe_side = []
      foe_rolls.each { |roll| foe_side << [foe_does * roll[1], true, roll[0]] } if foe_does > 0.0
      foe_side << [1.0 - foe_does, false, 1.0] if foe_does < 1.0
      out = []
      orders.each do |order|
        own_side.each do |o|
          foe_side.each do |f|
            prob = order[1] * o[0] * f[0]
            next if prob <= 0.0
            out << [prob, order[0],
                    { "own_does" => o[1], "own_roll" => o[2],
                      "foe_does" => f[1], "foe_roll" => f[2] }]
          end
        end
      end
      out
    end

    # true we move first, false they do, nil unknown.
    #
    # Only two moves make the question meaningful. With a switch on either side at most
    # one side deals damage that turn, so both orders project the identical board and
    # the answer here is immaterial -- true, to spend one projection rather than two.
    def self.moves_first(snapshot, board, own_action, foe_action)
      return true if own_action["type"] != "move" || foe_action["kind"] != "stay"
      priority = Model.number(own_action["priority"], 0.0)
      # 0.7.9: the foe's column carries its bracket too (version 4), so a foe's
      # Protect or Sucker Punch is no longer invisible here.
      theirs = Model.number(foe_action["priority"], 0.0)
      return true if priority > theirs
      return false if theirs > priority
      # The adapter's own speed answer for the pair on the field, which reads a Choice
      # Scarf the cell does not. Only the cell knows about hypothetical pairs, and
      # only the transformed cell knows about a speed stage we projected.
      stages = projected_stages(board)
      foe_speed_stage = Model.number((board["foe_stages"] || {})["speed"], 0.0).to_i
      if live_pair?(board) && Model.number(stages["speed"], 0.0).to_i == 0 && foe_speed_stage == 0
        live = board["live_faster"]
        return live if live == true || live == false
      end
      cell = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
      cell = boosted_cell(snapshot, PortableAI.matrix(snapshot), board, cell)
      return nil if cell.nil?
      faster = cell["faster"]
      (faster == true || faster == false) ? faster : nil
    end

    # The board after both switches and before either move: which bodies stand
    # there and at what HP. A switch-in pays its hazard damage here (both sides,
    # 0.7.9 -- the foe's from the side table). Everything a switch throws away
    # (stages, a Substitute, this turn's status delta) goes with the body.
    def self.resolve_switches(snapshot, board, own_action, foe_action)
      out = Model.copy_hash(board)
      out["protected"] = false
      out["foe_protected"] = false
      out["foe_reply"] = nil
      out["own_hps"] = Model.copy_hash(board["own_hps"])
      out["foe_hps"] = Model.copy_hash(board["foe_hps"])
      m = PortableAI.matrix(snapshot)
      if own_action["type"] == "switch"
        out["own_slot"] = own_action["slot"]
        standing = out["own_hps"].key?(out["own_slot"]) ? out["own_hps"][out["own_slot"]] :
                   Model.number(own_action["candidate_hp_pct"], 100.0)
        out["own_hp"] = standing - Model.number(own_action["entry_damage_pct"], 0.0)
        # Stages, a Substitute and this turn's own status go with the body that left.
        out["own_stages"] = {}
        out["stage_base"] = {}
        out["substitute"] = false
        out["own_status_points"] = 0.0
        out["own_seeded"] = false
        out["own_toxic"] = 0
        out["own_status"] = status_key(PortableAI.matrix_entry(m["own"], out["own_slot"]))
      end
      if foe_action["kind"] == "switch"
        out["foe_slot"] = foe_action["slot"]
        # AND THE HP THAT BODY IS ACTUALLY STANDING ON. Leaving this at the outgoing
        # body's HP was the first version's worst bug: with the active foe chipped,
        # every one of its switches read as a free kill for us, so five of six foe
        # options scored a kill and maximin was choosing between fictions. The
        # switch-in's HP is in the same side table the board was opened from.
        entry = PortableAI.matrix_entry(m["foe"], foe_action["slot"])
        standing = out["foe_hps"].key?(out["foe_slot"]) ? out["foe_hps"][out["foe_slot"]] :
                   Model.number(entry && entry["hp_pct"], 100.0)
        out["foe_hp"] = standing - Model.number(entry && entry["entry_damage_pct"], 0.0)
        out["foe_boost"] = 0.0
        out["foe_stages"] = {}
        out["foe_status_points"] = 0.0
        out["foe_substitute"] = false
        out["foe_seeded"] = false
        out["foe_toxic"] = 0
        out["foe_status"] = status_key(entry)
      end
      out
    end

    # One turn, applied to a copy. Switches resolve first; then each side acts in
    # speed order, and the body that came in eats the other side's hit in full -- the
    # same free-hit convention candidate_race charges a switch candidate (core.rb).
    # `hit` is our accuracy branch: false and our move does nothing at all, damage and
    # effects alike. `chance` (0.7.9) is the full outcome from `outcomes`: whether
    # each side's move happens and the roll it lands at; absent, the foe acts, and
    # both land at the raw number. Then the end of turn ticks (residual).
    def self.project(snapshot, board, own_action, foe_action, own_first, hit = true, chance = nil)
      chance = chance || {}
      own_does = chance.key?("own_does") ? chance["own_does"] : hit
      foe_does = chance.key?("foe_does") ? chance["foe_does"] : true
      out = resolve_switches(snapshot, board, own_action, foe_action)

      # Damage each side lands AFTER both switches have resolved, so an attack aimed at
      # a body that left hits the one that replaced it -- which is the whole reason a
      # foe switch is worth considering.
      mine = own_does ? own_damage(snapshot, board, out, own_action, foe_action) *
                        Model.number(chance["own_roll"], 1.0) : 0.0
      theirs = foe_does ? foe_damage(snapshot, board, out, own_action, foe_action) *
                          Model.number(chance["foe_roll"], 1.0) : 0.0

      if own_first
        act_own(snapshot, out, own_action, mine, own_does)
        act_foe(snapshot, out, foe_action, theirs, foe_does) if out["foe_hp"] > 0 && out["own_hp"] > 0
      else
        act_foe(snapshot, out, foe_action, theirs, foe_does)
        act_own(snapshot, out, own_action, mine, own_does) if out["own_hp"] > 0 && out["foe_hp"] > 0
      end
      residual(snapshot, out)
      out["own_hp"] = 0.0 if out["own_hp"] < 0
      out["foe_hp"] = 0.0 if out["foe_hp"] < 0
      out["own_hp"] = 100.0 if out["own_hp"] > 100.0
      out["foe_hp"] = 100.0 if out["foe_hp"] > 100.0
      out["own_hps"][out["own_slot"]] = out["own_hp"]
      out["foe_hps"][out["foe_slot"]] = out["foe_hp"]
      # Next ply's Protect fails if this one was a Protect, on either side.
      out["protect_repeats"] = out["protected"] ? 1 : 0
      out["foe_protect_repeats"] = out["foe_protected"] ? 1 : 0
      out
    end

    # Our action on the board: the damage, then everything the move does besides,
    # each the original's evaluate term applied where the original's instruction
    # generator would apply it. A miss (hit false) applies nothing. A foe Protect
    # (0.7.9) takes the whole move; a foe Substitute takes the damage and every
    # effect aimed at the body behind it, and breaks unless the hit was under its HP.
    def self.act_own(snapshot, out, action, damage, hit)
      return if action["type"] != "move" || !hit
      return if out["foe_protected"]
      tags = Effects.describe(action["move_id"], action["tags"])
      move_id = action["move_id"].to_s.upcase
      shielded = out["foe_substitute"] ? true : false
      if shielded
        out["foe_substitute"] = false if damage >= SUBSTITUTE_COST
      else
        out["foe_hp"] -= damage
      end

      if damage > 0
        recoil = Model.number(action["recoil_fraction"], 0.0)
        out["own_hp"] -= damage * recoil if recoil > 0
        drain = Model.number(action["drain_fraction"], 0.0)
        out["own_hp"] = [100.0, out["own_hp"] + damage * drain].min if drain > 0 && !shielded
      end
      out["own_hp"] = 0.0 if tags.include?("self_ko")

      if tags.include?("setup")
        stages = Effects.setup_stages(move_id)
        if tags.include?("hp_cost_half")
          # Belly Drum fails below half; above it, half is the price.
          stages = nil if out["own_hp"] <= 50.0
          out["own_hp"] -= 50.0 if !stages.nil?
        end
        add_stages(out, stages)
      end
      add_stages(out, Effects.self_drop_stages(move_id)) if tags.include?("self_drop")
      if action["effect_kind"].to_s == "self_raise" &&
         Model.number(action["effect_chance"], 100.0) >= 100.0
        add_stages(out, { action["effect_stat"].to_s => 1 })
      end

      if tags.include?("heal") || tags.include?("variable_heal")
        out["own_hp"] = [100.0, out["own_hp"] + Effects.heal_amount(snapshot, tags)].min
        if tags.include?("self_sleep")
          out["own_status_points"] -= STATUS_VALUE["sleep"]
          out["own_status"] = "sleep"
        end
      end

      # Protect fails on a repeat; the memory counter is the only record of one.
      if tags.include?("protect") && out["protect_repeats"] <= 0
        out["protected"] = true
      end
      if tags.include?("substitute") && !out["substitute"] && out["own_hp"] > SUBSTITUTE_COST
        out["own_hp"] -= SUBSTITUTE_COST
        out["substitute"] = true
      end

      if tags.include?("hazard")
        layers = Model.number(action["existing_layers"], 0.0)
        cap = Model.number(action["max_layers"], 1.0)
        if layers < cap
          per_body = HAZARD_VALUE[move_id] || 0.0
          bodies = PortableAI.matrix_live_slots(PortableAI.matrix(snapshot)["foe"]).length
          out["foe_hazard_points"] += per_body * bodies
        end
      end

      # A status or a stat drop on the foe, at the chance the adapter exported: 100 for
      # a status move the engine says can land, 0 for one it says cannot (already
      # statused, immune, Sheer Force), the secondary rate for a damaging move.
      return if shielded
      kind = action["effect_kind"]
      kind = Effects.kind_of(tags, "secondary") if kind.nil?
      kind = status_kind(tags) if kind.nil? && tags.include?("status")
      return if kind.nil?
      # One status per body: a second Toxic on a foe this search already poisoned is
      # the engine refusing it, which the root's chance export cannot know a ply on.
      return if tags.include?("status") && (out["foe_status_points"] > 0 || !out["foe_status"].nil?)
      chance = Model.number(action["effect_chance"], 100.0)
      return if chance <= 0
      chance = 100.0 if chance > 100.0
      kind = kind.to_s
      if kind == "drop"
        value = STAGE_VALUE[action["effect_stat"].to_s] || 0.0
        out["foe_boost"] -= value * chance / 100.0
      elsif STATUS_VALUE.key?(kind)
        value = STATUS_VALUE[kind]
        value = value * (Model.truthy(action["target_physical_attacker"]) ? 1.0 : 0.5) if kind == "burn"
        value = STATUS_VALUE["toxic"] if kind == "poison" && move_id == "TOXIC"
        out["foe_status_points"] += value * chance / 100.0
        # A certain status is on the body for the plies that follow: it ticks, and
        # it decides whether the body acts. A secondary is points only.
        if chance >= 100.0
          if kind == "drain"
            out["foe_seeded"] = true
          elsif !out["foe_status"].nil?
            # already carrying one
          else
            out["foe_status"] = (kind == "poison" && move_id == "TOXIC") ? "toxic" : kind
          end
        end
      end
    end

    # THEIR action on the board (0.7.9), the mirror of act_own: the damage through our
    # Protect or Substitute, then whatever the column's move does besides -- its own
    # setup or drop, a heal, a Protect, a Substitute, a hazard on our side, a status
    # or a stat drop on us -- from the tags its id carries and the effect triple the
    # cell exported. Through 0.7.8 this was the damage and nothing else, because the
    # foe's columns were damaging moves and nothing else.
    def self.act_foe(snapshot, out, foe_action, damage, acts = true)
      return if foe_action["kind"] != "stay" || !acts
      return if out["protected"]
      shielded = out["substitute"] ? true : false
      if damage > 0
        if shielded
          out["substitute"] = false if damage >= SUBSTITUTE_COST
        else
          out["own_hp"] -= damage
        end
      end
      move_id = foe_action["move_id"]
      return if move_id.nil?
      move_id = move_id.to_s.upcase
      tags = Effects.describe(move_id, [])
      out["foe_hp"] = 0.0 if tags.include?("self_ko")

      if tags.include?("setup")
        stages = Effects.setup_stages(move_id)
        if tags.include?("hp_cost_half")
          stages = nil if out["foe_hp"] <= 50.0
          out["foe_hp"] -= 50.0 if !stages.nil?
        end
        add_stages(out, stages, "foe_stages")
      end
      add_stages(out, Effects.self_drop_stages(move_id), "foe_stages") if tags.include?("self_drop")

      if tags.include?("heal") || tags.include?("variable_heal")
        out["foe_hp"] = [100.0, out["foe_hp"] + Effects.heal_amount(snapshot, tags)].min
        if tags.include?("self_sleep")
          out["foe_status_points"] += STATUS_VALUE["sleep"]
          out["foe_status"] = "sleep"
        end
      end
      if tags.include?("protect") && Model.number(out["foe_protect_repeats"], 0.0) <= 0
        out["foe_protected"] = true
      end
      if tags.include?("substitute") && !out["foe_substitute"] && out["foe_hp"] > SUBSTITUTE_COST
        out["foe_hp"] -= SUBSTITUTE_COST
        out["foe_substitute"] = true
      end
      if tags.include?("hazard")
        # The snapshot carries our side's hazards as one count, so a foe hazard lands
        # when our side is clear and this search has not laid this one already.
        laid = out["foe_laid"] || {}
        if Model.number(out["own_hazard_layers"], 0.0) <= 0 && !laid[move_id]
          per_body = HAZARD_VALUE[move_id] || 0.0
          bodies = PortableAI.matrix_live_slots(PortableAI.matrix(snapshot)["own"]).length
          out["own_hazard_points"] += per_body * bodies
          laid = Model.copy_hash(laid)
          laid[move_id] = true
          out["foe_laid"] = laid
        end
      end

      return if shielded
      effect = foe_action["effect"].is_a?(Array) ? foe_action["effect"] : [nil, nil, nil]
      kind = effect[0]
      kind = status_kind(tags) if kind.nil? && tags.include?("status")
      return if kind.nil?
      return if tags.include?("status") && (out["own_status_points"] < 0 || !out["own_status"].nil?)
      chance = Model.number(effect[2], 100.0)
      return if chance <= 0
      chance = 100.0 if chance > 100.0
      kind = kind.to_s
      if kind == "drop"
        add_stages(out, { effect[1].to_s => -1 }) if chance >= 100.0
      elsif kind == "self_raise"
        add_stages(out, { effect[1].to_s => 1 }, "foe_stages") if chance >= 100.0
      elsif STATUS_VALUE.key?(kind)
        value = STATUS_VALUE[kind]
        value = STATUS_VALUE["toxic"] if kind == "poison" && move_id == "TOXIC"
        out["own_status_points"] -= value * chance / 100.0
        if chance >= 100.0
          if kind == "drain"
            out["own_seeded"] = true
          elsif out["own_status"].nil?
            out["own_status"] = (kind == "poison" && move_id == "TOXIC") ? "toxic" : kind
          end
        end
      end
    end

    # THE END OF THE TURN (0.7.9). What the original applies as end-of-turn
    # instructions every ply and this planner never did: Leftovers and Black Sludge,
    # burn, poison and the Toxic ladder, sand and hail on the bodies they touch, and
    # Leech Seed both ways. Through 0.7.8 a Toxic was thirty points forever and never
    # became HP, so an eight-ply tree could not see a stall matchup from either side.
    # Immunities the leaf knows about: Magic Guard (no residual damage at all), Poison
    # Heal, the sand and hail types and abilities.
    def self.residual(snapshot, out)
      m = PortableAI.matrix(snapshot)
      weather = (snapshot || {})["weather"].to_s
      ["own", "foe"].each do |side|
        hp_key = side + "_hp"
        next if out[hp_key] <= 0
        entry = PortableAI.matrix_entry(m[side], out[side + "_slot"]) || {}
        ability = entry["ability"].to_s.upcase
        item = entry["item"].to_s.upcase
        types = (entry["types"] || []).map { |t| t.to_s.upcase }
        guarded = ability == "MAGICGUARD"
        delta = 0.0
        if item == "LEFTOVERS"
          delta += RESIDUAL_SIXTEENTH
        elsif item == "BLACKSLUDGE"
          delta += types.include?("POISON") ? RESIDUAL_SIXTEENTH : (guarded ? 0.0 : -RESIDUAL_EIGHTH)
        end
        status = out[side + "_status"].to_s
        if status == "burn"
          delta -= RESIDUAL_EIGHTH if !guarded
        elsif status == "poison"
          delta += ability == "POISONHEAL" ? RESIDUAL_EIGHTH : (guarded ? 0.0 : -RESIDUAL_EIGHTH)
        elsif status == "toxic"
          count = Model.number(out[side + "_toxic"], 0.0).to_i + 1
          out[side + "_toxic"] = count
          delta += ability == "POISONHEAL" ? RESIDUAL_EIGHTH :
                   (guarded ? 0.0 : -RESIDUAL_SIXTEENTH * count)
        end
        if weather == "sand" && !guarded && !SAND_PROOF_ABILITIES.include?(ability) &&
           (types & SAND_PROOF_TYPES).empty?
          delta -= RESIDUAL_SIXTEENTH
        elsif weather == "hail" && !guarded && !HAIL_PROOF_ABILITIES.include?(ability) &&
              !types.include?("ICE")
          delta -= RESIDUAL_SIXTEENTH
        end
        if out[side + "_seeded"] && !guarded
          delta -= RESIDUAL_EIGHTH
          other = side == "own" ? "foe_hp" : "own_hp"
          out[other] += RESIDUAL_EIGHTH if out[other] > 0
        end
        out[hp_key] += delta
      end
      out
    end

    # The engine's status code on a side-table entry (PBStatuses: 1 sleep, 2 poison,
    # 3 burn, 4 paralysis, 5 frozen), as the name this planner keys on; nil healthy.
    def self.status_key(entry)
      return nil if entry.nil?
      raw = entry["status"]
      return nil if raw.nil?
      return STATUS_CODES[raw.to_i] if raw.is_a?(Numeric) || raw.to_s =~ /\A\d+\z/
      name = raw.to_s.downcase
      return nil if name == "" || name == "none" || name == "healthy" || name == "0"
      STATUS_NAMES[name] || name
    end

    def self.status_kind(tags)
      %w[poison burn paralyze sleep freeze confuse drain].each do |kind|
        return kind if tags.include?(kind)
      end
      nil
    end

    def self.add_stages(out, stages, key = "own_stages")
      return if stages.nil?
      merged = Model.copy_hash(out[key] || {})
      stages.each do |stat, delta|
        value = Model.number(merged[stat], 0.0).to_i + delta.to_i
        value = 6 if value > 6
        value = -6 if value < -6
        if value == 0
          merged.delete(stat)
        else
          merged[stat] = value
        end
      end
      out[key] = merged
    end

    # The damage our move lands when it lands. Accuracy is payoff's branch, not a
    # multiplier here.
    def self.own_damage(snapshot, board, projected, own_action, foe_action)
      return 0.0 if own_action["type"] != "move"
      cell = PortableAI.matrix_cell(snapshot, projected["own_slot"], projected["foe_slot"])
      priced = cell_move(cell, own_action["move_id"])
      category = priced ? priced["cat"] : nil
      raw = nil
      if foe_action["kind"] == "switch"
        # A body we have no live estimate against. Through 0.7.3 the cell was ONE
        # number -- the best this body has against that one -- so every move we could
        # click was credited the same damage against a switch-in and the foe-switch
        # column could not order our moves against each other; depth two showed that
        # was the bottleneck (190 of 227 move-versus-move disagreements sat in that
        # column). The cell now carries every damaging move it rolled (out_moves,
        # matrix version 2), so THIS move gets its own number against that body: a
        # 0 for the Earthquake their Flying-type shrugs off, the full Ice Beam for
        # the one it does not. A cell without the list (an older adapter, a move the
        # cell never rolled) still falls back to the one best number. A move that
        # deals nothing on the field deals nothing to a switch-in either.
        return 0.0 if !Model.truthy(own_action["damaging"])
        raw = priced ? Model.number(priced["pct"], 0.0) :
                       (cell.nil? ? 0.0 : Model.number(cell["out"], 0.0))
      else
        # The engine's own number for the pair on the field, which is better than the
        # cell: it carries this move, these stages, this weather -- and a stage this
        # search projected on top, by the category the cell priced this move in.
        raw = Model.number(own_action["expected_damage_pct"], 0.0)
      end
      # ...and the foe's own projected defence stages on the way in (0.7.9).
      raw * offence_multiplier(snapshot, projected, category) /
        stage_divisor(projected["foe_stages"], category, snapshot, projected, "out_cat", "def", "spd")
    end

    # The cell's own roll of one move, or nil when the cell has no such list.
    def self.cell_move(cell, move_id)
      return nil if cell.nil? || move_id.nil?
      moves = cell["out_moves"]
      return nil if !moves.is_a?(Hash)
      entry = moves[move_id.to_s.upcase]
      entry.is_a?(Hash) ? entry : nil
    end

    # The stages this search has put on the body ON TOP of the ones the engine's
    # numbers already carry: own_stages less the root's stage_base, per stat.
    def self.projected_stages(board)
      stages = board["own_stages"] || {}
      base = board["stage_base"] || {}
      out = {}
      stages.each do |stat, stage|
        delta = stage.to_i - Model.number(base[stat], 0.0).to_i
        out[stat] = delta if delta != 0
      end
      base.each do |stat, stage|
        next if stages.key?(stat)
        delta = -stage.to_i
        out[stat] = delta if delta != 0
      end
      out
    end

    # How a projected Attack or Special Attack stage scales what the body deals, by
    # the category the move is priced in -- or, for a move the cell never rolled, the
    # category of the body's best hit into the foe on the field (the cell's out_cat).
    def self.offence_multiplier(snapshot, board, category = nil)
      stages = projected_stages(board)
      return 1.0 if stages.empty?
      if category.nil?
        cell = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
        category = cell && cell["out_cat"]
      end
      stat = (category == "special") ? "spa" : "atk"
      stage = Model.number(stages[stat], 0.0).to_i
      stage == 0 ? 1.0 : Effects.stage_multiplier(stage)
    end

    # The mirror for what the body takes: by the category of the move the foe column
    # actually named (0.7.7), or of its best hit for a column that names none.
    def self.defence_divisor(snapshot, board, category = nil)
      stages = projected_stages(board)
      return 1.0 if stages.empty?
      if category.nil?
        cell = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
        category = cell && cell["in_cat"]
      end
      stat = (category == "special") ? "spd" : "def"
      stage = Model.number(stages[stat], 0.0).to_i
      stage == 0 ? 1.0 : Effects.stage_multiplier(stage)
    end

    # A stage table (the FOE's projected stages, 0.7.9) read as a ratio for one
    # category: `cat_key` names the cell field that says which category a column
    # without one is priced in, `physical`/`special` the stat each maps to.
    def self.stage_divisor(stages, category, snapshot, board, cat_key, physical, special)
      return 1.0 if stages.nil? || stages.empty?
      if category.nil?
        cell = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
        category = cell && cell[cat_key]
      end
      stage = Model.number(stages[(category == "special") ? special : physical], 0.0).to_i
      stage == 0 ? 1.0 : Effects.stage_multiplier(stage)
    end

    # A switching foe deals nothing this turn. A staying one hits whatever is in front
    # of it, and the number is read from the thickest view the snapshot has of that
    # pair: the actor view for the body already on the field, the switch candidate's
    # own estimate (Intimidate-aware, every foe move, a real damage roll) for a body
    # we bring in, and the cell only for a pair nothing else has priced.
    def self.foe_damage(snapshot, board, projected, own_action, foe_action)
      return 0.0 if foe_action["kind"] != "stay"
      # 0.7.7. THE FOE NAMED A MOVE, so this is that move's number and not the best
      # one it owns -- and it is read against whatever body is standing AFTER our
      # switch resolves, exactly as own_damage prices our move against their
      # switch-in. Falling back to the column's own number for a pair the matrix
      # never rolled.
      if !foe_action["move_id"].nil?
        return 0.0 if !Model.truthy(foe_action["damaging"]) && Model.number(foe_action["pct"], 0.0) <= 0.0
        priced = cell_in_move(
          PortableAI.matrix_cell(snapshot, projected["own_slot"], projected["foe_slot"]),
          foe_action["move_id"])
        raw = priced ? Model.number(priced["pct"], 0.0) : Model.number(foe_action["pct"], 0.0)
        category = priced ? priced["cat"] : foe_action["cat"]
        return raw / defence_divisor(snapshot, projected, category) *
               stage_divisor(projected["foe_stages"], category, snapshot, projected, "in_cat", "atk", "spa")
      end
      raw = nil
      raw = board["live_incoming"] if live_pair?(projected) && !board["live_incoming"].nil?
      if raw.nil? && own_action["type"] == "switch" && !own_action["incoming_damage_pct"].nil?
        raw = Model.number(own_action["incoming_damage_pct"], 0.0)
      end
      if raw.nil?
        cell = PortableAI.matrix_cell(snapshot, projected["own_slot"], projected["foe_slot"])
        raw = cell.nil? ? 0.0 : Model.number(cell["in"], 0.0)
      end
      raw / defence_divisor(snapshot, projected) *
        stage_divisor(projected["foe_stages"], nil, snapshot, projected, "in_cat", "atk", "spa")
    end

    # ------------------------------------------------------------------------------
    # The leaf: every live body on both sides, at the HP it stands on, plus the terms
    # the original's evaluate carries for the body on the field -- its stages, a
    # Substitute, a status landed this turn, hazards on the other side -- and, 0.7.9,
    # the same terms for THEIR body on the field. Each side's HP map overrides the
    # table for the bodies this search has touched; every other body is as the side
    # table has it.

    def self.leaf(snapshot, board)
      m = PortableAI.matrix(snapshot)
      own = side_value(m["own"], board["own_hps"])
      foe = side_value(m["foe"], board["foe_hps"])
      return -BATTLE_OVER if own["alive"] == 0
      return BATTLE_OVER if foe["alive"] == 0
      score = own["points"] - foe["points"]
      if board["own_hp"] > 0
        score += stage_points(board["own_stages"])
        score += SUBSTITUTE_VALUE if board["substitute"]
        score += board["own_status_points"]
      end
      if board["foe_hp"] > 0
        score -= board["foe_boost"]
        score -= stage_points(board["foe_stages"])
        score -= SUBSTITUTE_VALUE if board["foe_substitute"]
        score += board["foe_status_points"]
      end
      score += board["foe_hazard_points"]
      score -= Model.number(board["own_hazard_points"], 0.0)
      score
    end

    # The pair's cell as it reads under the stages this search projected -- a Dragon
    # Dance flips who moves first, which is what moves_first asks it for. The stages
    # the body already carried are inside the cell (matrix_bodies prices a body on
    # the field through its real battler), so only the projected ones apply. The
    # foe's projected speed stage (0.7.9) scales its side of the comparison.
    def self.boosted_cell(snapshot, m, board, cell)
      stages = projected_stages(board)
      foe_speed_stage = Model.number((board["foe_stages"] || {})["speed"], 0.0).to_i
      return cell if cell.nil? || (stages.empty? && foe_speed_stage == 0)
      own = PortableAI.matrix_entry(m["own"], board["own_slot"])
      foe = PortableAI.matrix_entry(m["foe"], board["foe_slot"])
      foe_speed = foe && foe["speed"]
      foe_speed = foe_speed.to_f * Effects.stage_multiplier(foe_speed_stage) if !foe_speed.nil? && foe_speed_stage != 0
      stages = Model.copy_hash(stages)
      # A foe speed stage with none of ours: hand the transform a zero own stage so
      # it still recomputes the order against the scaled foe speed.
      stages["speed"] = 0 if foe_speed_stage != 0 && !stages.key?("speed")
      if stages["speed"] == 0
        out = PortableAI.matrix_transform_cell(cell, stages, own && own["speed"], foe_speed,
                                               Model.truthy(snapshot["trick_room_active"]))
        own_speed = own && own["speed"]
        if !own_speed.nil? && !foe_speed.nil?
          trick = Model.truthy(snapshot["trick_room_active"])
          out["faster"] = trick ? own_speed.to_f < foe_speed.to_f : own_speed.to_f > foe_speed.to_f
        end
        return out
      end
      PortableAI.matrix_transform_cell(cell, stages, own && own["speed"], foe_speed,
                                       Model.truthy(snapshot["trick_room_active"]))
    end

    # The original's boost term: 30 a stage of offence or speed, 15 of defence,
    # through its diminishing multiplier (a second stage is worth as much as the
    # first, a third half as much, the sixth almost nothing more).
    def self.stage_points(stages)
      total = 0.0
      (stages || {}).each do |stat, stage|
        total += (STAGE_VALUE[stat.to_s] || 0.0) * stage_multiplier(stage.to_i)
      end
      total
    end

    def self.stage_multiplier(stage)
      sign = stage < 0 ? -1.0 : 1.0
      sign * (STAGE_MULTIPLIER[stage.abs] || STAGE_MULTIPLIER[6])
    end

    # Every live body on a side, at the HP the search's map says or, for a body the
    # search never touched, the table's.
    def self.side_value(table, hps)
      points = 0.0
      alive = 0
      hps = hps || {}
      (table || []).each do |entry|
        next if entry.nil? || entry["alive"] == false
        slot = entry["slot"]
        body_hp = hps.key?(slot) ? hps[slot] : Model.number(entry["hp_pct"], 0.0)
        next if body_hp <= 0
        points += body_hp + BODY_ALIVE
        alive += 1
      end
      { "points" => points, "alive" => alive }
    end

    # ------------------------------------------------------------------------------
    # THE TREE (0.7.6). A third planner path on the same board, off unless
    # `search_mcts` is set -- and with it off `plan` never reaches this section, so a
    # run without the key reproduces 0.7.5 decision for decision.
    #
    # WHY, given the maximin above sits at 46/60 against the rule engine's 48. Every
    # gain this month came from the board model and the opponent model, not from more
    # search: depth 2 was +1 over depth 1, and the whole 40 -> 46 was blending one
    # predicted reply into the root rows. That blend is a TABLE -- the foe's columns
    # weighted by what stock v16's triggers say it does -- and the AI's real opponent
    # is the player, who is not stock. The question this path asks is whether a tree
    # that lets the foe's line be shaped by ITS OWN payoff, over many iterations,
    # beats the one number. Ruby is slow and that is fine: the budget is an iteration
    # count, the gauntlet is a study harness and not a 100 ms move clock, so a
    # generous budget here answers the question a Rust port would only make faster.
    #
    # PROVENANCE: poke-engine's src/mcts.rs (GPL-3.0), the path Foul Play runs today,
    # read 2026-09-08. Four ideas, no code:
    #   * DECOUPLED simultaneous-move MCTS -- one node, two independent option lists,
    #     each side selecting its own by UCB1 without seeing the other's pick. The
    #     justification is Tak, Lanctot & Winands, "Monte Carlo Tree Search in
    #     Simultaneous Move Games" (2014); a sequential tree here would let one side
    #     answer a move it cannot see.
    #   * chance outcomes ENUMERATED into children with their probabilities, then one
    #     sampled by weight per iteration -- the same branching payoff already does,
    #     kept as nodes instead of averaged away.
    #   * NO PLAYOUT. The new board is scored by the static leaf relative to the root
    #     and squashed, `sigmoid(eval - root_eval)`. A random playout in a game this
    #     branchy is noise; the leaf is the same evaluate the maximin trusts.
    #   * the foe credited `1 - score`, and the pick being the MOST-VISITED root
    #     option (Foul Play's convention), not the highest average.
    # Not borrowed: the instruction generator (our `project` is the transition) and
    # reversible instructions (each node holds its own board copy; Model.copy_hash is
    # the undo).
    #
    # THE OPPONENT MODEL HERE IS THE TREE ITSELF. `foe_reply` / `column_weights` --
    # 0.7.5's table -- are deliberately NOT read on this path: the whole point is to
    # see what the foe's own payoff says when nothing tells it what to do. 0.7.8's
    # search_foe_prior is the follow-up, and it does NOT bring the opponent-model
    # producer in: what it steers by is `foe_prior`, damage the cell had already
    # priced, because the diagnostic found the tree's own foe model losing to it.
    MCTS_HORIZON = 8
    MCTS_DEFAULT_ITERATIONS = 1000
    # PUCT's exploration constant, AlphaZero's scale. Only reached under
    # search_foe_prior; the tree without the key is the 0.7.7 tree exactly.
    MCTS_PRIOR_C = 1.0
    # The original's scale: "~200 points is very close to 1.0", which in this leaf's
    # currency is two bodies' worth of swing.
    SIGMOID_SCALE = 0.0125

    def self.mcts_plan(snapshot, config, board, own_actions, foe_actions)
      started = Time.now
      iterations = iterations_of(config)
      prior_on = config["search_foe_prior"] ? true : false
      rng = Lcg.new(mcts_seed(snapshot, board, config))
      root = node_for(board, 0)
      # The root's own options are the EXPORTED actions -- legality, PP, the Choice
      # lock, every per-move number against this foe. Only the plies below have to
      # settle for own_options' matrix reconstruction.
      root["own"] = own_actions
      root["foe"] = foe_actions
      root_leaf = leaf(snapshot, board)
      count = 0
      while count < iterations
        mcts_iterate(snapshot, root, root_leaf, own_actions, rng, prior_on)
        count += 1
      end

      ranked = []
      own_actions.each_with_index do |action, i|
        stat = root["own_stats"][i]
        scored = Model.copy_hash(action)
        scored["score"] = average(stat)
        scored["search_visits"] = stat["visits"]
        # The row the readouts print, in foe_actions order: this action's average
        # score against each foe column. nil is "the tree never tried that pair",
        # which a 0.0 -- a real, and very bad, score -- would hide.
        row = []
        j = 0
        while j < foe_actions.length
          cell = root["cells"][[i, j]]
          row << (cell.nil? || cell["visits"] == 0 ? nil : cell["total"] / cell["visits"])
          j += 1
        end
        scored["search_row"] = row
        # As on the maximin path: the on-field cell the leaf and the ordering are read
        # from, because nothing else in a trace can tell a real certain death from a
        # misread cell.
        scored["search_cell"] = PortableAI.matrix_cell(snapshot, board["own_slot"], board["foe_slot"])
        scored["reasons"] = [["search_visits", stat["visits"]],
                             ["search_avg", scored["score"]],
                             ["search_iterations", iterations]]
        ranked << scored
      end
      ranked.sort! { |a, b| mcts_compare(a, b) }

      {
        "actions" => [ranked[0]],
        "memory_updates" => Effects.memory_updates([ranked[0]]),
        "diagnostics" => {
          "version" => VERSION,
          "planner" => "mcts",
          "iterations" => iterations,
          "horizon" => MCTS_HORIZON,
          # Wall clock, diagnostics only -- nothing branches on it, so a slow machine
          # and a fast one make the identical decisions. It is here because the budget
          # question is "how many iterations can a real run afford".
          "elapsed_ms" => ((Time.now - started) * 1000.0).to_i,
          "format" => "single",
          "joint_adjustment" => 0,
          "foe_options" => foe_actions.map { |f| foe_label(f) },
          # THE TREE'S OWN OPPONENT MODEL, readable against 0.7.5's foe_reply: how the
          # foe's visits spread over its options once its own payoff chose them.
          "foe_visits" => root["foe_stats"].map { |s| s["visits"] },
          "board" => board,
          "candidate_counts" => [ranked.length],
          "rankings" => [ranked]
        }
      }
    end

    def self.iterations_of(config)
      count = Model.number((config || {})["search_iterations"], MCTS_DEFAULT_ITERATIONS).to_i
      count < 1 ? 1 : count
    end

    # Foul Play's convention: the most-visited root option, the one UCB1 kept coming
    # back to. Its average breaks a tie, then the key -- so a tie never follows the
    # order the adapter happened to export actions in, as in `compare`.
    def self.mcts_compare(a, b)
      by_visits = b["search_visits"] <=> a["search_visits"]
      return by_visits if by_visits != 0
      by_score = b["score"] <=> a["score"]
      return by_score if by_score != 0
      key(a) <=> key(b)
    end

    def self.average(stat)
      stat["visits"] > 0 ? stat["total"] / stat["visits"] : 0.0
    end

    # A node is a board, the two option lists over it, one statistic per option per
    # side, and the chance children of each pair already expanded. `ply` is the
    # distance from the root, which is the only thing bounding the tree.
    def self.node_for(board, ply)
      { "board" => board, "ply" => ply, "visits" => 0,
        "own" => nil, "foe" => nil, "own_stats" => nil, "foe_stats" => nil,
        "children" => {}, "cells" => {} }
    end

    # Option lists and their statistics, built on first visit. Most nodes an iteration
    # creates are never descended into again, so enumerating options in `branches`
    # would price every leaf at a full option build.
    def self.populate(snapshot, node, root_actions, prior_on = false)
      return node if !node["own_stats"].nil?
      node["own"] = own_options(snapshot, node["board"], root_actions) if node["own"].nil?
      node["foe"] = foe_options(snapshot, node["board"]) if node["foe"].nil?
      node["own_stats"] = node["own"].map { { "total" => 0.0, "visits" => 0 } }
      node["foe_stats"] = node["foe"].map { { "total" => 0.0, "visits" => 0 } }
      node["foe_prior"] = prior_on ? foe_prior(node["foe"]) : nil
      node
    end

    # Scored where it stands and never expanded: the battle is over, a side has no
    # option, or the horizon is reached. THE HORIZON IS NOT OPTIONAL -- `project` does
    # not always change HP (a Protect, a stage-only turn, two switches), so a tree
    # without one can descend forever on a board that never resolves.
    def self.terminal_node?(snapshot, node)
      return true if node["ply"] >= MCTS_HORIZON
      return true if !battle_over(snapshot, node["board"]).nil?
      node["own"].empty? || node["foe"].empty?
    end

    # Decoupled UCB1, the original's numbers: `avg + sqrt(2 ln N / n)`, an unvisited
    # option ahead of every visited one. Called once per side per node, and neither
    # call sees the other's answer -- that independence is what makes this a
    # simultaneous-move tree.
    def self.ucb_pick(stats, parent_visits, prior = nil)
      # N is 0 on a node's first visit and ln 0 is not a number; every option is
      # unvisited then, so the exploration term is never reached.
      ln = parent_visits > 0 ? Math.log(parent_visits.to_f) : 0.0
      # 0.7.8, foe axis only. AlphaZero's PUCT term ADDED to UCB1 rather than
      # replacing it: `c * P(j) * sqrt(N) / (1 + n)` steers the split between the
      # foe's columns while UCB1's own term underneath keeps every column sampled --
      # so a column the prior prices at zero (Volt Switch off a Choice Specs set, a
      # status move) is still explored on merit, which a bare PUCT would starve.
      root = prior.nil? ? 0.0 : Math.sqrt(ln > 0.0 ? parent_visits.to_f : 0.0)
      best = -HUGE
      chosen = 0
      stats.each_with_index do |stat, i|
        visits = stat["visits"]
        value = visits == 0 ? HUGE :
                stat["total"] / visits + Math.sqrt(2.0 * ln / visits)
        value += MCTS_PRIOR_C * prior[i] * root / (1.0 + visits) if !prior.nil? && visits > 0
        if value > best
          best = value
          chosen = i
        end
      end
      chosen
    end

    # The chance outcomes of one joint pair, each with its probability -- the same
    # list `payoff` averages over (outcomes), kept as children so the tree can sample
    # them. The board of a child is NOT built here: an expansion enumerates every
    # outcome of the pair and an iteration walks into exactly one, so each child is
    # projected the first time it is sampled (child_node) and never otherwise.
    # The damage roll branches at the root and the root's children only, as the
    # original's should_branch_on_damage; deeper the average roll stands in.
    def self.branches(snapshot, node, i, j, root_actions)
      own_action = node["own"][i]
      foe_action = node["foe"][j]
      outcomes(snapshot, node["board"], own_action, foe_action, node["ply"] <= 1).map do |spec|
        { "prob" => spec[0], "order" => spec[1], "chance" => spec[2], "node" => nil }
      end
    end

    # The child's node, projected on first use and kept.
    def self.child_node(snapshot, parent, i, j, child)
      return child["node"] if !child["node"].nil?
      board = project(snapshot, parent["board"], parent["own"][i], parent["foe"][j],
                      child["order"], true, child["chance"])
      child["node"] = node_for(board, parent["ply"] + 1)
      child["node"]
    end

    def self.sample_branch(children, rng)
      roll = rng.next_float
      total = 0.0
      children.each do |child|
        total += child["prob"]
        return child if roll < total
      end
      children[children.length - 1]
    end

    # One iteration: descend by UCB1, sampling a chance branch at each step; expand the
    # first pair that has none; score the board reached; credit it back up the path.
    def self.mcts_iterate(snapshot, root, root_leaf, root_actions, rng, prior_on = false)
      path = []
      node = root
      while true
        populate(snapshot, node, root_actions, prior_on)
        break if terminal_node?(snapshot, node)
        i = ucb_pick(node["own_stats"], node["visits"])
        j = ucb_pick(node["foe_stats"], node["visits"], node["foe_prior"])
        path << [node, i, j]
        children = node["children"][[i, j]]
        if children.nil?
          children = branches(snapshot, node, i, j, root_actions)
          node["children"][[i, j]] = children
          # Expansion ends the descent: the new child is what this iteration scores.
          node = child_node(snapshot, node, i, j, sample_branch(children, rng))
          break
        end
        node = child_node(snapshot, node, i, j, sample_branch(children, rng))
      end
      backprop(path, evaluate_node(snapshot, node, root_leaf))
    end

    # No playout. The board is worth what the leaf says about it RELATIVE TO THE ROOT,
    # squashed to 0..1 -- the original's `sigmoid(eval - root_eval)`. Relative because
    # UCB1 needs a bounded reward and the leaf is unbounded HP points; a board that
    # ended the battle is the bound itself.
    def self.evaluate_node(snapshot, node, root_leaf)
      over = battle_over(snapshot, node["board"])
      return (over > 0 ? 1.0 : 0.0) if !over.nil?
      sigmoid(leaf(snapshot, node["board"]) - root_leaf)
    end

    def self.sigmoid(x)
      1.0 / (1.0 + Math.exp(-SIGMOID_SCALE * x))
    end

    # Up the path: our option is credited the score, theirs its complement -- one leaf,
    # read from both ends of a zero-sum game. The per-cell tally is ours and not the
    # original's: decoupled statistics cannot say what a ROW scored, and the row is
    # what a readout needs to see why the pick went where it did.
    def self.backprop(path, score)
      path.each do |entry|
        node = entry[0]
        i = entry[1]
        j = entry[2]
        node["visits"] += 1
        own = node["own_stats"][i]
        own["total"] += score
        own["visits"] += 1
        foe = node["foe_stats"][j]
        foe["total"] += 1.0 - score
        foe["visits"] += 1
        cell = node["cells"][[i, j]]
        if cell.nil?
          cell = { "total" => 0.0, "visits" => 0 }
          node["cells"][[i, j]] = cell
        end
        cell["total"] += score
        cell["visits"] += 1
      end
    end

    # A stable fingerprint of the position: the turn, the pair on the field, and every
    # body's HP on both sides, plus `search_seed`. Mixed rather than summed, so two
    # boards that differ only in which body holds a number do not collide.
    def self.mcts_seed(snapshot, board, config)
      seed = Model.number((config || {})["search_seed"], 0.0).to_i
      parts = [Model.number(snapshot["turn"], 0.0).to_i,
               board["own_slot"].to_i, board["foe_slot"].to_i]
      m = PortableAI.matrix(snapshot) || {}
      ["own", "foe"].each do |side|
        (m[side] || []).each do |entry|
          next if entry.nil?
          parts << entry["slot"].to_i
          parts << Model.number(entry["hp_pct"], 0.0).round.to_i
        end
      end
      parts.each { |part| seed = ((seed * 33) + part) & 0x3FFFFFFF }
      seed
    end

    # The chance branches are SAMPLED, so the tree needs a stream -- and it must not be
    # the battle's. `pbAIRandom` decides the engine's own rolls: drawing from it here
    # would change the battle a shadow run is meant to observe without disturbing, and
    # would make a traced decision unrepeatable. This is the adapter's NeutralRNG
    # recurrence, seeded per decision from the position alone, so a paired run and its
    # shadow twin agree and a readout can replay any decision from its snapshot.
    class Lcg
      def initialize(seed)
        @state = (seed.to_i & 0x3FFFFFFF)
      end

      def next_float
        @state = ((@state * 1103515245) + 12345) & 0x3FFFFFFF
        @state / 1073741824.0
      end
    end
  end
end
# ===== END portable_ai/search.rb =====

# ===== BEGIN adapters/reborn/Portable_AI_Adapter.rb =====
# Portable AI adapter for Reborn Yang (Reborn E19.16, v16-era fork, modern Ruby).
#
# Concatenated after portable_ai/model.rb, effects.rb, matrix.rb, core.rb and
# search.rb by
# tools/build_portable_ai.py --target reborn, installed as Scripts/Portable_AI.rb and
# listed in Data/!script_order.csv after AI_Harness, before Main.
#
# Hook point: PokeBattle_AI#chooseAction is Reborn's single registration site — its
# per-battler loop starts with `next if @battle.choices[i][0] != 0`, so any battler the
# portable side registers first is skipped by the host AI with no further patching.
#
# BENCHMARK POLICY — no silent fallback. The Realidea adapter falls back to the stock
# selector on error, which is safe there because stock IS the baseline. Here fallback
# would mean letting Reborn's own AI decide, silently contaminating any head-to-head
# strength result. Errors are appended to Data/portable_ai_error.txt and re-raised.
#
# BASE SCORE — neutral 100, not the host scorer. In Realidea the portable AI consumes
# stock v16 pbGetMoveScore as its base evidence. Reborn has no stock scorer left; its
# replacement is the 17k-line opinionated AI this benchmark measures against, so using
# it as base evidence is exactly the contamination the policy above forbids. The known
# consequence: the Reborn build leans entirely on the core's own evidence terms, and
# Tier-1/Tier-2 validation (not construction) decides whether that is good enough.
#
# Engine primitives intentionally borrowed from Reborn (adapter-legitimate, per
# AI-PORTABILITY.md §4: damage/type/legality belong to the engine):
#   - PokeBattle_AI#pbRoughDamage        damage estimate (needs @mondata staged)
#   - PokeBattle_AI#pbTypeModNoMessages  type verdict, neutral = 4, -1 = absorb ability
#   - pbCanChooseMove?/pbCanSwitch?/pbRegister* legality and registration
# While estimating, $game_switches[3000] (Intense) is masked off and swappredicted is
# neutralized so Intense-mode cheats cannot leak into the portable side's snapshot.

module PortableAIReborn
  ENABLE_FILE = "Data/portable_ai.txt"

  # Essentials function code -> [effect kind, affected stat]. This is the whole of
  # 0.5.0's move-side-effect knowledge: every burn/paralysis/poison/freeze/flinch
  # secondary, every target stat drop and every self-raise on a damaging move is
  # identified by the code the engine already stores, so ~80 hand-tagged move names
  # are replaced by one table that covers moves nobody has listed. Reborn and Realidea
  # share the code family (both are Essentials 16-era), and the codes were read off
  # Reborn's own dispatch (PokeBattle_AI_2.rb:3442-5510) rather than guessed.
  MOVE_EFFECT_CODES = {
    0x05 => ["poison", nil], 0x06 => ["poison", nil], 0x174 => ["poison", nil],
    0x225 => ["poison", nil], 0x256 => ["poison", nil],
    0x07 => ["paralyze", nil], 0x08 => ["paralyze", nil], 0x09 => ["paralyze", nil],
    0x127 => ["paralyze", nil],
    0x0A => ["burn", nil], 0x0B => ["burn", nil], 0x128 => ["burn", nil],
    0x207 => ["burn", nil], 0x230 => ["burn", nil],
    0x0C => ["freeze", nil], 0x0D => ["freeze", nil], 0x0E => ["freeze", nil],
    0x129 => ["freeze", nil],
    0x0F => ["flinch", nil], 0x10 => ["flinch", nil], 0x11 => ["flinch", nil],
    0x229 => ["flinch", nil], 0x236 => ["flinch", nil],
    # Target stat drops. The stat is the one Reborn passes to oppstatdrop; where a
    # move drops two, the one the core can actually price is named.
    0x42 => ["drop", "atk"], 0x226 => ["drop", "atk"],
    0x43 => ["drop", "def"], 0x4a => ["drop", "def"], 0x4c => ["drop", "def"],
    0x180 => ["drop", "def"],
    0x44 => ["drop", "speed"], 0x4d => ["drop", "speed"], 0x17c => ["drop", "speed"],
    0x13f => ["drop", "speed"],
    0x45 => ["drop", "spa"], 0x13b => ["drop", "spa"],
    0x46 => ["drop", "spd"],
    0x47 => ["drop", "acc"],
    # Self-raise on a damaging move (Power-Up Punch, Flame Charge, Charge Beam).
    0x1d => ["self_raise", "def"], 0x1e => ["self_raise", "def"],
    0x1f => ["self_raise", "speed"], 0x20 => ["self_raise", "spa"],
    0x21 => ["self_raise", "spd"], 0x01C => ["self_raise", "atk"]
  }

  # Recoil fraction of the damage dealt, from Reborn's own table (:4533) plus the
  # three moves that hard-code 1/3.
  MOVE_RECOIL_CODES = {
    0xfa => 0.25, 0xfb => 0.3333, 0xfc => 0.5,
    0xfd => 0.3333, 0xfe => 0.3333, 0x235 => 0.3333
  }

  # Fraction of the damage dealt that is restored to the user.
  MOVE_DRAIN_CODES = { 0xDD => 0.5, 0xDE => 0.5, 0x139 => 0.75 }

  MULTI_HIT_CODES = [0xBD, 0xBE, 0xBF, 0xC0, 0x17e, 0x202, 0x231, 0x251]

  # Reborn field ids for the four terrains the modern metagame actually uses
  # (PBStuff.rb:570-606). Everything else is a Reborn-specific field the portable core
  # has no rule for, and is exported as nil rather than as a name it cannot read.
  TERRAIN_FIELDS = { 1 => "electric", 2 => "grassy", 3 => "misty", 37 => "psychic" }
  ERROR_FILE  = "Data/portable_ai_error.txt"
  ENABLE_WILD = false

  NEUTRAL_BASE_SCORE = 100.0
  TYPEMOD_NEUTRAL    = 4.0

  class BattleRNG
    def initialize(battle)
      @battle = battle
    end

    def rand(limit)
      @battle.pbAIRandom(limit)
    end
  end

  def self.requested?
    return true if defined?($PORTABLE_AI_ENABLED) && $PORTABLE_AI_ENABLED
    File.exist?(ENABLE_FILE)
  rescue
    false
  end

  # Shadow mode: build the snapshot and run the planner for the marked side, record
  # what it would have done, and register nothing — the host AI still chooses. Both
  # AIs therefore answer from the identical position on every turn, which is the only
  # way to compare the two policies at scale; two live arms diverge after ~1 turn and
  # everything after that is a different battle.
  #
  # Sound only because the planner is side-effect free at BESTSKILL: it draws from
  # BattleRNG solely for difficulty noise (off when deterministic), and
  # with_neutral_estimation restores every host field it stages. The one thing shadow
  # deliberately does NOT do is apply_memory — portable memory would otherwise record
  # moves the portable AI never made — so a shadow decision does not carry the
  # repeated-setup penalty the same position would attract in a live portable run.
  def self.shadow?
    defined?($PORTABLE_AI_SHADOW) && $PORTABLE_AI_SHADOW ? true : false
  end

  def self.active?
    requested? || shadow?
  end

  # Which battlers the portable AI drives. Default: the opposing (odd) side.
  #
  # The gauntlet needs a stronger identity: Reborn's test environment runs both sides
  # through the SAME odd-side AI path by physically swapping the battle's halves
  # (PokeBattle_TestEnvironment#switchTrainers exchanges @player/@opponent, parties,
  # battlers, choices and aimondata between the two pbChooseEnemyCommand calls of each
  # turn). Index parity therefore points at BOTH teams, one per call. When
  # $PORTABLE_AI_TRAINER is set, the portable side is whichever team that trainer
  # object currently owns — an identity the swap moves around consistently.
  def self.enabled_for?(battle, index)
    return false if !active?
    return false if !battle.pbIsOpposing?(index)
    return false if !ENABLE_WILD && !battle.opponent
    marked = $PORTABLE_AI_TRAINER
    if marked
      owner = battle.pbGetOwner(index) rescue nil
      return owner.equal?(marked)
    end
    true
  rescue
    false
  end

  # Run-level config overrides, set from Data/ai_harness.txt by the gauntlet. Keys not
  # named here keep their skill-derived or Model::DEFAULT_CONFIG value.
  #
  # This exists so one installed build can play both sides of a policy A/B — the
  # alternative is rebuilding and reinstalling between arms, which makes the two arms
  # different artifacts and invites exactly the mix-up the study cannot detect after
  # the fact. Every gauntlet record carries the overrides it ran under.
  def self.config_overrides
    return {} if !defined?($PORTABLE_AI_CONFIG) || !$PORTABLE_AI_CONFIG.is_a?(Hash)
    $PORTABLE_AI_CONFIG
  end

  # Whether one core config key is on for this run, for the handful of rules that live
  # on THIS side of the boundary and so never see the config hash the core is handed.
  # Same precedence as Model.config: a run-level override wins, otherwise the default.
  # Only for adapter-owned rules -- anything the core can decide belongs in the core.
  def self.rule_enabled?(key)
    overrides = config_overrides
    return overrides[key] ? true : false if overrides.key?(key)
    PortableAI::Model::DEFAULT_CONFIG[key] ? true : false
  rescue
    true
  end

  def self.config_for(skill)
    base =
      if skill >= PokeBattle_AI::BESTSKILL
        {
          "deterministic" => true, "noise" => 0, "switching" => true,
          "memory" => true, "coordination" => true, "knowledge" => "fair"
        }
      elsif skill >= PokeBattle_AI::HIGHSKILL
        {
          "deterministic" => false, "noise" => 5, "switching" => true,
          "memory" => true, "coordination" => true, "knowledge" => "fair"
        }
      elsif skill >= PokeBattle_AI::MEDIUMSKILL
        {
          "deterministic" => false, "noise" => 12, "switching" => true,
          "memory" => false, "coordination" => true, "knowledge" => "fair"
        }
      else
        {
          "deterministic" => false, "noise" => 25, "switching" => false,
          "memory" => false, "coordination" => false, "knowledge" => "fair"
        }
      end
    base.merge(config_overrides)
  end

  def self.skill_for(ai, index)
    data = ai.aimondata[index]
    data ? data.skill.to_i : PokeBattle_AI::BESTSKILL
  rescue
    PokeBattle_AI::BESTSKILL
  end

  # Entry point, called from the chooseAction hook before the host AI registers
  # anything. Registers portable choices for every opposing battler that still needs
  # one; the host loop then skips those indices.
  def self.register_side(ai)
    return if !active?
    battle = ai.battle
    return if !battle || (!ENABLE_WILD && !battle.opponent)
    indices = pending_indices(battle)
    return if indices.empty?
    begin
      choose_all(ai, battle, indices)
    rescue Exception => error
      log_error(error)
      raise
    end
  end

  def self.pending_indices(battle)
    out = []
    [1, 3].each do |index|
      next if index == 3 && !battle.doublebattle
      battler = battle.battlers[index]
      next if !battler || battler.isFainted?
      next if !enabled_for?(battle, index)
      next if !battle.pbCanShowCommands?(index)
      next if battle.choices[index][0] != 0
      # Nothing to decide (no choosable move, no legal switch): leave the battler to
      # the host loop's pbAutoChooseMove path — that is engine mechanics (Struggle,
      # locked moves), not an AI decision.
      next if !any_choosable_move?(battle, index) && !has_legal_switch?(battle, index)
      out << index
    end
    out
  end

  def self.choose_all(ai, battle, indices)
    snapshot, skill = build_snapshot(ai, battle, indices)
    config = config_for(skill)
    plan = PortableAI.plan(snapshot, config, BattleRNG.new(battle))
    battle.instance_variable_set(:@portable_ai_last_plan, plan)
    observing = shadow?

    indices.each do |index|
      action = nil
      (plan["actions"] || []).each do |candidate|
        if candidate["actor_index"] == index
          action = candidate
          break
        end
      end
      raise "portable plan has no action for battler #{index}" if !action
      if !observing
        if !apply_action(battle, index, action)
          raise "portable action failed to register for battler #{index}: " +
                "#{action['type']} slot=#{action['slot']} target=#{action['target'].inspect}"
        end
        apply_memory(battle, index, action) if config["memory"]
      end
      trace = battle.instance_variable_get(
        observing ? :@portable_ai_shadow_trace : :@portable_ai_decision_trace)
      if trace
        entry = {
          "turn" => battle.turncount,
          "actor" => index,
          "type" => action["type"],
          "slot" => action["slot"],
          "move_id" => action["move_id"],
          "target" => action["target"],
          "score" => action["score"]
        }
        # Under trace, keep why as well as what. Storing only the chosen action means a
        # later diagnosis has to infer the gate reason from board state, which is what
        # produced the Chansey/Gengar misread; the planner already computed the reasons,
        # so this costs a copy. Top candidates only, to bound the file size.
        entry["candidates"] = candidate_trace(plan, index) if $AI_GAUNTLET_TRACE
        entry["view"] = view_trace(snapshot, index) if $AI_GAUNTLET_TRACE
        if $AI_GAUNTLET_TRACE
          entry["joint_adjustment"] = plan.dig("diagnostics", "joint_adjustment")
          entry["damage_by_target"] = action["damage_by_target"] if action["damage_by_target"]
          entry["friendly_fire_pct"] = action["friendly_fire_pct"] if action["friendly_fire_pct"]
          entry["partner_protect_blocks"] = action["partner_protect_blocks"] if !action["partner_protect_blocks"].nil?
        end
        trace << entry
      end
    end
  end

  TRACE_CANDIDATE_LIMIT = 5
  # view_trace reports the race as computed, independently of whether the run
  # has the rules that consume it switched on.
  DEFAULT_RACE_CONFIG = { "damage_race" => true }

  # What the actor believed about the board when it chose: its own HP and speed order,
  # the incoming-damage estimate the heal and priority gates read, and each target's
  # HP. Joined with debuglog.txt this shows where the estimate and the foe's actual
  # choice part ways.
  def self.view_trace(snapshot, index)
    actor = (snapshot["actors"] || []).find { |a| a["index"] == index }
    return {} if !actor
    out = {
      "hp_pct" => actor["hp_pct"],
      "speed" => actor["speed"],
      "faster" => actor["faster"],
      "incoming_damage_pct" => actor["incoming_damage_pct"],
      "certain_incoming_damage_pct" => actor["certain_incoming_damage_pct"],
      "incoming_by_move" => actor["incoming_by_move"],
      "threatened_lethal" => actor["threatened_lethal"],
      "targets" => (snapshot["targets"] || []).map do |t|
        { "index" => t["index"], "hp_pct" => t["hp_pct"], "speed" => t["speed"] }
      end
    }
    # 0.6.0: the hits-to-KO both ways, per target. The helper is pure and reads only
    # the snapshot, so the adapter can call it on the snapshot it just built. The
    # counts live HERE and not in a reason pair -- reasons stay [name, number].
    race = {}
    (snapshot["targets"] || []).each do |t|
      race[t["index"].to_s] =
        PortableAI.damage_race(snapshot, actor, t, DEFAULT_RACE_CONFIG)
    end
    out["race"] = race
    out
  rescue
    {}
  end

  # The top scored candidates for one battler, each with the reason list that built its
  # score, from plan["diagnostics"]["rankings"] (already sorted best-first).
  def self.candidate_trace(plan, index)
    diagnostics = plan["diagnostics"] || {}
    rankings = diagnostics["rankings"] || []
    actors = (plan["actions"] || []).map { |a| a["actor_index"] }
    slot = actors.index(index)
    return [] if slot.nil?
    ranked = rankings[slot] || []
    out = []
    ranked.each do |candidate|
      break if out.length >= TRACE_CANDIDATE_LIMIT
      out << {
        "type" => candidate["type"],
        "slot" => candidate["slot"],
        "move_id" => candidate["move_id"],
        "target" => candidate["target"],
        "score" => candidate["score"],
        "reasons" => candidate["reasons"]
      }
    end
    out
  rescue
    []
  end

  def self.build_snapshot(ai, battle, indices)
    foe_indices = [0]
    foe_indices << 2 if battle.doublebattle
    foe_indices = foe_indices.select do |i|
      battler = battle.battlers[i]
      battler && !battler.isFainted?
    end

    skills = indices.map { |i| skill_for(ai, i) }
    skill = skills.min || PokeBattle_AI::BESTSKILL

    snapshot = nil
    with_neutral_estimation(ai, indices[0]) do
      targets = foe_indices.map { |i| battler_view(ai, battle, battle.battlers[i]) }
      actors = indices.map { |i| build_actor(ai, battle, i, foe_indices, skill) }
      memory = battle.instance_variable_get(:@portable_ai_memory) || {}
      snapshot = {
        "format" => battle.doublebattle ? "double" : "single",
        "turn" => battle.turncount,
        "weather" => weather_name(battle),
        # Only the four modern terrains are named; every other Reborn field is a
        # mechanic the portable core has no rule for and is better reported as absent
        # than as a word it will not match.
        "terrain" => TERRAIN_FIELDS[(battle.FE rescue nil)],
        "trick_room_active" => ((battle.trickroom.to_i != 0) rescue false),
        "tailwind_active" =>
          (safe_side_effect(battle.battlers[indices[0]].pbOwnSide, :Tailwind, 0).to_i > 0 rescue false),
        "actors" => actors,
        "targets" => targets,
        "memory" => memory
      }
    end
    [snapshot, skill]
  end

  # pbRoughDamage reads @mondata.skill and @swappredicted, and both it and Reborn's
  # scoring branch on $game_switches[3000] (Intense player-choice reads, 100% Sucker
  # Punch prediction, mega reads). Stage a clean context for the duration of snapshot
  # building so the portable side estimates with fair information only.
  def self.with_neutral_estimation(ai, actor_index)
    old_mondata = ai.mondata
    old_swap    = ai.swappredicted
    old_intense = ($game_switches ? $game_switches[3000] : nil)
    ai.mondata = ai.aimondata[actor_index] || old_mondata
    raise "no aimondata for battler #{actor_index}" if !ai.mondata
    ai.swappredicted = [-1, -1]
    $game_switches[3000] = false if $game_switches
    yield
  ensure
    ai.mondata = old_mondata
    ai.swappredicted = old_swap
    $game_switches[3000] = old_intense if $game_switches && !old_intense.nil?
  end

  def self.battler_view(ai, battle, battler)
    physical, special = attack_bias(ai, battler)
    partner = (battler.pbPartner rescue nil)
    {
      "index" => battler.index,
      "species" => battler.species,
      "hp_pct" => percent(battler.hp, battler.totalhp),
      "status" => battler.status,
      "types" => [battler.type1, battler.type2],
      "speed" => (battler.pbSpeed rescue battler.speed),
      # Switch scoring needs the foe's boost level and, unlike a move action, has no
      # scoring target to read it from.
      "positive_stages" => positive_stages(battler),
      # 0.5.0 facts. Plain uppercase names and booleans only: the core matches them
      # against its own tables and never sees a PBAbilities/PBItems constant.
      "ability" => ability_key(battler),
      "item" => item_key(battler),
      "full_hp" => (battler.hp >= battler.totalhp),
      "physical_attacker" => physical,
      "special_attacker" => special,
      "substitute" => (safe_effect(battler, :Substitute, 0).to_i > 0),
      "partner_ability" => (partner && !partner.isFainted? ? ability_key(partner) : nil),
      "choice_locked_move" => choice_locked_move(battler),
      # The doubles response model needs to distinguish an all-attacks set from a
      # support set. Use the visible moveset as a neutral prior; target choice is
      # still resolved in the portable core.
      "attack_probability" => attack_move_fraction(battler),
      "utility_response" =>
        (battle.doublebattle &&
         PortableAI::Model.truthy((defined?($PORTABLE_AI_CONFIG) && $PORTABLE_AI_CONFIG ?
           $PORTABLE_AI_CONFIG : {})["opponent_utility"]) ?
           utility_response(battle, battler) : nil)
    }
  end

  UTILITY_RESPONSE_RANK = {
    "field_speed" => 80, "redirect" => 70, "team_protect" => 60,
    "protect" => 50, "status" => 40, "disrupt" => 35,
    "screen" => 30, "setup" => 25, "partner_support" => 20
  }

  # Pick one representative for the non-damaging response branch. The probability
  # of taking that branch still comes from the damaging/status split of the whole
  # visible moveset; this chooses what the support half of the set is trying to do.
  def self.utility_response(battle, battler)
    locked = safe_effect(battler, :ChoiceBand, -1).to_i
    target = (battler.pbOppositeOpposing rescue nil)
    best = nil
    battler.moves.each do |move|
      next if !move || move.id == 0 || move.basedamage > 0
      next if locked >= 0 && move.id != locked
      move_id = move_key(move.id)
      tags = PortableAI::Effects.describe(move_id, [])
      kind = UTILITY_RESPONSE_RANK.keys.find { |tag| tags.include?(tag) }
      next if !kind
      next if kind == "field_speed" &&
              ((move_id == "TAILWIND" &&
                safe_side_effect(battler.pbOwnSide, :Tailwind, 0).to_i > 0) ||
               (move_id == "TRICKROOM" && (battle.trickroom.to_i != 0 rescue false)))
      candidate = {
        "kind" => kind, "move_id" => move_id,
        "priority" => effective_priority(battle, move, battler, target),
        "value" => (move_id == "TRICKROOM" ? 156 :
                    move_id == "TAILWIND" ? 104 : nil)
      }
      rank = UTILITY_RESPONSE_RANK[kind]
      best = [rank, candidate] if !best || rank > best[0]
    end
    best ? best[1] : nil
  rescue
    nil
  end

  def self.attack_move_fraction(battler)
    locked = safe_effect(battler, :ChoiceBand, -1).to_i
    moves = battler.moves.select do |move|
      move && move.id != 0 && (locked < 0 || move.id == locked)
    end
    return 0.0 if moves.empty?
    damaging = moves.count { |move| move.basedamage > 0 }
    damaging.to_f / moves.length
  rescue
    1.0
  end

  # The move a Choice item has locked this battler into, once it has actually moved.
  # PBEffects::ChoiceBand holds the move id and is -1 when free (:6207).
  def self.choice_locked_move(battler)
    id = safe_effect(battler, :ChoiceBand, -1).to_i
    return nil if id < 0
    move_key(id)
  rescue
    nil
  end

  def self.build_actor(ai, battle, index, foe_indices, skill)
    battler = battle.battlers[index]
    actions = []
    battler.moves.each_with_index do |move, slot|
      next if !move || move.id == 0
      next if !battle.pbCanChooseMove?(index, slot, false)
      move_actions(ai, battle, battler, move, slot, foe_indices, skill).each do |action|
        actions << action
      end
    end
    switch_actions(ai, battle, battler, foe_indices).each { |action| actions << action }

    damaging = actions.select { |action| action["type"] == "move" && action["damaging"] }
    best_damage = 0
    damaging.each do |action|
      damage = PortableAI::Model.number(action["expected_damage_pct"], 0)
      best_damage = damage if damage > best_damage
    end
    no_effective = !damaging.empty? && damaging.all? do |action|
      PortableAI::Model.truthy(action["immune"]) ||
        PortableAI::Model.number(action["effectiveness"], 1) <= 0
    end
    negative_stages = 0
    battler.stages.each { |stage| negative_stages += stage if stage && stage < 0 }
    # 0.6.2: the durable record of "I have already set up", which the memory counter is
    # not -- apply_memory zeroes it on any non-setup action.
    positive_stages_total = positive_stages(battler)

    incoming_map = incoming_damage_by_move(ai, battle, battler, foe_indices)
    incoming = incoming_map.values.max || 0.0
    certain = certain_incoming_damage(ai, battle, battler, foe_indices, incoming_map)
    toxic_stage = safe_effect(battler, :Toxic, 0).to_i
    residual = 0.0
    residual += (toxic_stage + 1) * 100.0 / 16.0 if toxic_stage > 0
    residual += 100.0 / 8.0 if safe_effect(battler, :LeechSeed, -1).to_i >= 0
    speed = battler_speed(battler)
    partner = (battler.pbPartner rescue nil)
    partner_alive = partner && !partner.isFainted? ? true : false
    {
      "index" => index,
      "species" => battler.species,
      "hp_pct" => percent(battler.hp, battler.totalhp),
      "status" => battler.status,
      "speed" => speed,
      "faster" => faster_than_foes?(battle, speed, foe_indices),
      "stages" => battler.stages.clone,
      "negative_stage_total" => negative_stages,
      "positive_stage_total" => positive_stages_total,
      "incoming_damage_pct" => incoming,
      "certain_incoming_damage_pct" => certain,
      "incoming_by_move" => incoming_map,
      # 0.6.0: the per-foe view of the same threat, which is what a hits-to-KO
      # question has to read. Absent on any adapter that does not build it, and the
      # core's damage_race then returns nil and every consumer goes inert.
      "threats_by_foe" => threats_by_foe(ai, battle, battler, foe_indices, incoming_map),
      "threatened_lethal" => incoming >= percent(battler.hp, battler.totalhp),
      "no_effective_move" => no_effective,
      "best_damage_pct" => best_damage,
      "yawned" => safe_effect(battler, :Yawn, 0).to_i > 0,
      "residual_damage_pct" => residual,
      "trapped" => !has_legal_switch?(battle, index),
      # 0.5.0 facts about the actor itself.
      "ability" => ability_key(battler),
      "item" => item_key(battler),
      # Mold Breaker turns the target's Sturdy off, so the kill call stands.
      "mold_breaker" => mold_breaker?(battler),
      # Fake Out and First Impression are worth +115 on turn 0 and nothing after.
      "turncount" => (battler.turncount.to_i rescue 0),
      "slower_bench_count" => slower_bench_count(battle, battler, foe_indices),
      "partner_alive" => partner_alive,
      "partner_index" => (partner_alive ? partner.index : nil),
      "partner_ability" => (partner_alive ? ability_key(partner) : nil),
      "partner_hp_pct" => (partner_alive ? percent(partner.hp, partner.totalhp) : nil),
      "partner_airborne" =>
        (partner_alive ? (battler_has_type?(partner, :FLYING) ||
                          (ability_key(partner) == "LEVITATE")) : false),
      "actions" => actions
    }
  end

  def self.mold_breaker?(battler)
    name = ability_key(battler)
    name == "MOLDBREAKER" || name == "TERAVOLT" || name == "TURBOBLAZE"
  end

  # How many benched Pokemon are slower than every current foe. Trick Room is a
  # whole-team investment, so it is only worth a turn when the team behind the actor
  # is slow too.
  def self.slower_bench_count(battle, battler, foe_indices)
    fastest = 0
    foe_indices.each do |foe_index|
      speed = battler_speed(battle.battlers[foe_index])
      fastest = speed if speed && speed > fastest
    end
    return 0 if fastest <= 0
    count = 0
    battle.pbParty(battler.index).each_with_index do |pokemon, slot|
      next if !pokemon || pokemon.hp <= 0 || pokemon.isEgg?
      next if pokemon.equal?(battler.pokemon)
      speed = (pokemon.speed rescue nil)
      count += 1 if speed && speed < fastest
    end
    count
  rescue
    0
  end

  def self.move_actions(ai, battle, battler, move, slot, foe_indices, skill)
    target_const = (battler.pbTarget(move) rescue move.target)
    spread = (target_const == PBTargets::AllOpposing ||
              target_const == PBTargets::AllNonUsers)
    move_id = move_key(move.id)

    if spread
      scored = foe_indices.map do |target_index|
        target = battle.battlers[target_index]
        action_for_target(ai, battle, battler, move, slot, move_id, target, nil, skill)
      end
      return [] if scored.empty?
      action = scored[0]
      # Preserve each foe's damage and immunity before aggregating the legacy view.
      action["damage_by_target"] = {}
      scored.each_with_index do |item, n|
        action["damage_by_target"][foe_indices[n].to_s] = {
          "damage_pct" => item["immune"] ? 0.0 : item["expected_damage_pct"],
          "accuracy" => item["accuracy"]
        }
      end
      action["base_score"] = average(scored.map { |item| item["base_score"] })
      action["expected_damage_pct"] = scored.inject(0) do |sum, item|
        sum + PortableAI::Model.number(item["expected_damage_pct"], 0)
      end
      action["target"] = nil
      action["spread"] = true
      # Engine truth for partner exposure: AllNonUsers hits the partner, AllOpposing
      # does not. (The Realidea adapter used the effects-table tag; the dynamic
      # pbTarget answer is strictly better and free here.)
      if target_const == PBTargets::AllNonUsers
        partner = battler.pbPartner
        if partner && !partner.isFainted?
          action["friendly_fire_pct"] = rough_damage_pct(ai, move, battler, partner)
          action["partner_hp_pct"] = percent(partner.hp, partner.totalhp)
          action["partner_protect_blocks"] = (move.canProtectAgainst? rescue false) &&
            !(battler.hasWorkingAbility(:UNSEENFIST) && (move.isContactMove? rescue false)) &&
            !safe_effect(partner, :ProtectNegation, false)
        end
      end
      return [action]
    end

    targets = legal_targets(battle, battler, target_const, foe_indices)
    if targets.empty?
      opponent = foe_indices.empty? ? nil : battle.battlers[foe_indices[0]]
      return [action_for_target(ai, battle, battler, move, slot, move_id, opponent, nil, skill)]
    end

    targets.map do |target_index|
      target = battle.battlers[target_index]
      registration_target = explicit_target?(target_const) ? target_index : nil
      action = action_for_target(
        ai, battle, battler, move, slot, move_id, target, registration_target, skill
      )
      partner = battler.pbPartner
      if partner && target_index == partner.index
        action["friendly_target"] = true
        if move.basedamage > 0
          action["friendly_fire_pct"] = action["expected_damage_pct"]
          action["partner_hp_pct"] = percent(partner.hp, partner.totalhp)
        end
      end
      action
    end
  end

  def self.action_for_target(ai, battle, battler, move, slot, move_id, target, register_target, skill)
    scoring_target = target
    if !scoring_target || scoring_target.index == battler.index
      scoring_target = battler.pbOppositeOpposing
    end
    effectiveness = type_effectiveness(ai, move, battler, scoring_target)
    damaging = move.basedamage > 0
    tags = PortableAI::Effects.describe(move_id, [])
    blocked = !damaging && status_blocked?(ai, move, tags, battler, scoring_target)
    kind, stat, chance = move_effect(ai, move, battler, scoring_target)
    physical, special = scoring_target ? attack_bias(ai, scoring_target) : [false, false]
    code = (move.function rescue nil)
    {
      "type" => "move",
      "actor_index" => battler.index,
      "slot" => slot,
      "move_id" => move_id,
      "numeric_move_id" => move.id,
      "target" => register_target,
      "base_score" => NEUTRAL_BASE_SCORE,
      "damaging" => damaging,
      "power" => move.basedamage,
      "priority" => effective_priority(battle, move, battler, scoring_target),
      # 0.5.0 move facts, all from the engine.
      "move_type" => type_key((move.pbType(battler) rescue move.type)),
      "category" => (damaging ? ((move.pbIsPhysical?(move.pbType(battler)) rescue false) ?
                                 "physical" : "special") : "status"),
      "contact" => ((move.isContactMove? rescue false) ? true : false),
      "effect_kind" => kind,
      "effect_stat" => stat,
      "effect_chance" => chance,
      "multi_hit" => multi_hit?(move),
      "recoil_fraction" => MOVE_RECOIL_CODES[code],
      "drain_fraction" => MOVE_DRAIN_CODES[code],
      "mold_breaker" => mold_breaker?(battler),
      # Mirrors of the target view, so a spread action (which has no single target)
      # and a unit test both reach the same facts.
      "target_species" => (scoring_target ? scoring_target.species : nil),
      "target_ability" => (scoring_target ? ability_key(scoring_target) : nil),
      "target_item" => (scoring_target ? item_key(scoring_target) : nil),
      "target_full_hp" => (scoring_target ? (scoring_target.hp >= scoring_target.totalhp) : false),
      "target_speed" => (scoring_target ? battler_speed(scoring_target) : nil),
      "target_physical_attacker" => physical,
      "target_special_attacker" => special,
      "target_substitute" =>
        (scoring_target ? (safe_effect(scoring_target, :Substitute, 0).to_i > 0) : false),
      "effectiveness" => effectiveness,
      "immune" => (damaging && effectiveness <= 0) || blocked,
      "expected_damage_pct" => rough_damage_pct(ai, move, battler, scoring_target),
      "accuracy" => rough_accuracy(ai, move, battler, scoring_target),
      "opponent_protect_blocks" =>
        ((move.canProtectAgainst? rescue true) &&
         !(battler.hasWorkingAbility(:UNSEENFIST) && (move.isContactMove? rescue false))),
      "target_hp_pct" => (scoring_target ? percent(scoring_target.hp, scoring_target.totalhp) : nil),
      "tags" => tags,
      "spread" => false,
      "existing_layers" => existing_layers(battler, move_id),
      "max_layers" => max_layers(move_id),
      "own_hazard_layers" => own_hazard_layers(battler),
      "foe_hazard_layers" => opposing_hazard_layers(battler),
      "target_positive_stages" => positive_stages(scoring_target),
      "effect_active" => effect_active?(battler, move_id),
      "failed_last_turn" => failed_last_turn?(battle, battler, move_id, scoring_target),
      "foe_reserves" => reserve_count(battle, scoring_target ? scoring_target.index : battler.index ^ 1),
      "hazard_targets" => hazard_target_count(battle, move_id, battler.index),
      "own_reserves" => reserve_count(battle, battler.index)
    }
  end

  # Priority as the engine's own AI helper reads it: Prankster, Gale Wings and Triage
  # raise it, and Fake Out/First Impression lose it after turn 0 (PokeBattle_Move.rb
  # :2586). Psychic Terrain stops a priority move reaching a grounded target
  # altogether, which the probe confirmed stock Reborn already knows (Aqua Jet scored
  # 0 on field 37 against 242 on an open field), so a priority move that cannot land
  # is reported as having no priority rather than as having some.
  def self.effective_priority(battle, move, battler, target)
    base = move.priority
    if base > 0 && TERRAIN_FIELDS[(battle.FE rescue nil)] == "psychic" && target
      grounded = !(battler_has_type?(target, :FLYING) || ability_key(target) == "LEVITATE")
      return 0 if grounded
    end
    positive = (move.pbIsPriorityMoveAI(battler) rescue nil)
    return 0 if positive == false && base > 0
    return 1 if positive == true && base <= 0
    base
  rescue
    move.priority
  end

  def self.legal_targets(battle, battler, target_const, foe_indices)
    case target_const
    when PBTargets::SingleNonUser
      out = foe_indices.clone
      partner = battler.pbPartner
      out << partner.index if partner && !partner.isFainted?
      out
    when PBTargets::SingleOpposing
      foe_indices.clone
    when PBTargets::OppositeOpposing
      target = battler.pbOppositeOpposing
      target = target.pbPartner if target && target.isFainted?
      target && !target.isFainted? ? [target.index] : []
    when PBTargets::RandomOpposing
      foe_indices.clone
    when PBTargets::User
      [battler.index]
    when PBTargets::UserOrPartner
      out = [battler.index]
      partner = battler.pbPartner
      out << partner.index if partner && !partner.isFainted?
      out
    when PBTargets::Partner
      partner = battler.pbPartner
      partner && !partner.isFainted? ? [partner.index] : []
    else
      []
    end
  end

  def self.explicit_target?(target_const)
    target_const == PBTargets::SingleNonUser ||
      target_const == PBTargets::SingleOpposing ||
      target_const == PBTargets::UserOrPartner ||
      target_const == PBTargets::Partner
  end

  def self.switch_actions(ai, battle, battler, foe_indices)
    party = battle.pbParty(battler.index)
    forced = safe_effect(battler, :PerishSong, 0) == 1
    actions = []
    party.each_with_index do |pokemon, slot|
      next if !pokemon || !battle.pbCanSwitch?(battler.index, slot, false)
      hp_pct = percent(pokemon.hp, pokemon.totalhp)
      matchup = switch_matchup(pokemon, battle, foe_indices)
      hazard = entry_hazard_pct(pokemon, battler)
      next if hazard >= hp_pct
      action = {
        "type" => "switch",
        "actor_index" => battler.index,
        "slot" => slot,
        "base_score" => 20 + hp_pct * 0.35 - hazard,
        "matchup_score" => matchup,
        "incoming_risk" => switch_incoming_risk(pokemon, battle, foe_indices),
        "forced" => forced,
        "safe_entry" => hp_pct > hazard + 20,
        "species" => pokemon.species,
        # 0.5.0 entry facts. candidate_hp_pct and entry_damage_pct restate what is
        # already folded into base_score so the core can ask "is this Pokemon alive at
        # the end of the turn it comes in on" rather than "did it clear the hazards".
        "candidate_hp_pct" => hp_pct,
        "entry_damage_pct" => hazard,
        "ability" => ability_key(pokemon),
        "item" => item_key(pokemon)
      }
      real = switch_incoming_damage(ai, battle, pokemon, foe_indices)
      action["incoming_damage_pct"] = real if !real.nil?
      # 0.6.0: the offensive half of the same estimate, so the core can run the race
      # for a candidate that has not come in yet. Same fake battler, same rescue-to-nil
      # contract as incoming_damage_pct.
      out = switch_outgoing_damage(ai, battle, pokemon, foe_indices)
      action["outgoing_damage_pct"] = out if !out.nil?
      fast = switch_candidate_faster(battle, pokemon, foe_indices)
      action["faster"] = fast if !fast.nil?
      actions << action
    end
    actions
  end

  # What the candidate actually eats on the turn it comes in, as a real damage estimate
  # against a fake battler rather than a type-chart proxy -- and with the candidate's
  # own Intimidate applied to the foes first, which is the only way an entry ability
  # can show up in the number at all. Reborn does exactly this, including the temporary
  # stage mutation and its restore (:11584-11617); pbCanReduceStatStage? is what makes
  # Clear Body, White Smoke, Full Metal Body, Hyper Cutter and Clear Amulet exempt, and
  # the probe confirmed the exemption is complete.
  #
  # nil when the engine cannot build a fake battler, which leaves the core on the type
  # proxy it used through 0.4.1.
  def self.switch_incoming_damage(ai, battle, pokemon, foe_indices)
    fake = (ai.pbMakeFakeBattler(pokemon) rescue nil)
    return nil if !fake
    intimidate = (ability_key(pokemon) == "INTIMIDATE")
    saved = {}
    worst = 0.0
    begin
      if intimidate
        foe_indices.each do |foe_index|
          foe = battle.battlers[foe_index]
          next if !foe || foe.isFainted?
          next if !(foe.pbCanReduceStatStage?(PBStats::ATTACK) rescue false)
          next if (foe.item == PBItems::WHITEHERB rescue false)
          ability = ability_key(foe)
          next if ability == "CONTRARY" || ability == "MIRRORARMOR" || ability == "DEFIANT"
          saved[foe_index] = foe.stages[PBStats::ATTACK]
          foe.stages[PBStats::ATTACK] -= 1
        end
      end
      foe_indices.each do |foe_index|
        foe = battle.battlers[foe_index]
        next if !foe || foe.isFainted?
        foe.moves.each do |known|
          next if !known || known.id == 0
          damage = rough_damage_pct(ai, known, foe, fake)
          worst = damage if damage > worst
        end
      end
    ensure
      saved.each do |foe_index, value|
        battle.battlers[foe_index].stages[PBStats::ATTACK] = value
      end
    end
    worst
  rescue
    nil
  end

  # The mirror of switch_incoming_damage: the best real hit this candidate has into
  # any current foe, so the core can ask how many turns it needs rather than only how
  # many it survives. Same fake battler and the same nil-on-failure contract, which
  # leaves the core on switch_matchup's type proxy exactly as before.
  def self.switch_outgoing_damage(ai, battle, pokemon, foe_indices)
    fake = (ai.pbMakeFakeBattler(pokemon) rescue nil)
    return nil if !fake
    best = 0.0
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe || foe.isFainted?
      (pokemon.moves || []).each do |own|
        next if !own || own.id == 0
        # 0.6.4 (switch_estimate_pp). A move with no PP left is not a hit this body
        # has. The field view drops it (pbCanChooseMove?), this estimate did not, so in
        # a long stall war -- Quagsire and Chansey in front of a Zapdos at turn 89,
        # every Scald and Seismic Toss spent -- the bench body "hit for 27%" while the
        # same body on the field hit for nothing, and the two traded places on
        # weak_current_attacks until the round cap. Its own PP is its own information.
        next if own.respond_to?(:pp) && own.pp.to_i <= 0 && rule_enabled?("switch_estimate_pp")
        move = (PokeBattle_Move.pbFromPBMove(battle, own, fake) rescue nil)
        next if !move
        damage = rough_damage_pct(ai, move, fake, foe)
        best = damage if damage > best
      end
    end
    best
  rescue
    nil
  end

  # Whether the candidate would outrun every current foe once it is in. A benched
  # Pokemon has no battler and therefore no pbSpeed, so this reads the party entry's
  # own Speed stat -- no stages, which is right: a switch-in enters at stage 0.
  def self.switch_candidate_faster(battle, pokemon, foe_indices)
    speed = (pokemon.speed rescue nil)
    return nil if speed.nil?
    faster_than_foes?(battle, speed, foe_indices)
  rescue
    nil
  end

  # Best offensive type matchup of a benched Pokemon into the current foes.
  # Reborn's static chart is per-type neutral 2, combined neutral 4 (two type slots);
  # Realidea's combined neutral is 8 (three slots) with a x4 weight, so weight x8 here
  # to hand the core the same magnitudes (neutral 32, super-effective 64, double 128).
  def self.switch_matchup(pokemon, battle, foe_indices)
    best = 0
    (pokemon.moves || []).each do |pokemon_move|
      next if !pokemon_move || pokemon_move.id == 0
      data = PBMoveData.new(pokemon_move.id) rescue nil
      next if !data || data.basedamage <= 0
      total = 0
      foe_indices.each do |foe_index|
        foe = battle.battlers[foe_index]
        total += PBTypes.getCombinedEffectiveness(data.type, foe.type1, foe.type2)
      end
      best = total if total > best
    end
    best * 8
  rescue
    0
  end

  # The mirror of switch_matchup: how hard the foe hits the candidate coming in.
  # switch_matchup asks only what the incoming Pokemon can dish out, which is why
  # Portable's switch-ins took 33.5% of their HP on the entry turn against
  # Reborn-Normal's 26.5% over ~406 measured switches — it picks a good attacker and
  # never asks what that attacker will eat.
  #
  # Scored off the foe's own types rather than its moveset, so this stays inside the
  # fair-information contract: a player can see the opposing species and infer its STAB
  # without having been shown its moves. Same units as switch_matchup (x8, so neutral is
  # 32), and the worst foe is taken rather than the sum — in a double the incoming
  # Pokemon eats both, but the one that hits hardest is what decides whether it lives.
  def self.switch_incoming_risk(pokemon, battle, foe_indices)
    worst = 0
    types = [pokemon.type1, pokemon.type2].compact.uniq
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe
      [foe.type1, foe.type2].compact.uniq.each do |attacking|
        value = PBTypes.getCombinedEffectiveness(attacking, types[0], types[-1])
        worst = value if value > worst
      end
    end
    worst * 8
  rescue
    0
  end

  # Reborn's own type verdict, ability- and field-aware. Neutral is 4; 0 is immune and
  # -1 is an absorb ability (heals/boosts the target) — both are "do not click" for a
  # damaging move, so both map to 0.0.
  def self.type_effectiveness(ai, move, attacker, target)
    return 1.0 if !target || move.basedamage <= 0
    raw = ai.pbTypeModNoMessages(
      (move.pbType(attacker) rescue move.type), attacker, target, move,
      PokeBattle_AI::BESTSKILL
    )
    return 0.0 if raw.nil? || raw <= 0
    raw.to_f / TYPEMOD_NEUTRAL
  rescue
    1.0
  end

  def self.rough_damage_pct(ai, move, attacker, target)
    return 0.0 if !target || move.basedamage <= 0
    damage = ai.pbRoughDamage(move, attacker, target, false, false)
    return 0.0 if !damage || damage <= 0
    percent(damage, target.totalhp)
  rescue
    0.0
  end

  # Hit chance 0-100 as the engine itself computes it, including ability, weather and
  # accuracy/evasion stages (PokeBattle_AI_2.rb:9965). It reads @mondata.skill, which
  # with_neutral_estimation has already staged, and returns 100 for never-miss moves.
  # nil when the primitive is unavailable, which the core reads as "do not discount".
  def self.rough_accuracy(ai, move, attacker, target)
    return nil if !target
    value = ai.pbRoughAccuracy(move, attacker, target)
    return nil if value.nil?
    value.to_f
  rescue
    nil
  end

  def self.battler_speed(battler)
    return nil if !battler
    (battler.pbSpeed rescue battler.speed)
  rescue
    nil
  end

  # Reborn's own convention (pbAIfaster?, :10055): strictly greater is faster, a tie is
  # not, and Trick Room inverts the comparison. nil when either speed is unavailable,
  # which every rule reading it treats as "unknown, do not penalise".
  def self.faster_than_foes?(battle, speed, foe_indices)
    return nil if speed.nil?
    fastest = nil
    foe_indices.each do |foe_index|
      foe_speed = battler_speed(battle.battlers[foe_index])
      next if foe_speed.nil?
      fastest = foe_speed if fastest.nil? || foe_speed > fastest
    end
    return nil if fastest.nil?
    trick_room = (battle.trickroom.to_i != 0 rescue false)
    trick_room ? speed < fastest : speed > fastest
  end

  # Fair-information caveat carried over from the Realidea adapter: this inspects the
  # foe's actual move objects rather than a revealed-move memory model.
  def self.estimated_incoming_damage(ai, battle, battler, foe_indices)
    maximum = 0.0
    incoming_damage_by_move(ai, battle, battler, foe_indices).each_value do |damage|
      maximum = damage if damage > maximum
    end
    maximum
  end

  # Every foe move's estimated hit on this battler, keyed "<foe index>:<move id>".
  # The maximum is what the threat rules read; the whole map goes into the trace view
  # so a later diagnosis can compare the estimate for the move the foe actually used
  # against the damage it actually did.
  def self.incoming_damage_by_move(ai, battle, battler, foe_indices)
    out = {}
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      # A Choice item that has already locked in is a CERTAINTY about what is coming,
      # and the strongest one available: the foe cannot use anything else until it
      # switches. Reborn reads the same effect when it scores switch-ins (:11377) but
      # NOT when it scores moves, which the probe caught -- Skarmory scored Roost at 0
      # behind a Heatran locked into a move it is immune to, because the threat model
      # still contained the Flamethrower it could not use. This is a deliberate
      # departure from the reference, on the strict_threat side of the ledger.
      locked = safe_effect(foe, :ChoiceBand, -1).to_i
      foe.moves.each do |known|
        next if !known || known.id == 0
        next if locked >= 0 && known.id != locked
        out["#{foe_index}:#{known.id}"] = rough_damage_pct(ai, known, foe, battler)
      end
    end
    out
  end

  # The same incoming_map, resolved PER FOE and with the two extra facts a hits-to-KO
  # question needs: the best hit that foe has, the best one it has that moves first,
  # and whether it outruns this battler. incoming_by_move is keyed "foe:moveid" with no
  # priority, and actor["faster"] is against the FASTEST foe only -- in doubles that is
  # the wrong flag for the slower target, and a race computed off it is wrong.
  #
  # Keyed by foe index as a STRING, because the core reads it out of a plain Hash that
  # has been through JSON in the Realidea build.
  def self.threats_by_foe(ai, battle, battler, foe_indices, incoming_map)
    speed = battler_speed(battler)
    configured = (defined?($PORTABLE_AI_CONFIG) && $PORTABLE_AI_CONFIG ?
      $PORTABLE_AI_CONFIG : {})
    outcome_details = battle.doublebattle &&
      (PortableAI::Model.truthy(configured["doubles_outcomes"]) ||
       PortableAI::Model.truthy(configured["doubles_search"]))
    out = {}
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe || foe.isFainted?
      locked = safe_effect(foe, :ChoiceBand, -1).to_i
      best = 0.0
      best_priority = 0.0
      best_accuracy = 100.0
      best_move_priority = 0
      best_priority_accuracy = 100.0
      foe.moves.each do |known|
        next if !known || known.id == 0
        next if locked >= 0 && known.id != locked
        # Reuse the map the actor already paid for; fall back for anything not in it.
        damage = incoming_map["#{foe_index}:#{known.id}"]
        damage = rough_damage_pct(ai, known, foe, battler) if damage.nil?
        damage = PortableAI::Model.number(damage, 0.0)
        priority = effective_priority(battle, known, foe, battler)
        if damage > best
          best = damage
          best_accuracy = rough_accuracy(ai, known, foe, battler) if outcome_details
          best_move_priority = priority
        end
        next if priority <= 0
        if damage > best_priority
          best_priority = damage
          best_priority_accuracy = rough_accuracy(ai, known, foe, battler) if outcome_details
        end
      end
      out[foe_index.to_s] = {
        "damage_pct" => best,
        "accuracy" => best_accuracy,
        "priority" => best_move_priority,
        "priority_damage_pct" => best_priority,
        "priority_accuracy" => best_priority_accuracy,
        "faster" => faster_than_foes?(battle, speed, [foe_index])
      }
    end
    out
  rescue
    {}
  end

  # The largest incoming hit that cannot fail to happen: the foe is not asleep (with
  # sleep still to serve) or frozen, and the move never misses as the engine computes
  # its hit chance. The core's "you die whatever you click" rules read this under
  # strict_threat; the loose maximum stays for the soft rules. Set_c showed the loose
  # figure was wrong 72% of the time exactly when one of these two conditions held.
  def self.certain_incoming_damage(ai, battle, battler, foe_indices, incoming_map)
    maximum = 0.0
    foe_indices.each do |foe_index|
      foe = battle.battlers[foe_index]
      next if !foe || !foe_can_act?(foe)
      foe.moves.each do |known|
        next if !known || known.id == 0
        damage = incoming_map["#{foe_index}:#{known.id}"]
        next if !damage || damage <= 0
        accuracy = rough_accuracy(ai, known, foe, battler)
        next if !accuracy.nil? && accuracy < 100
        maximum = damage if damage > maximum
      end
    end
    maximum
  end

  def self.foe_can_act?(foe)
    status = foe.status
    return false if status == PBStatuses::FROZEN
    if status == PBStatuses::SLEEP
      count = (foe.statusCount rescue 0).to_i
      # One turn left means it wakes and acts this turn.
      return false if count > 1
    end
    true
  rescue
    true
  end

  def self.any_choosable_move?(battle, index)
    battler = battle.battlers[index]
    return false if !battler
    battler.moves.each_with_index do |move, slot|
      next if !move || move.id == 0
      return true if battle.pbCanChooseMove?(index, slot, false)
    end
    false
  rescue
    false
  end

  def self.has_legal_switch?(battle, index)
    party = battle.pbParty(index)
    party.each_with_index do |pokemon, slot|
      return true if pokemon && battle.pbCanSwitch?(index, slot, false)
    end
    false
  rescue
    false
  end

  def self.reserve_count(battle, index)
    count = 0
    party = battle.pbParty(index)
    party.each_with_index do |pokemon, slot|
      next if !pokemon || pokemon.hp <= 0 || pokemon.isEgg?
      active = battle.battlers.any? do |battler|
        battler && battle.pbIsOpposing?(battler.index) == battle.pbIsOpposing?(index) &&
          battler.pokemonIndex == slot && !battler.isFainted?
      end
      count += 1 if !active
    end
    count
  rescue
    0
  end

  def self.hazard_target_count(battle, move_id, actor_index)
    party = battle.pbParty(actor_index ^ 1)
    count = 0
    party.each do |pokemon|
      next if !pokemon || pokemon.hp <= 0 || pokemon.isEgg?
      # Heavy-Duty Boots and Magic Guard walk over every hazard, so a party wearing
      # them is a party the move cannot touch. Reborn's Spikes and Toxic Spikes
      # branches skip Boots holders (:4603, :4633) and its Stealth Rock branch does
      # not look at the party at all -- measured, Spikes collapse to 0 against an
      # all-Boots party while Stealth Rock stays at 45. Applied to every hazard here,
      # because the asymmetry is a gap in the reference and not a rule.
      next if item_key(pokemon) == "HEAVYDUTYBOOTS"
      next if pokemon_ability?(pokemon, :MAGICGUARD)
      airborne = pokemon_has_type?(pokemon, :FLYING) || pokemon_ability?(pokemon, :LEVITATE)
      if move_id == "SPIKES" || move_id == "STICKYWEB"
        count += 1 if !airborne
      elsif move_id == "TOXICSPIKES"
        immune_type = pokemon_has_type?(pokemon, :POISON) || pokemon_has_type?(pokemon, :STEEL)
        count += 1 if !airborne && !immune_type
      else
        count += 1
      end
    end
    count
  rescue
    1
  end

  # Hazards this battler would lay land on the opposing half of the field.
  def self.existing_layers(battler, move_id)
    side = battler.pbOpposingSide
    case move_id
    when "SPIKES"       then safe_side_effect(side, :Spikes, 0)
    when "TOXICSPIKES"  then safe_side_effect(side, :ToxicSpikes, 0)
    when "STEALTHROCK"  then safe_side_effect(side, :StealthRock, false) ? 1 : 0
    when "STICKYWEB"    then safe_side_effect(side, :StickyWeb, false) ? 1 : 0
    else 0
    end
  end

  def self.max_layers(move_id)
    return 3 if move_id == "SPIKES"
    return 2 if move_id == "TOXICSPIKES"
    1
  end

  # Universal status-immunity facts, computed from engine type data. Kind tags come
  # from the canonical effects table; "typed_status" additionally consults the
  # engine's own type verdict (Thunder Wave vs Ground and ability absorbs).
  # Universal facts about a non-damaging move that make it unusable. Four sources,
  # in order of how much they know:
  #
  # 1. Magic Bounce on the target OR its partner reflects every status move
  #    (Reborn returns -1 for the whole move, :2828).
  # 2. Prankster gives status moves priority and a Dark type ignores them entirely
  #    (Reborn returns a flat 0, :3324).
  # 3. The status itself: ask the ENGINE's own can-status check rather than the type
  #    list this used to carry. pbCanBurn?/pbCanPoison?/pbCanParalyze?/pbCanSleep?/
  #    pbCanFreeze?/pbCanConfuse? already know about Misty and Electric Terrain,
  #    Safeguard, Leaf Guard, Comatose, Purifying Salt, Good as Gold, Overcoat and
  #    Sweet Veil against powder, Limber, Water Veil, Immunity, Insomnia and Vital
  #    Spirit -- none of which a type list can see. The list stays as the rescue path
  #    for an engine that does not expose them.
  def self.status_blocked?(ai, move, tags, battler, target)
    return false if !target
    return false if !tags.include?("status")
    return true if magic_bounced?(target)
    if ability_key(battler) == "PRANKSTER" && battler_has_type?(target, :DARK)
      return true
    end
    if tags.include?("typed_status")
      raw = ai.pbTypeModNoMessages(
        (move.pbType(battler) rescue move.type), battler, target, move,
        PokeBattle_AI::BESTSKILL
      ) rescue nil
      return true if raw && raw <= 0
    end
    # 4. Leech Seed carries the "status" tag but sets no status CONDITION -- it writes
    #    PBEffects::LeechSeed -- so the core's major-status guard never sees it and
    #    there is no pbCanLeechSeed? to ask, which left a seeded foe looking fresh and
    #    the move collecting fresh_status+25 every turn. Mirror the engine's own three
    #    failure conditions from PokeBattle_Move_0DC#pbEffect
    #    (PokeBattle_MoveEffects.rb:6194): already seeded, behind a Substitute, or
    #    Grass-type. "drain" is carried by LEECHSEED alone (effects.rb:58).
    if tags.include?("drain")
      return true if safe_effect(target, :LeechSeed, -1).to_i >= 0
      return true if safe_effect(target, :Substitute, 0).to_i > 0
      return true if battler_has_type?(target, :GRASS)
    end
    # 5. Yawn is the same shape one move over. It is tagged ["status", "sleep"]
    #    (effects.rb:56), so engine_can_status? asks pbCanSleep? -- which answers about
    #    the status CONDITION and says yes about a target that is merely drowsy. The
    #    engine's second guard is a separate line the AI never reads:
    #    PokeBattle_Move_004#pbEffect (PokeBattle_MoveEffects.rb:249) displays "But it
    #    failed!" and returns -1 when effects[PBEffects::Yawn] > 0. Checked BEFORE
    #    engine_can_status? for the same reason the Leech Seed clause is: the engine
    #    check would otherwise return a confident, wrong "yes".
    if tags.include?("drowsy") && rule_enabled?("yawn_gate")
      return true if safe_effect(target, :Yawn, 0).to_i > 0
    end
    verdict = engine_can_status?(tags, target)
    return !verdict if !verdict.nil?
    return true if tags.include?("burn") && battler_has_type?(target, :FIRE)
    return true if tags.include?("poison") &&
                   (battler_has_type?(target, :POISON) || battler_has_type?(target, :STEEL))
    return true if tags.include?("powder") && battler_has_type?(target, :GRASS)
    return true if tags.include?("paralyze") && battler_has_type?(target, :ELECTRIC)
    false
  rescue
    false
  end

  # true/false from the engine, or nil when this move applies no status the engine can
  # be asked about (so the caller falls through to the type list).
  def self.engine_can_status?(tags, target)
    return target.pbCanBurn?(false)      if tags.include?("burn")
    return target.pbCanPoison?(false)    if tags.include?("poison")
    return target.pbCanParalyze?(false)  if tags.include?("paralyze")
    return target.pbCanSleep?(false)     if tags.include?("sleep")
    return target.pbCanFreeze?(false)    if tags.include?("freeze")
    return target.pbCanConfuse?(false)   if tags.include?("confuse")
    nil
  rescue
    nil
  end

  def self.magic_bounced?(target)
    return true if ability_key(target) == "MAGICBOUNCE"
    partner = (target.pbPartner rescue nil)
    return true if partner && !partner.isFainted? && ability_key(partner) == "MAGICBOUNCE"
    false
  rescue
    false
  end

  def self.battler_has_type?(battler, symbol)
    battler.pbHasType?(symbol)
  rescue
    type = (PBTypes.const_get(symbol) rescue nil)
    return false if type.nil?
    battler.type1 == type || battler.type2 == type
  end

  def self.positive_stages(target)
    return 0 if !target
    total = 0
    target.stages.each { |stage| total += stage if stage && stage > 0 }
    total
  rescue
    0
  end

  def self.opposing_hazard_layers(battler)
    side = battler.pbOpposingSide
    safe_side_effect(side, :Spikes, 0).to_i +
      safe_side_effect(side, :ToxicSpikes, 0).to_i +
      (safe_side_effect(side, :StealthRock, false) ? 1 : 0) +
      (safe_side_effect(side, :StickyWeb, false) ? 1 : 0)
  rescue
    0
  end

  def self.own_hazard_layers(battler)
    side = battler.pbOwnSide
    safe_side_effect(side, :Spikes, 0).to_i +
      safe_side_effect(side, :ToxicSpikes, 0).to_i +
      (safe_side_effect(side, :StealthRock, false) ? 1 : 0) +
      (safe_side_effect(side, :StickyWeb, false) ? 1 : 0)
  rescue
    0
  end

  def self.effect_active?(battler, move_id)
    side = battler.pbOwnSide
    case move_id
    when "REFLECT"     then safe_side_effect(side, :Reflect, 0).to_i > 0
    when "LIGHTSCREEN" then safe_side_effect(side, :LightScreen, 0).to_i > 0
    when "SAFEGUARD"   then safe_side_effect(side, :Safeguard, 0).to_i > 0
    when "SUBSTITUTE"  then safe_effect(battler, :Substitute, 0).to_i > 0
    # 0.6.2. Wish fails outright with a Wish already pending
    # (PokeBattle_MoveEffects.rb:6084). PBEffects::Wish is the countdown on the USER,
    # not a side effect, which is why it is read off the battler here.
    when "WISH"        then safe_effect(battler, :Wish, 0).to_i > 0
    else false
    end
  end

  # Did THIS move fail last turn against THIS target?
  #
  # The engine keeps the answer itself: pbProcessMoveAgainstTarget writes
  # effects[PBEffects::Tantrum] = (pbEffect returned -1) after every move use
  # (PokeBattle_Battler.rb:5085, and :4961-4966 for a move with no target), holds it
  # for Stomping Tantrum to read, and clears it on switch-in (:619). It is the same
  # flag the gauntlet event log renders as "failed" (Portable_AI_Gauntlet.rb:362).
  #
  # It is deliberately NOT successStates[index].useState, which the backlog entry
  # proposed. useState is set to 2 only on the DAMAGING path (:5362), so a status move
  # that worked perfectly reads back as "1 = failed" and every Swords Dance would be
  # charged for succeeding.
  #
  # Tantrum alone says only that SOMETHING failed, so it is paired with the portable
  # memory's record of what was clicked and at whom: a re-click is only charged when
  # the move id matches and the target is the same Pokemon. A target that switched out
  # is a new board and the memory of the failure does not carry to it.
  def self.failed_last_turn?(battle, battler, move_id, target)
    return false if !safe_effect(battler, :Tantrum, false)
    memory = battle.instance_variable_get(:@portable_ai_memory) || {}
    state = memory[battler.index.to_s]
    return false if !state || state["last_move"] != move_id
    last_species = state["last_target_species"]
    return false if target && !last_species.nil? && last_species != target.species
    true
  rescue
    false
  end

  # Rough entry cost on this battler's own side (what a switch-in would eat).
  # Reborn's combined-effectiveness neutral is 4, hence /4 where Realidea used /8.
  def self.entry_hazard_pct(pokemon, battler)
    side = battler.pbOwnSide
    # The other half of the Boots rule: a holder pays nothing to come in.
    return 0 if item_key(pokemon) == "HEAVYDUTYBOOTS"
    return 0 if pokemon_ability?(pokemon, :MAGICGUARD)
    spikes = safe_side_effect(side, :Spikes, 0).to_i
    damage = [0, 12.5, 16.7, 25.0][spikes] || 25.0
    if pokemon_has_type?(pokemon, :FLYING) || pokemon_ability?(pokemon, :LEVITATE)
      damage = 0
    end
    if safe_side_effect(side, :StealthRock, false)
      rock = (PBTypes.const_get(:ROCK) rescue nil)
      if rock
        effectiveness = PBTypes.getCombinedEffectiveness(
          rock, pokemon.type1, pokemon.type2
        )
        damage += 12.5 * effectiveness.to_f / TYPEMOD_NEUTRAL
      else
        damage += 12.5
      end
    end
    damage
  rescue
    0
  end

  def self.pokemon_has_type?(pokemon, symbol)
    pokemon.hasType?(symbol)
  rescue
    type = (PBTypes.const_get(symbol) rescue nil)
    return false if !type
    pokemon.type1 == type || pokemon.type2 == type
  end

  def self.pokemon_ability?(pokemon, symbol)
    value = (PBAbilities.const_get(symbol) rescue nil)
    return false if !value
    (pokemon.ability rescue nil) == value
  end

  def self.safe_effect(battler, name, fallback)
    return fallback if !PBEffects.const_defined?(name)
    battler.effects[PBEffects.const_get(name)]
  rescue
    fallback
  end

  def self.safe_side_effect(side, name, fallback)
    return fallback if !PBEffects.const_defined?(name)
    side.effects[PBEffects.const_get(name)]
  rescue
    fallback
  end

  # Uppercase type name ("FIRE"), the same shape the core's absorb and redirect tables
  # are keyed by. Built once from PBTypes, like move_key.
  def self.type_key(id)
    return nil if id.nil?
    if !defined?(@type_keys) || !@type_keys
      @type_keys = {}
      PBTypes.constants.each do |name|
        value = PBTypes.const_get(name) rescue nil
        @type_keys[value] = name.to_s.upcase if value.is_a?(Integer)
      end
    end
    @type_keys[id]
  end

  # Ability and item names as uppercase strings, resolved through the CONSTANT tables
  # rather than through PBAbilities.getName / PBItems.getName.
  #
  # getName goes to the compiled message file, and the test environment the probe and
  # the gauntlet both run in has no message data: it returns an empty string for every
  # id (the same reason debuglog.txt shows blank species names). The first 0.5.0 build
  # used getName, and the result was that ability_key returned "" for everything, so
  # every ability and item row in all four tables silently did nothing -- 22 corpus
  # cards failed under Portable while passing under stock Reborn. The constants are
  # compiled into the module itself and are always there.
  def self.ability_key(battler_or_pokemon)
    value = (battler_or_pokemon.ability rescue nil)
    return nil if value.nil? || value == 0
    constant_key(PBAbilities, :@ability_keys, value)
  rescue
    nil
  end

  def self.item_key(battler_or_pokemon)
    value = (battler_or_pokemon.item rescue nil)
    return nil if value.nil? || value == 0
    constant_key(PBItems, :@item_keys, value)
  rescue
    nil
  end

  def self.constant_key(namespace, cache_name, value)
    cache = instance_variable_get(cache_name)
    if !cache
      cache = {}
      namespace.constants.each do |name|
        id = namespace.const_get(name) rescue nil
        cache[id] = name.to_s.upcase if id.is_a?(Integer)
      end
      instance_variable_set(cache_name, cache)
    end
    cache[value]
  rescue
    nil
  end

  # Which attacking stat this battler actually hits with. The burn, paralysis and
  # stat-drop rows all ask it, and Reborn asks the same question with pbRoughStat
  # (burncode:5662).
  def self.attack_bias(ai, battler)
    attack = (ai.pbRoughStat(battler, PBStats::ATTACK) rescue nil)
    special = (ai.pbRoughStat(battler, PBStats::SPATK) rescue nil)
    return [false, false] if attack.nil? || special.nil?
    [attack > special, special > attack]
  rescue
    [false, false]
  end

  # kind / stat / chance for one move against one target, all three from the engine.
  # The chance is the move's own addlEffect, doubled by Serene Grace and zeroed when
  # the engine says the secondary is negated (Sheer Force, Shield Dust, Covert Cloak) —
  # the same three checks Reborn makes in secondaryEffectNegated? (:17430).
  def self.move_effect(ai, move, battler, target)
    code = (move.function rescue nil)
    return [nil, nil, nil] if code.nil?
    entry = MOVE_EFFECT_CODES[code]
    return [nil, nil, nil] if !entry
    chance = (move.addlEffect rescue 0).to_i
    # A status MOVE (Will-O-Wisp, Toxic, Thunder Wave) carries addlEffect 0 because the
    # status is its whole point, not a secondary; those are certain.
    chance = 100 if move.basedamage <= 0 || chance <= 0
    if target && move.basedamage > 0
      negated = (ai.secondaryEffectNegated?(move, battler, target) rescue false)
      return [entry[0], entry[1], 0] if negated
      chance *= 2 if (battler.ability == PBAbilities::SERENEGRACE rescue false)
    end
    # A secondary that cannot land is worth nothing, and only the engine knows why not
    # -- a Fire type cannot burn, Misty Terrain blocks everything, Purifying Salt and
    # Good as Gold and Safeguard each block their own share. status_blocked? asks the
    # same question but only ever ran for NON-damaging moves, which left Scald scoring
    # its burn bonus into an Arcanine.
    if target
      verdict = engine_can_status?([entry[0]], target)
      return [entry[0], entry[1], 0] if verdict == false
    end
    chance = 100 if chance > 100
    [entry[0], entry[1], chance]
  rescue
    [nil, nil, nil]
  end

  def self.multi_hit?(move)
    return true if (move.pbIsMultiHit rescue false)
    MULTI_HIT_CODES.include?((move.function rescue nil))
  rescue
    false
  end

  def self.move_key(id)
    if !defined?(@move_keys) || !@move_keys
      @move_keys = {}
      PBMoves.constants.each do |name|
        value = PBMoves.const_get(name) rescue nil
        @move_keys[value] = name.to_s.upcase if value.is_a?(Integer)
      end
    end
    @move_keys[id] || id.to_s
  end

  def self.weather_name(battle)
    weather = battle.pbWeather rescue battle.weather
    return "rain" if defined?(PBWeather::RAINDANCE) && weather == PBWeather::RAINDANCE
    return "rain" if defined?(PBWeather::HEAVYRAIN) && weather == PBWeather::HEAVYRAIN
    return "sun" if defined?(PBWeather::SUNNYDAY) && weather == PBWeather::SUNNYDAY
    return "sun" if defined?(PBWeather::HARSHSUN) && weather == PBWeather::HARSHSUN
    return "sand" if defined?(PBWeather::SANDSTORM) && weather == PBWeather::SANDSTORM
    return "hail" if defined?(PBWeather::HAIL) && weather == PBWeather::HAIL
    "none"
  end

  def self.percent(value, total)
    return 0.0 if !total || total.to_f <= 0
    value.to_f * 100.0 / total.to_f
  end

  def self.average(values)
    return 0.0 if values.empty?
    values.inject(0.0) do |sum, value|
      sum + PortableAI::Model.number(value, 0)
    end / values.length
  end

  def self.apply_action(battle, index, action)
    if action["type"] == "switch"
      return battle.pbRegisterSwitch(index, action["slot"])
    end
    return false if !battle.pbRegisterMove(index, action["slot"], false)
    target = action["target"]
    battle.pbRegisterTarget(index, target) if !target.nil? && battle.doublebattle
    true
  end

  def self.apply_memory(battle, index, action)
    memory = battle.instance_variable_get(:@portable_ai_memory) || {}
    state = memory[index.to_s] || {}
    selected_key = nil
    if action["type"] == "switch"
      selected_key = "switch"
    else
      tags = PortableAI::Effects.describe(action["move_id"], action["tags"])
      if tags.include?("setup")
        selected_key = "setup"
      elsif tags.include?("protect") || tags.include?("team_protect")
        selected_key = "protect"
      elsif tags.include?("substitute")
        selected_key = "substitute"
      end
    end
    previous_count = selected_key ? state[selected_key].to_i : 0
    %w[setup protect substitute switch].each { |key| state[key] = 0 }
    if action["type"] == "switch"
      state["switch"] = previous_count + 1
    else
      state[selected_key] = previous_count + 1 if selected_key
      state["last_move"] = action["move_id"]
      # Who it was aimed at, so failed_last_turn? can tell "this failed against this
      # Pokemon" from "this failed against the one that has since switched out".
      state["last_target_species"] = action["target_species"]
    end
    state["last_type"] = action["type"]
    memory[index.to_s] = state
    battle.instance_variable_set(:@portable_ai_memory, memory)
  end

  def self.log_error(error)
    signature = "#{error.class}: #{error.message}"
    return if defined?(@last_error) && @last_error == signature
    @last_error = signature
    File.open(ERROR_FILE, "ab") do |file|
      file.write("#{signature}\n")
      file.write(error.backtrace[0, 8].join("\n") + "\n") if error.backtrace
    end
  rescue
  end
end

class PokeBattle_Battle
  def portable_ai_last_plan
    @portable_ai_last_plan
  end
end

class PokeBattle_AI
  if !method_defined?(:portable_ai_orig_chooseAction)
    alias_method :portable_ai_orig_chooseAction, :chooseAction
  end

  def chooseAction
    PortableAIReborn.register_side(self)
    portable_ai_orig_chooseAction
  end
end
